"use strict";(globalThis.webpackChunkistqb_quiz=globalThis.webpackChunkistqb_quiz||[]).push([[495],{495(e){e.exports=JSON.parse('[{"id":1001,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following is a common objective of software testing?  ","options":["Confirm that the software meets the specified requirements.","Ensure there are no errors in the source code.","Demonstrate that the system is completely secure against external attacks.","Verify that all users are satisfied with the product."],"correctAnswer":0,"explanation":"Confirming compliance with requirements is a common objective (syllabus 1.1). Testing cannot ensure there are no errors (false), nor that it is completely secure or that everyone is satisfied.","source":"Pr\xe1ctica Adicional"},{"id":1002,"chapter":1,"topic":"Fundamentals of Testing","question":"A software company develops applications for the financial sector. The management team asks the test manager\\n\\nwhy testing is essential in their context, beyond finding defects. Which of the following reasons BEST describes why testing is necessary in this context?","options":["To demonstrate that the software has no defects before delivery.","To provide confidence about the software quality level and comply with the sector\'s regulatory requirements.","To replace the requirements review process and reduce documentation.","To ensure that all developers know the entire system code."],"correctAnswer":1,"explanation":"In the financial sector, providing confidence and complying with regulations is vital. Testing cannot demonstrate the absence of defects (absence-of-defects fallacy principle).","source":"Pr\xe1ctica Adicional"},{"id":1003,"chapter":1,"topic":"Fundamentals of Testing","question":"You are evaluating the quality of the testing performed on a software before its release. You observe that although many tests have been run, significant defects still persist.\\n\\nWhich of the seven testing principles is reflected in this situation?","options":["Exhaustive testing is impossible","Defects cluster together","Tests wear out","Absence-of-defects fallacy"],"correctAnswer":1,"explanation":"Defects tend to cluster in specific modules (defect cluster or Pareto).","source":"Pr\xe1ctica Adicional"},{"id":1007,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following skills is essential for a tester\\n\\nwhen evaluating the quality of a software product?\\n\\ni. Effective communication\\n\\nii. Technical knowledge\\n\\niii. Analytical ability\\n\\niv. Time management","options":["i and ii are essential; iii and iv are not","iii and iv are essential; i and ii are not","ii and iii are essential; i and iv are not","i and iii are essential; ii and iv are not"],"correctAnswer":3,"explanation":"Effective communication and analytical ability (i and iii) are paramount according to the syllabus for reporting problems and designing tests, although ii and iv also help.","source":"Pr\xe1ctica Adicional"},{"id":1008,"chapter":1,"topic":"Fundamentals of Testing","question":"What is a key advantage of the whole-team approach in the software development process?  ","options":["It promotes isolated communication between testers and developers.","It facilitates collaboration among all stakeholders from the start of the project.","It increases testing duration by requiring extensive reviews.","It eliminates the need for a well-defined test strategy."],"correctAnswer":1,"explanation":"The whole-team approach fosters mutual collaboration of all profiles from the start.","source":"Pr\xe1ctica Adicional"},{"id":1038,"chapter":1,"topic":"Fundamentals of Testing","question":"You are evaluating the quality of the testing performed on a software before its release. You observe that although many tests have been run, significant defects still persist.\\n\\nWhich of the seven testing principles is reflected in this situation?","options":["Exhaustive testing is impossible","Defects cluster together","Tests wear out","Absence-of-defects fallacy"],"correctAnswer":1,"explanation":"This principle indicates that a small number of components can contain most of the defects (clustering), which explains why significant localized defects persist.","source":"Errores Reportados - Set 2"},{"id":1039,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following skills (i-v) are essential for a tester in their daily work?\\n\\ni. Ability to write clear reports\\n\\nii. Knowledge of programming languages\\n\\niii. Risk analysis ability\\n\\niv. Being a good communicator\\n\\nv. Knowing automation tools  ","options":["i, iii and iv are essential; ii and v are not","ii, iii and v are essential; i and iv are not","i, ii and iv are essential; iii and v are not","iii, iv and v are essential; i and ii are not"],"correctAnswer":0,"explanation":"Writing reports (i), risk analysis (iii), and communication (iv) are essential skills (basic soft and hard skills). Programming and automation are desirable but not strictly essential for every daily tester.","source":"Errores Reportados - Set 2"},{"id":1043,"chapter":1,"topic":"Fundamentals of Testing","question":"You are reviewing the progress of a software project and notice that defects have been fixed, but no new tests have been performed. The project manager is satisfied with the results, but you are concerned about quality.\\n\\nWhich testing principle could justify your concern?","options":["Tests wear out","Absence-of-defects fallacy","Defects cluster together","Exhaustive testing is impossible"],"correctAnswer":1,"explanation":"It refers to the mistaken belief that simply fixing existing defects means there are no other problems in the system (absence-of-defects fallacy), which is misleading without new tests validating it against the requirements.","source":"Errores Reportados - Set 2"},{"id":1068,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following options best describes\\n\\nwhy testing is necessary in software development?","options":["Testing helps identify errors before the software is delivered to users.","Testing is only a requirement to comply with quality regulations.","Testing is only necessary if there is a change in the software requirements.","Testing guarantees that the software will work on all available devices."],"correctAnswer":0,"explanation":"A. Correct. Testing is essential to identify and fix errors before end users use the software. B. Incorrect. Its main value lies in identifying defects and improving quality. C. Incorrect. Testing should be performed regardless of whether there are changes in requirements. D. Incorrect. It cannot be guaranteed that the software will work on all devices.","source":"Generadas (Why Testing)"},{"id":1069,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following is a typical objective of software testing?  ","options":["Ensure that the software meets all customer requirements.","Identify defects in the software before its release.","Test all possible combinations of system inputs.","Guarantee that the system is completely free of errors."],"correctAnswer":1,"explanation":"A. Incorrect. Testing cannot ensure full compliance with all requirements. B. Correct. A fundamental objective of testing is to identify defects before the software is released. C. Incorrect. Testing all combinations is impractical (testing principle 2). D. Incorrect. It is impossible to guarantee that a system is completely free of errors.","source":"Generadas (Test Objectives)"},{"id":1070,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following contexts could modify the approach of the testing process in a software project?\\n\\ni. The type of client and their expectations,\\n\\nii. The experience of the development team,\\n\\niii. The duration of the project,\\n\\niv. The development methodology used.  ","options":["i and ii are contexts that modify the testing approach","ii and iii are contexts that modify the testing approach","i, iii and iv are contexts that modify the testing approach","ii, iv are contexts that modify the testing approach"],"correctAnswer":2,"explanation":"C. Correct. The type of client (i) influences the approach; the project duration (iii) affects planning; and the development methodology (iv) impacts the type of testing to be performed. These three carry more weight than team experience alone.","source":"Generadas (Context)"},{"id":1071,"chapter":1,"topic":"Fundamentals of Testing","question":"Which context elements can alter the test strategy in a project?\\n\\ni. The experience of the test team,\\n\\nii. The budget available for testing,\\n\\niii. The automation tools used,\\n\\niv. The team\'s organizational culture.  ","options":["i, ii, iii alter the test strategy","ii, iii, iv alter the test strategy","i, iii, iv alter the test strategy","i, ii, iv alter the test strategy"],"correctAnswer":1,"explanation":"B. Correct. The budget (ii) directly affects test planning and execution. Automation tools (iii) can change the way testing is performed. Organizational culture (iv) influences communication and collaboration. These three are the most decisive in altering the strategy.","source":"Generadas (Context)"},{"id":1072,"chapter":1,"topic":"Fundamentals of Testing","question":"During a test review, you notice that similar tests are being used in different projects without any adaptation. This has resulted in a high success rate but many overlooked defects.\\n\\nWhich testing principle could explain this situation?","options":["Exhaustive testing is impossible","Tests wear out","Defects cluster together","Absence-of-defects fallacy"],"correctAnswer":1,"explanation":"A. Incorrect. This principle is about possible data combinations. B. Correct. Tests wear out (Pesticide Paradox): the same tests repeated without adaptation lose effectiveness and stop finding new defects. C. Incorrect. Defect clustering is about the concentration of defects in specific modules. D. Incorrect. The fallacy refers to the mistaken belief that no defects means the software is perfect.","source":"Generadas (Test Principles)"},{"id":1073,"chapter":1,"topic":"Fundamentals of Testing","question":"During a project, the team believes their software is perfect because they have not received error reports in weeks. As a tester, you know this does not guarantee quality.\\n\\nWhich testing principle reflects this situation?","options":["The absence-of-defects fallacy","Tests wear out","Defects cluster together","Exhaustive testing is impossible"],"correctAnswer":0,"explanation":"A. Correct. This principle indicates that the absence of reported defects does not mean the software is defect-free, as it can lead to a false sense of security. B. Incorrect. This principle refers to repetitive tests losing effectiveness. C. Incorrect. This principle is about defect concentration. D. Incorrect. This principle is about the impossibility of testing all combinations.","source":"Generadas (Test Principles)"},{"id":1074,"chapter":1,"topic":"Fundamentals of Testing","question":"Which skills are essential for a tester\\n\\nwhen working in an agile team?\\n\\ni. Active listening,\\n\\nii. Deep technical knowledge,\\n\\niii. Effective communication,\\n\\niv. Ability to work under pressure.","options":["i and iii are essential; ii and iv are not","i, ii and iv are essential; iii is not","iii and iv are essential; i and ii are not","i, ii and iii are essential; iv is not"],"correctAnswer":3,"explanation":"D. Correct. Active listening (i), deep technical knowledge (ii), and effective communication (iii) are fundamental skills for a tester in an agile team. The ability to work under pressure (iv) is less decisive as a generic testing skill according to ISTQB.","source":"Generadas (Tester Skills)"},{"id":1075,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following skills (i-v) is ESSENTIAL for a tester?\\n\\ni. Risk analysis,\\n\\nii. Effective communication,\\n\\niii. Technical programming knowledge,\\n\\niv. Creativity,\\n\\nv. Time management.  ","options":["i and ii are essential; iii, iv and v are not","iii and iv are essential; i, ii and v are not","ii and v are essential; i, iii and iv are not","i, ii and iv are essential; iii and v are not"],"correctAnswer":3,"explanation":"D. Correct. Risk analysis (i) and effective communication (ii) are fundamental skills, and creativity (iv) also plays an important role in identifying quality problems. Deep technical knowledge (iii) and time management (v) are less decisive as essential skills.","source":"Generadas (Tester Skills)"},{"id":1076,"chapter":1,"topic":"Fundamentals of Testing","question":"In a software development project, the team is reviewing the test approach for a new user management feature.\\n\\nWhich of the following activities is part of test design?","options":["Describe the acceptance criteria for the user management feature.","Review the system requirements to identify possible test conditions.","Execute the defined test cases to verify the user management feature.","Create test cases from the requirements and design the associated test conditions."],"correctAnswer":3,"explanation":"A. Incorrect. Describing acceptance criteria is part of requirements specification. B. Incorrect. Reviewing requirements is part of test analysis. C. Incorrect. Executing test cases is part of the execution phase. D. Correct. Creating test cases and designing test conditions are key activities in test design.","source":"Generadas (Test Design)"},{"id":250,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following statements describes a valid test objective?  ","options":["A) Prove no defects exist","B) Prove no failures will happen","C) Reduce risk level and build confidence","D) Verify all combinations are tested"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#1, LO: FL-1.1.1). Rationale: Reduce the risk level of the test object and build confidence in the quality level D) Verify that there are no untested combinations of inputs","source":"Official Sample Exam A Q#1"},{"id":251,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following shows an example of testing activities that contribute to success?  ","options":["A) Involve testers during various activities","B) Do not bother developers","C) Collaborate with end users","D) Test all system code with tools"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#2, LO: FL-1.2.1). Rationale: Involving testers during various software development life cycle (SDLC) activities will help detect defects in work products","source":"Official Sample Exam A Q#2"},{"id":252,"chapter":1,"topic":"Fundamentals of Testing","question":"You have been assigned as a tester to a team that produces a new system incrementally. You have noticed that no changes have been made to existing regression test cases for several iterations and no new regression defects have been identified. Your manager is happy, but you are not.\\n\\nWhat principle of proof explains your skepticism?","options":["A) Tests wear out","B) Fallacy of the absence of defects","C) Defects are grouped together","D) Exhaustive testing is impossible"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#3, LO: FL-1.3.1). Rationale: Evidence wears out","source":"Official Sample Exam A Q#3"},{"id":253,"chapter":1,"topic":"Fundamentals of Testing","question":"You work on a team that develops a mobile app for ordering food. In the current iteration, the team decided to implement payment functionality.\\n\\nWhich of the following activities is part of test analysis?","options":["A) Estimate that testing the integration with the payment service will take 8 person-days","B) Decide that the team should test whether it is possible to share the payment appropriately among many users","C) Use boundary value analysis (BVA) to derive test data for test cases that verify correct payment processing for the minimum amount allowed to be paid","D) Analyze the discrepancy between the actual result and the expected result after running a test case that verifies the credit card payment process, and report a defect"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#4, LO: FL-1.4.1). Rationale: Decide that the team should test whether it is possible to share the payment appropriately among many users","source":"Official Sample Exam A Q#4"},{"id":254,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following factors have a SIGNIFICANT influence on the testing approach? Yo. The SDLC\\n\\nii. The number of defects detected in previous projects\\n\\niii. The identified product risks\\n\\niv. New regulatory requirements mandating formal white box testing\\n\\nv. Setting up the test environment  ","options":["A) i, ii have a significant influence","B) i, iii, iv have a significant influence","C) ii, iv, v have a significant influence","D) iii, v have a significant influence"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#5, LO: FL-1.4.2). Rationale: i, iii, iv have significant influence","source":"Official Sample Exam A Q#5"},{"id":255,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following tasks PRIMARILY belong to a testing role?","options":["A) Set up environments and Analyze test basis","B) Maintain backlog and Design solutions","C) Design solutions and Create test plan","D) Maintain backlog and Set up environments"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#6, LO: FL-1.4.5). Rationale: Set up test environments","source":"Official Sample Exam A Q#6"},{"id":256,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following skills (i-v) are MOST important for a tester? Yo. Have knowledge of the domain\\n\\nii. Create a product vision\\n\\niii. Be a good team player\\n\\niv. Plan and organize the team\'s work\\n\\nv. Critical thinking  ","options":["A) ii and iv are important","B) i, iii and v are important","C) i, ii and v are important","D) iii and iv are important"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#7, LO: FL-1.5.1). Rationale: i, iii and v are important","source":"Official Sample Exam A Q#7"},{"id":257,"chapter":1,"topic":"Fundamentals of Testing","question":"How is the whole-team approach present in interactions between testers and business representatives?  ","options":["A) Business representatives decide test automation approaches","B) Testers help business representatives define a testing strategy","C) Business representatives are not part of the entire team\'s focus","D) Testers help business representatives create proper acceptance tests"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#8, LO: FL-1.5.2). Rationale: Testers help business representatives create proper acceptance tests","source":"Official Sample Exam A Q#8"},{"id":289,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following is an example of\\n\\nwhy testing is necessary?","options":["A) Dynamic testing increases quality by making test objects fail in ways that users could never achieve","B) Static tests are used by developers to identify bugs in their code earlier than can be achieved through dynamic testing","C) Static analysis provides evidence to customers that system elements that do not provide outputs are suitable for release","D) Revisions increase the quality of the requirements specifications and lead to fewer changes being needed in the derived work products"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample B, Q#1, LO: FL-1.2.1). Rationale: Revisions increase the quality of requirements specifications and lead to fewer changes being needed in derived work products.","source":"Official Sample Exam B Q#1"},{"id":290,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following statements about quality assurance (QA) and/or quality control (QC) is correct?  ","options":["A) QA is performed as part of testing","B) Testing is performed as part of QC","C) Testing is another term for QC","D) Testing is performed as part of QA"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#2, LO: FL-1.2.2). Rationale: Testing is performed as part of QC.","source":"Official Sample Exam B Q#2"},{"id":291,"chapter":1,"topic":"Fundamentals of Testing","question":"One of the \'testing principles\' states that exhaustive testing is impossible.\\n\\nWhich of the following is an example of how to address this principle in practice?","options":["A) Create test cases that cover every possible specified output","B) Document all possible test input variations and prioritize them by importance","C) Start testing as early as possible with reviews and other static testing approaches","D) Use equivalence partitioning and boundary value analysis to generate test cases"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#3, LO: FL-1.3.1). Rationale: Use equivalence partitioning and boundary value analysis to generate test cases.","source":"Official Sample Exam B Q#3"},{"id":292,"chapter":1,"topic":"Fundamentals of Testing","question":"Which test activity involves working with test data requirements, test conditions, test environment requirements, and test cases?  ","options":["A) Test design","B) Test execution","C) Test analysis","D) Test implementation"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#4, LO: FL-1.4.1). Rationale: Test design.","source":"Official Sample Exam B Q#4"},{"id":293,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following is MOST likely to impact\\n\\nhow testing is performed for a given test object?","options":["A) The average experience level of the organization\'s marketing team","B) Users\' knowledge that a new system is being developed for them","C) The number of years of experience of the test team members","D) The end-user organizational structure for a commercial music streaming application"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#5, LO: FL-1.4.2). Rationale: The number of years of experience of the test team members.","source":"Official Sample Exam B Q#5"},{"id":294,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following statements is a CORRECT example of the value of traceability?  ","options":["A) Traceability between mitigated risks and passed test cases provides a means to determine the level of residual risk","B) Traceability between user requirements and test results provides a means to measure project progress against business objectives","C) Traceability between testers and failed test cases provides a means to determine the testers\' skill level","D) Traceability between identified risks and written test conditions provides a means to determine which risks are worth testing"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#6, LO: FL-1.4.4). Rationale: Traceability between user requirements and test results provides a means to measure project progress against business objectives.","source":"Official Sample Exam B Q#6"},{"id":295,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following is MOST likely an example of a tester using a generic skill\\n\\nwhen testing?","options":["A) The tester\'s deep knowledge of a variety of computer games meant they got along with one of the developers who was also a gamer","B) The tester was a former pilot and was better able to understand the acceptance criteria for the helicopter control system","C) The tester previously worked as a programmer and used their skills in this area to communicate better with the business analysts","D) The tester was very careful not to make mistakes when methodically generating test cases before starting their exploratory testing session"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#7, LO: FL-1.5.1). Rationale: The tester was a former pilot and was better able to understand the acceptance criteria for the helicopter control system.","source":"Official Sample Exam B Q#7"},{"id":296,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following is an advantage of the whole-team approach?  ","options":["A) It allows team members to take on any role at any time","B) It only needs a single team to support the entire development project","C) It integrates business representatives together with developers in the same team","D) It generates team synergy that benefits the entire project"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#8, LO: FL-1.5.2). Rationale: The whole-team approach generates synergy that benefits the entire project.","source":"Official Sample Exam B Q#8"},{"id":328,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following is a typical test objective?  ","options":["A) Validate that documented requirements are met","B) Cause failures and identify defects","C) Trigger errors and identify root causes","D) Verify that the test object meets user expectations"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#1, LO: FL-1.1.1). Rationale: A typical test objective is to cause failures in order to identify defects in the software.","source":"Official Sample Exam C Q#1"},{"id":329,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following statements BEST describes the difference between testing and debugging?  ","options":["A) Testing causes failures while debugging fixes them","B) Testing is a negative activity while debugging is positive","C) Testing determines that defects exist while debugging removes them","D) Testing finds the cause of defects while debugging fixes it"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#2, LO: FL-1.1.2). Rationale: Testing determines the existence of defects (through failures); debugging locates the root cause and removes it.","source":"Official Sample Exam C Q#2"},{"id":330,"chapter":1,"topic":"Fundamentals of Testing","question":"The \'absence-of-defects fallacy\' is one of the testing principles.\\n\\nWhich of the following is an example of how to address this principle in practice?","options":["A) Explain that it is not possible for testing to prove the absence of defects","B) Support end users in performing acceptance testing","C) Ensure that no implementation defect remains in the delivered system","D) Modify the tests that do not cause failures to make sure few defects remain"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#3, LO: FL-1.3.1). Rationale: Supporting end users in acceptance testing ensures the system meets their real needs, addressing the fallacy that \'no defects = correct system\'.","source":"Official Sample Exam C Q#3"},{"id":331,"chapter":1,"topic":"Fundamentals of Testing","question":"Which test activities are MOST LIKELY the ones that involve applying boundary value analysis and equivalence partitioning?  ","options":["A) Test implementation","B) Test design","C) Test execution","D) Test monitoring"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#4, LO: FL-1.4.1). Rationale: Test design techniques such as boundary value analysis and equivalence partitioning are applied during test design.","source":"Official Sample Exam C Q#4"},{"id":332,"chapter":1,"topic":"Fundamentals of Testing","question":"Given the following testware:\\n\\nWhich of the following BEST shows the testware produced by each activity?\\n\\n1. Coverage items\\n2. Change requests\\n3. Test execution schedule\\n4. Prioritized test conditions\\n\\nA. Test analysis  \\nB. Test design  \\nC. Test implementation  \\nD. Test completion","options":["A) 1B, 2D, 3C, 4A","B) 1B, 2D, 3A, 4C","C) 1D, 2C, 3A, 4B","D) 1D, 2C, 3B, 4A"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#5, LO: FL-1.4.3). Rationale: Coverage items are produced in design (1B), change requests in completion (2D), the schedule in implementation (3C), and prioritized conditions in analysis (4A).","source":"Official Sample Exam C Q#5"},{"id":333,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following statements about the different test roles is MOST LIKELY CORRECT?  ","options":["A) In agile software development, the test management role is mainly the team\'s responsibility, while the testing role is the responsibility of a single external individual","B) The testing role is mainly responsible for test monitoring and control, while the management role is responsible for planning and completion","C) In agile software development, test management activities spanning multiple teams are handled by an external test manager, while some management tasks are taken on by the team itself","D) The test management role is mainly responsible for test analysis and design, while the testing role is responsible for implementation and execution"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#6, LO: FL-1.4.5). Rationale: In Agile, management activities affecting several teams are coordinated by an external manager, while the team manages its own test activities internally.","source":"Official Sample Exam C Q#6"},{"id":334,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following statements about test independence is CORRECT?  ","options":["A) Independent testers will find defects thanks to their technical perspective different from the developers\', although their independence can create an antagonistic relationship","B) Developers\' familiarity with their own code means they find only few defects; however, their training being similar to testers\' means testers would also find them","C) Independent testing requires testers from outside the development team and ideally from outside the organization, although these people have difficulty understanding the application domain","D) Testers from outside the developer\'s team are more independent, but those inside the team are more likely to be blamed for delivery delays"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#8, LO: FL-1.5.3). Rationale: Independence brings a different perspective that helps find more defects, but can create tensions with the development team.","source":"Official Sample Exam C Q#8"},{"id":363,"chapter":1,"topic":"Fundamentals of Testing","question":"A designer documents a design for a user interface that does not adequately serve visually impaired users because the designer was unaware of the accessibility requirements.\\n\\nHow is this classified according to ISTQB terminology?","options":["A) The designer made a failure that introduced an error in the design","B) The designer made an error (mistake) that introduced a defect in the design","C) The designer made a defect that resulted in a failure in the design","D) The designer made an error that introduced a failure in the design"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#1, LO: FL-1.2.2). Rationale: The designer\'s lack of knowledge (human error) leads to a defect in the design document. Terminology: Error -> Defect -> Failure.","source":"Official Sample Exam D Q#2"},{"id":364,"chapter":1,"topic":"Fundamentals of Testing","question":"Testers use test conditions to generate test cases and run tests. Although the test conditions remain the same, the test cases vary each time.\\n\\nWhich of the \'testing principles\' is being applied by varying the test cases?","options":["A) Tests wear out (pesticide paradox)","B) The absence-of-defects fallacy","C) Early testing saves time and money","D) Defects cluster together"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#3, LO: FL-1.3.1). Rationale: The pesticide paradox (or \'tests wear out\') indicates that repeating the same test cases stops detecting new defects, which is why they must be varied.","source":"Official Sample Exam D Q#3"},{"id":365,"chapter":1,"topic":"Fundamentals of Testing","question":"Given the following testware:\\n\\ni. Test completion report\\n\\nii. Data in a database used as inputs and expected results\\n\\niii. List of items needed to build the test environment\\n\\niv. Documented sequences of test cases in execution order\\n\\nv. Test cases.\\n\\nWhich of the following BEST shows the testware produced as a result of performing test implementation?","options":["A) ii, iv","B) iii, v","C) i, ii, v","D) i, iii, iv"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#5, LO: FL-1.4.3). Rationale: During test implementation, test data (ii) and execution sequences/test suites (iv) are created.","source":"Official Sample Exam D Q#5"},{"id":366,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following options MOST LIKELY describes a task performed by someone in a test management role?  ","options":["A) Evaluate the test basis and the test object","B) Define the test environment requirements","C) Evaluate the testability of the test object","D) Create the test completion report"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#6, LO: FL-1.4.5). Rationale: Creating the test completion report is a process-closing task, typically the responsibility of the test manager.","source":"Official Sample Exam D Q#6"},{"id":367,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following is an advantage of the whole-team approach?  ","options":["A) It improves communication among team members","B) It decreases individual responsibility for quality","C) It speeds up the deployment of deliverables to end users","D) It reduces collaboration with external business users"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#7, LO: FL-1.5.2). Rationale: The whole-team approach promotes collaboration among all team members, improving communication.","source":"Official Sample Exam D Q#7"},{"id":368,"chapter":1,"topic":"Fundamentals of Testing","question":"Given the following benefits and drawbacks of test independence:\\n\\ni. Testers work in a different location from the developers\\n\\nii. Testers question the assumptions programmers make\\n\\nwhen writing code\\n\\niii. A confrontational dynamic has been established between testers and developers\\n\\niv. Developers have become convinced that testers are mainly responsible for quality\\n\\nv. Testers have different biases from the developers. Which are MOST LIKELY considered benefits?","options":["A) i, iv","B) ii, v","C) i, iii, iv","D) ii, iii, v"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#8, LO: FL-1.5.3). Rationale: Questioning assumptions (ii) and having different biases (v) are benefits of independence; the others are drawbacks or negative consequences.","source":"Official Sample Exam D Q#8"},{"id":399,"chapter":1,"topic":"Fundamentals of Testing","question":"Given the following test tasks:\\n\\nWhat is the BEST match?\\n\\n1. Derive test cases from conditions\\n2. Identify reusable testware\\n3. Organize test cases into procedures\\n4. Evaluate the test basis\\n\\nA. Analysis  \\nB. Design  \\nC. Implementation  \\nD. Completion","options":["A) 1B, 2A, 3D, 4C","B) 1B, 2D, 3C, 4A","C) 1C, 2A, 3B, 4D","D) 1C, 2D, 3A, 4B"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#4, LO: FL-1.4.1). Rationale: 1B, 2D, 3C, 4A.","source":"Official Sample Exam D Q#4"},{"id":407,"chapter":1,"topic":"Fundamentals of Testing","question":"Your team detected 45 defects in module A (5,000 lines of code) and 12 defects in module B (8,000 lines). According to the \'defect clustering\' principle,\\n\\nwhich conclusion is the MOST correct?","options":["A) Module B is riskier because it has more code","B) Module A has a higher defect density and should receive more testing effort","C) Both modules have the same risk level","D) Defects are evenly distributed between both modules"],"correctAnswer":1,"explanation":"Module A has a density of 45/5000=0.009 defects/line vs B with 12/8000=0.0015. The clustering principle indicates that defects concentrate in a few modules; A deserves greater effort.","source":"banco"},{"id":408,"chapter":1,"topic":"Fundamentals of Testing","question":"A tester runs the same set of regression tests for 6 consecutive sprints without modifications. According to ISTQB principles,\\n\\nwhat problem arises and what is the solution?","options":["A) There is no problem; regression tests should be stable","B) Pesticide paradox: the tests stop finding new defects; review and update the test set","C) Absence of defects: the software no longer has bugs","D) Early testing generates accumulated false positives"],"correctAnswer":1,"explanation":"The pesticide paradox states that if the same tests are repeated without changes, they eventually stop finding new defects. The solution is to periodically review and update the tests.","source":"banco"},{"id":419,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following is an example of NON-functional testing?  ","options":["A) Verify that login rejects incorrect passwords","B) Check that the home page loads in less than 3 seconds with 500 concurrent users","C) Validate that the VAT calculation is correct","D) Confirm that the \'Save\' button stores the data in the database"],"correctAnswer":1,"explanation":"Non-functional tests evaluate quality attributes such as performance, usability, and security. Option B is a performance (load) test, which is non-functional.","source":"banco"},{"id":429,"chapter":1,"topic":"Fundamentals of Testing","question":"Your company develops flight control software. The cost of failure is catastrophic.\\n\\nWhich of the following ISTQB principles justifies investing more in testing than in low-risk projects?","options":["A) Exhaustive testing is possible with enough resources","B) Testing is context dependent: the level of rigor must match the risk and consequences of failure","C) Absence of defects is a fallacy","D) Early testing saves time and money"],"correctAnswer":1,"explanation":"The \'Testing is context dependent\' principle states that the test approach, techniques, and intensity vary according to the domain, risk, and consequences. Critical software requires greater rigor.","source":"banco"},{"id":430,"chapter":1,"topic":"Fundamentals of Testing","question":"During system testing, a defect is found in the billing module. The developer fixes it. Afterward, the tester discovers that the fix introduced a new error in the inventory module.\\n\\nWhat is this type of introduced defect called?","options":["A) Regression defect","B) Integration defect","C) Mutation defect","D) Confirmation defect"],"correctAnswer":0,"explanation":"A regression defect is one inadvertently introduced by a change (such as a bug fix). Regression testing is specifically designed to detect them.","source":"banco"},{"id":440,"chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following activities is the responsibility of the Test Manager (not the individual Tester)?  ","options":["A) Run test cases","B) Report defects found","C) Coordinate the test strategy and communicate status to the project","D) Design specific test data"],"correctAnswer":2,"explanation":"The Test Manager coordinates, plans, monitors, and controls test activities, defines strategy, and communicates progress. Individual testers execute, design cases, and report defects.","source":"banco"},{"id":446,"chapter":1,"topic":"Fundamentals of Testing","question":"According to ISTQB CTFL v4.0,\\n\\nwhat are the 7 testing principles?","options":["A) Testing shows the presence of defects; exhaustive testing is impossible; early testing; defect clustering; pesticide paradox; testing is context dependent; the absence-of-defects fallacy","B) Testing removes all defects; exhaustive testing is possible; testing at the end; uniform defects; testing is not context dependent","C) There are only 4 principles in ISTQB v4.0","D) The 7 principles include: mandatory automation, agile testing, CI/CD, shift-left, shift-right, DevOps, and TDD"],"correctAnswer":0,"explanation":"The 7 ISTQB principles are: 1) Testing shows the presence of defects 2) Exhaustive testing is impossible 3) Early testing saves money 4) Defect clustering 5) Pesticide paradox 6) Testing is context dependent 7) Absence-of-defects fallacy.","source":"banco"},{"id":454,"chapter":1,"topic":"Fundamentals of Testing","question":"PRACTICAL CASE: The team has run 500 tests and found 0 defects. The product owner wants to release the software claiming it \'is bug-free\'.\\n\\nWhat is your response based on ISTQB principles?","options":["A) You agree, 500 tests with no defects is enough evidence","B) Tests only show that no defects were found with that test set; they cannot prove their total absence (Principle 1). Releasing has residual risk","C) You must add 500 more tests to be sure","D) Request exhaustive testing of all possible paths"],"correctAnswer":1,"explanation":"ISTQB Principle 1: \'Testing shows the presence of defects, not their absence\'. 0 defects in 500 tests does not guarantee bug-free software, only that this test set did not find them. Residual risk always exists.","source":"banco"},{"id":460,"chapter":1,"topic":"Fundamentals of Testing","question":"What best describes the concept of \'shift-left\' in testing?  ","options":["A) Moving the tests to the left side of the screen","B) Starting test activities earlier in the development life cycle","C) Reducing the number of testers on the team","D) Automating all regression tests"],"correctAnswer":1,"explanation":"Shift-left means moving test activities earlier (to the left on the timeline): reviewing requirements, doing component testing sooner, using TDD/ATDD, etc. The goal is to detect defects earlier to reduce costs.","source":"banco"},{"id":466,"chapter":1,"topic":"Fundamentals of Testing","question":"What is the difference between verification and validation in testing?  ","options":["A) They are exactly the same","B) Verification: are we building the product correctly? Validation: are we building the right product?","C) Verification is done by users; validation by testers","D) Verification is dynamic; validation is static"],"correctAnswer":1,"explanation":"Verification checks that the product meets its specifications (\'are we building it right?\'). Validation checks that the product satisfies the user\'s real needs (\'are we building the right thing?\').","source":"banco"},{"id":"q_batch2_1thtnzqjs","chapter":1,"topic":"Fundamentals of Testing","question":"What skills are essential for a tester in the context of software testing? Understanding the customer\'s requirements Developing programming skills Performing only manual testing Clearly communicating the test findings  ","options":["i and iv are essential; ii and iii are not","ii and iii are essential; i and iv are not","i and ii are essential; iii and iv are not","ii and iv are essential; i and iii are not"],"correctAnswer":0,"explanation":"A. i. True. Understanding the customer\'s requirements is fundamental to ensuring tests are effective. iv. True. Communicating findings is crucial in the testing process. ii. False. Although developing programming skills can be useful, it is not essential for all testers. iii. False. Performing only manual testing limits the tester\'s approach and is not the only way to test. B, C and D are incorrect because they classify some of these skills the wrong way (i and iv are the essential ones).","source":"banco-extra"},{"id":"q_batch2_3ur6idl31","chapter":1,"topic":"Fundamentals of Testing","question":"What is a key reason\\n\\nwhy testing is necessary in software development?","options":["To ensure that the software meets the customer\'s requirements.","To increase the project\'s development time.","To decrease end-user satisfaction.","To reduce collaboration between development teams."],"correctAnswer":0,"explanation":"A. This option is correct because testing helps verify that the software works as expected and meets the customer\'s needs. B. Incorrect. Testing is designed to identify problems and errors, which can help reduce development time in the long run. C. Incorrect. Testing is intended to improve software quality, which generally increases end-user satisfaction. D. Incorrect. Testing should not decrease collaboration, but rather foster communication and teamwork to achieve a quality product.","source":"banco-extra"},{"id":"q_batch2_7tzjynf4k","chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following statements describes a benefit of obtaining early and frequent feedback from stakeholders?  ","options":["It allows for more exhaustive testing at the end of the development cycle.","It facilitates the early identification of problems and necessary adjustments.","It reduces the number of intermediate deliveries to the client.","It increases the complexity of the development process."],"correctAnswer":1,"explanation":"A. Incorrect. Obtaining early feedback is not about performing exhaustive testing at the end, but about addressing problems earlier in the process. B. Correct. Early and frequent feedback allows problems to be identified in time, which facilitates necessary adjustments. C. Incorrect. Frequent feedback can in fact increase the number of intermediate deliveries to ensure requirements are being met. D. Incorrect. Early feedback seeks to simplify the process by clarifying requirements and expectations with stakeholders.","source":"banco-extra"},{"id":"q_batch2_butb18o4u","chapter":1,"topic":"Fundamentals of Testing","question":"Which of the following elements can modify the test approach in a software project?\\n\\ni. The number of employees in the company\'s commercial area\\nii. The complexity of the software to be tested\\niii. The budget assigned to the project\\niv. The use of automated tools","options":["i, ii, iii can modify the test approach","ii, iii, iv can modify the test approach","i, iii, iv can modify the test approach","i, ii, iv can modify the test approach"],"correctAnswer":1,"explanation":"A. Incorrect. i. False: the number of employees in the commercial area is not a test context factor according to the CTFL v4.0 syllabus, section 1.4.2. ii, iii, and iv are true. By including i, this option is incorrect. B. Correct. i. False: the number of employees in the commercial area is not a test context factor. ii. True: software complexity is a product characteristic recognized as a context factor (syllabus 1.4.2). iii. True: budget constraints are operational factors explicitly listed (syllabus 1.4.2). iv. True: available tools are part of the technical context factors (syllabus 1.4.2). C. Incorrect. By including i (false), this option is incorrect. D. Incorrect. By including i (false), this option is incorrect.","source":"banco-extra"},{"id":"q_batch2_il2jaia8g","chapter":1,"topic":"Fundamentals of Testing","question":"What is one of the most significant advantages of the whole-team approach in the testing process?  ","options":["It improves communication and collaboration among all team members.","It allows testers to work in isolation to focus better on their tasks.","It reduces the need for extensive documentation in the testing process.","It facilitates the assignment of test tasks to different departments."],"correctAnswer":0,"explanation":"A. Correct. The whole-team approach fosters communication and collaboration among testers, developers, and business representatives, resulting in a more effective testing process. B. Incorrect. The whole-team approach emphasizes teamwork, not isolation. C. Incorrect. Although it can reduce the need for documentation, the whole-team approach does not focus on eliminating it completely. D. Incorrect. The whole-team approach promotes collaboration rather than assigning tasks across separate departments.","source":"banco-extra"},{"id":1009,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements best describes the importance of testing in the software development life cycle (SDLC)?  ","options":["Testing is performed only at the end of the SDLC to verify the final product.","Testing should be planned and performed throughout the entire SDLC to detect problems early.","Testing is optional and only needed if the client requests it.","Testing focuses only on the software\'s functionality and not on other aspects."],"correctAnswer":1,"explanation":"Testing throughout the entire SDLC (shift-left) is key to detecting and fixing problems as early as possible.","source":"Pr\xe1ctica Adicional"},{"id":1010,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following descriptions BEST relates to test-driven development (TDD)?  ","options":["In TDD, tests are written before the code and used to guide development.","In TDD, developers first create the code and then the corresponding test cases.","In TDD, tests are performed only at the end of the development cycle to verify the product.","In TDD, acceptance test cases are used as the basis for code design."],"correctAnswer":0,"explanation":"TDD consists of writing the (unit) tests before writing the source code that makes them pass.","source":"Pr\xe1ctica Adicional"},{"id":1011,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements best describes\\n\\nhow the \'shift-left\' approach can improve software quality?","options":["It allows defects to be detected and fixed in later stages of the development life cycle.","It facilitates continuous integration and early delivery of value to the client by finding errors early.","It increases the complexity of the development process by introducing more tests in the early phases.","It reduces the need for documentation by applying more user testing at the end of the cycle."],"correctAnswer":1,"explanation":"Moving testing to the left allows errors to be found earlier, improving integration and reducing costs.","source":"Pr\xe1ctica Adicional"},{"id":1012,"chapter":2,"topic":"Testing Throughout the SDLC","question":"What is a key benefit of holding retrospectives in a work team?  ","options":["They allow the team to ignore communication problems that may arise during the project.","They help identify and promote practices that have been effective in the past and can be applied in future cycles.","They are a formality that must be completed without generating any real impact on the project.","They make it easier for team leaders to take full control of the process without considering opinions."],"correctAnswer":1,"explanation":"Retrospectives are the engine of continuous improvement (identifying what worked and what did not).","source":"Pr\xe1ctica Adicional"},{"id":1013,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements adequately describe the test levels and their approaches?\\n\\n1. Validates complete functionality in a simulated production environment\\n2. Verifies that individual modules work\\n3. Ensures that modules integrate together\\n4. Validates requirements from the end user\'s perspective\\n\\nA. System testing  \\nB. Component testing  \\nC. Integration testing  \\nD. Acceptance testing","options":["1A, 2B, 3C, 4D","1C, 2A, 3D, 4B","1D, 2C, 3A, 4B","1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"1: System (A), 2: Components (B), 3: Integration (C), 4: Acceptance (D).","source":"Pr\xe1ctica Adicional"},{"id":1037,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Identify the following test categories (1-4) and the agile testing quadrants (A-D).\\n\\nWhich combinations are correct?\\n\\n1. Usability testing\\n2. Component testing\\n3. Functional testing\\n4. Reliability testing\\n\\nA (Q1). Technology / supports the team  \\nB (Q2). Business / supports the team  \\nC (Q3). Business / critiques the product  \\nD (Q4). Technology / critiques the product","options":["1C, 2A, 3B, 4D","1D, 2A, 3C, 4B","1C, 2B, 3D, 4A","1D, 2B, 3C, 4A"],"correctAnswer":0,"explanation":"Usability -> Q3 (1C). Components -> Q1 (2A). Functional -> Q2 (3B). Reliability -> Q4 (4D).","source":"Errores Reportados - Set 2"},{"id":1040,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements best describes the purpose of retrospectives in an agile team?  ","options":["Retrospectives are mainly used to plan the next tasks and assign responsibilities to team members.","Retrospectives help identify what worked and what did not, allowing the team to make adjustments to their process for continuous improvement.","Retrospectives are meetings where the final project results are presented to stakeholders.","Retrospectives are essential for evaluating customer satisfaction with the delivered product."],"correctAnswer":1,"explanation":"The main objective of retrospectives is to identify areas for improvement in the team\'s work process, fostering continuous improvement.","source":"Errores Reportados - Set 2"},{"id":1047,"chapter":2,"topic":"Testing Throughout the SDLC","question":"To\\n\\nwhich agile quadrant do performance, security, and reliability tests belong, and what is their main objective?","options":["Quadrant Q1; technology-oriented to support the team.","Quadrant Q3; business-oriented to critique the product.","Quadrant Q4; technology-oriented to critique the product.","Quadrant Q2; business-oriented to support the team."],"correctAnswer":2,"explanation":"Quality attribute tests (performance, security, reliability) are in Quadrant Q4. They are technology-oriented and their purpose is to \'critique the product\' (evaluate the product against technical metrics).","source":"Generadas (Agile/Metrics)"},{"id":1048,"chapter":2,"topic":"Testing Throughout the SDLC","question":"During the development of a sprint, the team performs exploratory testing and usability testing to evaluate the system from the real user\'s perspective. In\\n\\nwhich agile quadrant are these tests located?","options":["Q1 (Technology support, technology-oriented)","Q2 (Business support, business-oriented)","Q3 (Product critique, business-oriented)","Q4 (Product critique, technology-oriented)"],"correctAnswer":2,"explanation":"Exploratory and usability tests are part of Quadrant Q3. Their objective is to critique the product by evaluating it from the business-oriented perspective (the real user).","source":"Generadas (Agile/Metrics)"},{"id":1056,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements best describes the importance of testing in the software development life cycle (SDLC)?  ","options":["Testing is performed only at the end of the SDLC to verify the final product.","Testing should be planned and performed throughout the entire SDLC to detect problems early.","Testing is optional and only needed if the client requests it.","Testing focuses only on the software\'s functionality and not on other aspects."],"correctAnswer":1,"explanation":"A. Incorrect. Testing should be integrated into each phase of the SDLC, not just at the end. B. Correct. Planning and performing testing throughout the entire SDLC helps identify and resolve problems in time. C. Incorrect. Testing is fundamental and should not be optional. D. Incorrect. Testing should address both functionality and other aspects such as usability and performance.","source":"Generadas (SDLC)"},{"id":1058,"chapter":2,"topic":"Testing Throughout the SDLC","question":"What is one of the main advantages of holding periodic retrospectives in a development team?  ","options":["They allow team members to share their opinions about the final product without restrictions.","They facilitate the identification of communication patterns that can improve collaboration within the team.","They provide a space for the team to evaluate and adjust their work process based on what was learned in the previous cycle.","They help establish metrics to measure the performance of the finished product."],"correctAnswer":2,"explanation":"A. Incorrect. The main focus of retrospectives is on the process, not the product. B. Incorrect. Identifying communication patterns is not the main objective. C. Correct. Retrospectives are fundamental for the team to evaluate and adjust its process based on previous experience, contributing to continuous improvement. D. Incorrect. Retrospectives are not focused on establishing metrics for the product.","source":"Generadas (Retrospectivas)"},{"id":1059,"chapter":2,"topic":"Testing Throughout the SDLC","question":"What is a key benefit of holding retrospectives at the end of a project?  ","options":["Allowing team members to share their opinions about the project\'s latest delivery.","Generating an environment of criticism where only the team\'s errors are mentioned.","Facilitating the identification of lessons learned that can be applied in future projects.","Ensuring that all team members have the opportunity to speak without a clear focus on processes."],"correctAnswer":2,"explanation":"A. Incorrect. Although sharing opinions is part of retrospectives, the main focus is continuous improvement. B. Incorrect. Retrospectives should not be a space for negative criticism. C. Correct. Identifying lessons learned is fundamental to applying improvements in future projects. D. Incorrect. Retrospectives should have a clear focus on process improvement.","source":"Generadas (Retrospectivas)"},{"id":1060,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following descriptions is best associated with test-driven development (TDD)?  ","options":["In TDD, the test cases are created first and then the code is developed to pass them.","In TDD, the code is written and then manual tests are generated to verify its operation.","In TDD, testing is performed only after all functionality has been implemented.","In TDD, it focuses only on integration testing and not on unit testing."],"correctAnswer":0,"explanation":"A. Correct. TDD is based on the cycle of writing a test, making it fail, implementing the code, and then refactoring. B. Incorrect. In TDD, tests are part of the development process; they are not generated manually afterward. C. Incorrect. TDD implies that tests are written before implementing functionality. D. Incorrect. TDD focuses mainly on unit testing.","source":"Generadas (TDD)"},{"id":1061,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements BEST describes the unit test-driven development approach (TDD)?  ","options":["In TDD, tests are written after the code to validate its operation.","In TDD, tests are created first and then the necessary code is developed to pass them.","In TDD, developers focus on documentation instead of automated tests.","In TDD, the focus is exclusively on integration testing and not on unit testing."],"correctAnswer":1,"explanation":"A. Incorrect. In TDD, tests are written before the code, not after. B. Correct. In TDD, tests are written first and then the code is developed to meet those tests. C. Incorrect. TDD focuses on automated tests. D. Incorrect. TDD focuses on unit tests, not exclusively on integration tests.","source":"Generadas (TDD)"},{"id":1062,"chapter":2,"topic":"Testing Throughout the SDLC","question":"A team has fixed several defects and released a new version. Before the fix, some test cases failed. The team needs to verify that the defects have been fixed and that the changes have not affected other parts of the system.\\n\\nWhich of the following descriptions best fits the testing that will be carried out?","options":["Confirmation tests focus only on the test cases that previously failed.","Regression tests ensure that the functionalities that were not modified still work correctly.","Confirmation tests include the test cases that failed in previous versions and those that are run for the first time.","Regression tests only apply to new defects discovered in the new version."],"correctAnswer":1,"explanation":"A. Incorrect. Confirmation tests verify that the fixed defects work, but are not limited to the cases that failed. B. Correct. Regression tests verify that the modifications have not affected the existing functionalities. C. Incorrect. Confirmation tests only relate to the fixed defects. D. Incorrect. Regression tests apply to all existing functionalities.","source":"Generadas (Confirmation/Regression)"},{"id":1063,"chapter":2,"topic":"Testing Throughout the SDLC","question":"You have found defects in a new software feature and, after fixing them, you run tests again.\\n\\nWhat type of testing are you performing if you are validating that the defects have been fixed?","options":["Regression testing","Confirmation testing","Functional testing","Black-box testing"],"correctAnswer":1,"explanation":"A. Incorrect. Regression testing focuses on verifying that functionalities that already worked continue to work. B. Correct. Confirmation testing is performed to ensure that the identified defects have effectively been fixed. C. Incorrect. Functional testing evaluates the software\'s behavior against requirements. D. Incorrect. Black-box testing is not specifically related to defect fixing.","source":"Generadas (Confirmation/Regression)"},{"id":1064,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements BEST describes the purpose of system testing compared to integration testing? (1) System testing focuses on the behavior of the complete system as a whole. (2) Integration testing verifies the interaction between individual modules. (3) System testing is more specific and focuses on isolated components. (4) Integration testing is performed after acceptance testing.  ","options":["1 and 2 are correct","1 and 3 are correct","2 and 4 are correct","1, 2 and 3 are correct"],"correctAnswer":0,"explanation":"A. Correct. System testing evaluates the behavior of the complete system (1) and integration testing focuses on how the modules interact with each other (2). B. Incorrect. Statement 3 is false; system testing is not more specific. C. Incorrect. Statement 4 is false; integration testing is performed BEFORE acceptance testing. D. Incorrect. Statement 3 is incorrect.","source":"Generadas (Test Levels)"},{"id":1065,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following test levels mainly focuses on verifying the interaction between different system modules?  ","options":["Acceptance testing","System testing","Integration testing","Component testing"],"correctAnswer":2,"explanation":"A. Acceptance testing validates that the system meets user requirements from a business perspective. B. System testing verifies overall requirements compliance. C. Correct. Integration testing focuses on verifying how different modules interact, ensuring they work correctly together. D. Component testing verifies the operation of an individual module.","source":"Generadas (Test Levels)"},{"id":1066,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements best describes a benefit of the \'shift-left\' approach?  ","options":["It reduces the total life cycle cost by identifying defects later in the process.","It improves collaboration between development and testing teams from the start of the project.","It increases the amount of testing performed in the production environment.","It eliminates the need for manual testing at the end of the development cycle."],"correctAnswer":1,"explanation":"A. Incorrect. Shift-left seeks to identify defects early, which reduces costs. B. Correct. It fosters early collaboration between teams to detect and resolve problems sooner. C. Incorrect. Increasing testing in production is not a goal of shift-left. D. Incorrect. Although automation is sought, the approach does not eliminate manual testing.","source":"Generadas (Shift Left)"},{"id":1067,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements best describes\\n\\nhow the \'shift-left\' approach can improve software quality?","options":["It allows defects to be detected and fixed in later stages of the development life cycle.","It facilitates continuous integration and early delivery of value to the client.","It increases the complexity of the development process by introducing more tests in the early phases.","It reduces the need for documentation by applying more user testing at the end of the cycle."],"correctAnswer":1,"explanation":"A. Incorrect. Shift-left focuses on detecting defects as early as possible, not in later stages. B. Correct. This approach allows valuable software to be integrated and delivered to the client more quickly, improving quality from the start. C. Incorrect. The goal is to simplify the process by improving initial quality. D. Incorrect. Shift-left does not eliminate the need for documentation.","source":"Generadas (Shift Left)"},{"id":1080,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following activities is an example of the \'shift-left\' approach in the software development process?  ","options":["A) Performing code reviews after software development is complete.","B) Involving the test team in the early stages of the project to define acceptance criteria.","C) Carrying out integration testing once system implementation is complete.","D) Writing the user documentation only after development is complete."],"correctAnswer":1,"explanation":"B. Correct. Involving the test team from the start helps identify problems early.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1081,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements correctly describes the test-driven development (TDD) approach?  ","options":["A) In TDD, a test case that defines a desired function is written first, before developing the code.","B) In TDD, tests are created after software development is complete.","C) In TDD, it focuses on performance testing and not on unit testing.","D) In TDD, test cases are irrelevant to the development process."],"correctAnswer":0,"explanation":"A. Correct. In TDD, a test case that guides code development is written first, promoting an iterative approach.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1082,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements BEST describes the test-driven development (TDD) methodology?  ","options":["A) In TDD, tests are written after software development is complete.","B) In TDD, a test that fails is created first before writing the code to make the test pass.","C) In TDD, only acceptance tests are developed at the end of the development cycle.","D) In TDD, the code and the tests are developed completely independently."],"correctAnswer":1,"explanation":"B. Correct. In TDD, a test that initially fails is written, which guides the subsequent development of the code.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1083,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements adequately describe the test levels (1-4) and their specific approaches (A-D)?\\n\\n1. Tests performed to validate the complete functionality of the system in a simulated production environment\\n2. Tests focused on verifying that individual modules work correctly\\n3. Tests that ensure the different modules integrate and work together\\n4. Tests involving the validation of requirements from the end user\'s perspective\\n\\nA. System testing  \\nB. Component testing  \\nC. Integration testing  \\nD. Acceptance testing","options":["A) 1A, 2B, 3C, 4D","B) 1C, 2A, 3D, 4B","C) 1D, 2C, 3A, 4B","D) 1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"A. Correct. Statement 1 correctly describes system testing (1A), which validates the system as a whole. Statement 2 refers to component testing (2B). Statement 3 relates to integration testing (3C). Statement 4 corresponds to acceptance testing (4D).","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1084,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements best describes a benefit of holding retrospectives after each iteration in a work team?  ","options":["A) Retrospectives ensure that all team members agree on the decisions made during the iteration.","B) Retrospectives allow problems in the work process to be identified and addressed, thus facilitating continuous improvement.","C) Retrospectives are an opportunity for the team to celebrate their successes without focusing on areas for improvement.","D) Retrospectives are just a formality carried out to comply with the requirements of the agile framework."],"correctAnswer":1,"explanation":"B. Correct. Retrospectives are crucial for identifying problems and facilitating continuous improvement in the team\'s work process.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1085,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements best describes the purpose of a retrospective in an agile team?  ","options":["A) Retrospectives are meetings for the team to share completed tasks and plan the next sprint.","B) Retrospectives allow the team to reflect on what went well and what did not, and generate actions to improve in the future.","C) Retrospectives are sessions where team members\' shortcomings are discussed so they are not repeated.","D) Retrospectives are useful only at the end of the project to evaluate the team\'s overall performance."],"correctAnswer":1,"explanation":"B. Correct. The main objective of a retrospective is to reflect on the work done and find ways to improve the process for future sprints.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1086,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Imagine you have tested a new software feature and found some defects. After fixing those defects, you run a series of tests again.\\n\\nWhat type of testing are you performing if you are validating that the defects have been fixed?","options":["A) Regression testing","B) Confirmation testing","C) Functional testing","D) Black-box testing"],"correctAnswer":1,"explanation":"B. Correct. Confirmation testing is performed to ensure that the identified defects have effectively been fixed.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1087,"chapter":2,"topic":"Testing Throughout the SDLC","question":"A test team has run a set of tests on a new feature in an application. In the first run, defects were found and corrections were made. In the second test run, some of the tests were repeated.\\n\\nWhich of the following statements correctly describes the tests performed?","options":["A) The repeated tests are confirmation tests, while the tests of the new feature are regression tests.","B) The tests of the new feature are considered confirmation tests and the repeated tests are regression tests.","C) The repeated tests are confirmation tests and the tests of the new feature are regression tests.","D) All the tests run are regression tests."],"correctAnswer":2,"explanation":"C. Correct. The repeated tests validate corrections, classified as confirmation tests, while those of the new feature are considered regression tests.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":258,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Consider the following rule: \\"for every SDLC activity there is a corresponding test activity.\\" In\\n\\nwhich SDLC models does this rule apply?","options":["A) Only in sequential development models","B) Only in iterative development models","C) Only in iterative and incremental development models","D) In \u200b\u200bsequential, incremental and iterative development models"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#9, LO: FL-2.1.2). Justification: In sequential, incremental and iterative development models","source":"Official Sample Exam A Q#9"},{"id":259,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements BEST describes the acceptance test-driven development (ATDD) approach?  ","options":["A) In ATDD, acceptance criteria are generally created based on the given/when/then format.","B) In ATDD, test cases are mainly created in component tests and are code-oriented","C) In ATDD, tests are created based on acceptance criteria to guide the development of related software","D) In \u200b\u200bATDD, testing is based on the desired behavior of the software, making it easier for team members to understand"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#10, LO: FL-2.1.3). Rationale: In ATDD, tests are created based on acceptance criteria to guide the development of related software","source":"Official Sample Exam A Q#10"},{"id":260,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following is NOT an example of the shift-left approach?  ","options":["A) Review user requirements before they are formally accepted by stakeholders","B) Write a component test before the corresponding code is written","C) Run a performance efficiency test for a component during component testing","D) Write a test script before configuring the configuration management process"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#11, LO: FL-2.1.5). Rationale: Write a test script before configuring the configuration management process","source":"Official Sample Exam A Q#11"},{"id":261,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following arguments would you use to convince your manager to organize retrospectives?  ","options":["A) Retrospectives are very popular nowadays and clients would appreciate it if we added them to our processes","B) Hosting retrospectives will save the organization money because without them, end-user representatives do not provide immediate feedback on the product.","C) Process weaknesses identified during the retrospective can be analyzed and serve as a to-do list for the organization\'s continuous process improvement program.","D) Retrospectives encompass five values \u200b\u200bincluding courage and respect, which are crucial to maintaining continuous improvement in the organization."],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#12, LO: FL-2.1.6). Rationale: Process weaknesses identified during the retrospective can be analyzed and serve as a to-do list for the organization\'s continuous process improvement program.","source":"Official Sample Exam A Q#12"},{"id":262,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which fault types (1-4) BEST fit\\n\\nwhich test levels (A-D)?\\n\\n1. Failures in system behavior by deviating from the user\'s business needs\\n2. Failures in communication between components\\n3. Failures in logic in the code\\n4. Failures due to incorrectly implemented business rules\\n\\nA. Component testing  \\nB. Component integration testing  \\nC. System testing  \\nD. Acceptance testing","options":["A) 1D, 2B, 3A, 4C","B) 1D, 2B, 3C, 4A","C) 1B, 2A, 3D, 4C","D) 1C, 2B, 3A, 4D"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#13, LO: FL-2.2.1). Rationale: 1D, 2B, 3A, 4C","source":"Official Sample Exam A Q#13"},{"id":297,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements about the chosen software development life cycle is CORRECT?  ","options":["A) If agile software development is used, automation of system testing replaces the need for regression testing","B) If a sequential development model is used, dynamic testing is usually restricted to later stages of the life cycle","C) If an iterative development model is used, component testing is usually performed manually by the developers","D) If an incremental development model is used, static testing is performed in the early increments and dynamic testing in the later ones"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#9, LO: FL-2.1.1). Rationale: In a sequential development model, dynamic testing is usually restricted to the final phases of the life cycle.","source":"Official Sample Exam B Q#9"},{"id":298,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following is a good testing practice applicable to all software development life cycles?  ","options":["A) Testers should review work products as part of the next development phase","B) Testers should review work products as soon as drafts are available","C) Testers should review work products before test analysis and design begin","D) Testers should review work products immediately after they are published"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#10, LO: FL-2.1.2). Rationale: Testers should review work products as soon as drafts are available.","source":"Official Sample Exam B Q#10"},{"id":299,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following is an example of a test-first development approach?  ","options":["A) Test-Driven Development (TDD)","B) Coverage-Driven Development","C) Quality-Driven Development","D) Feature-Driven Development"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#11, LO: FL-2.1.3). Rationale: Test-Driven Development (TDD) is the classic example of a test-first approach.","source":"Official Sample Exam B Q#11"},{"id":300,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following activities is MOST LIKELY performed as part of system testing?  ","options":["A) Security testing of a credit management system performed by an independent test team","B) Testing the interface of a currency exchange system with an external banking system","C) Beta testing of a remote learning system performed by the software developers","D) Testing the interactions between the user interface and the database of a human resources system"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#13, LO: FL-2.2.1). Rationale: Security testing performed by an independent team is characteristic of system testing.","source":"Official Sample Exam B Q#13"},{"id":301,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements is CORRECT?  ","options":["A) Regression tests increase in number as the project progresses, while confirmation tests decrease","B) Regression tests are created and run when the test object is fixed, while confirmation tests are run when the test object is enhanced","C) Regression tests verify that the operating environment remains unchanged, while confirmation tests test the changes in the test object","D) Regression tests verify the adverse effects on unchanged code, while confirmation tests test the modified code"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#14, LO: FL-2.2.3). Rationale: Regression testing deals with adverse effects on unchanged code, while confirmation testing deals with the modified code.","source":"Official Sample Exam B Q#14"},{"id":335,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following provides the BEST description of the \'shift-left\' concept?  ","options":["A) When developers agree, the manual activities on the left side of the test process are automated to support the principle \'early testing saves time and money\'","B) When it is cost-effective, test activities are moved earlier in the SDLC to reduce the total cost of quality by decreasing the number of defects found in late phases","C) When they have free time, testers should automate regression tests starting with component and component integration tests","D) When available, testers are trained to perform tasks at the start of the SDLC to enable automating more test activities in later phases"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#11, LO: FL-2.1.5). Rationale: Shift-left involves moving test activities to the beginning of the life cycle to detect defects earlier, when they are cheaper to fix.","source":"Official Sample Exam C Q#11"},{"id":336,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following is the LEAST LIKELY to occur as a result of a retrospective?  ","options":["A) The quality of future test objects improves by identifying improvements in development practices","B) Test efficiency improves by streamlining the setup of test environments through automation","C) End users\' understanding of the development and testing processes improves","D) Automated test scripts are improved thanks to developer feedback"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#12, LO: FL-2.1.6). Rationale: Retrospectives are internal team meetings; they do not aim to improve end users\' understanding of the processes.","source":"Official Sample Exam C Q#12"},{"id":337,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which test level is MOST LIKELY being performed if the testing is focused on validation and is not performed by testers?  ","options":["A) Component testing","B) Component integration testing","C) System integration testing","D) Acceptance testing"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#13, LO: FL-2.2.1). Rationale: Acceptance testing is oriented toward validation (is it the right system?) and is generally performed by users or customers, not testers.","source":"Official Sample Exam C Q#13"},{"id":338,"chapter":2,"topic":"Testing Throughout the SDLC","question":"The software of a navigation system has been updated because it suggested routes that violated traffic rules, such as driving the wrong way on one-way streets.\\n\\nWhich of the following BEST describes the testing to be performed?","options":["A) Only confirmation testing","B) Confirmation testing and then regression testing","C) Only regression testing","D) Regression testing and then confirmation testing"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#14, LO: FL-2.2.3). Rationale: First, confirmation testing is done to verify the defect is fixed, and then regression testing to check that the fix has not introduced new defects.","source":"Official Sample Exam C Q#14"},{"id":369,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following is MOST LIKELY a challenge\\n\\nwhen implementing DevOps?","options":["A) Ensuring that non-functional quality characteristics are not overlooked","B) Managing test environments that change continuously","C) The need for more manual testers with appropriate experience","D) Setting up test automation as part of the delivery pipeline"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#11, LO: FL-2.1.4). Rationale: Setting up and integrating test automation within the continuous delivery pipeline is one of the biggest challenges when adopting DevOps.","source":"Official Sample Exam D Q#11"},{"id":370,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following BEST describes retrospectives?  ","options":["A) Retrospectives allow team members to identify other members who did not contribute enough to quality according to the whole-team approach","B) Retrospectives give testers the opportunity to identify activities that were successful in order to keep them when improvements are made in the future","C) Retrospectives are where agile team members can express their concerns about management and customers in a blame-free environment","D) Retrospectives give agile team members a forum to discuss the plan and technical decisions for the next iteration"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#12, LO: FL-2.1.6). Rationale: Retrospectives serve to identify what worked well (to keep it) and what can be improved in the next cycle.","source":"Official Sample Exam D Q#12"},{"id":371,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following tests is MOST LIKELY the one performed as part of functional testing?  ","options":["A) The test verifies that the sorting function places the list items in ascending order","B) The test verifies that the sorting function completes the process in less than one second","C) The test verifies how easily the sorting function can be changed from ascending to descending","D) The test verifies that the sorting function still works correctly when migrating from a 32-bit to a 64-bit architecture"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#13, LO: FL-2.2.2). Rationale: Verifying that the sorting function does what it should do (sort correctly) is a functional test; the other options are non-functional.","source":"Official Sample Exam D Q#13"},{"id":372,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following is MOST LIKELY the trigger that leads to performing maintenance testing of a currency exchange system?  ","options":["A) The developers reported that modifying the system was difficult and the testers decided to verify whether this was true","B) The system\'s refund option was removed because it did not always return the correct amount to customers","C) The agile team began developing a user story that adds a customer loyalty feature","D) The system\'s language support option was used to enable transactions in English and in the local language"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#14, LO: FL-2.3.1). Rationale: Removing a defective feature from the system in production is a classic trigger for maintenance testing.","source":"Official Sample Exam D Q#14"},{"id":409,"chapter":2,"topic":"Testing Throughout the SDLC","question":"In a project with a V-model, the team receives the system requirements on day 1. At\\n\\nwhat point should system tests start being designed?","options":["A) When the system code is fully developed","B) After integration testing is completed","C) In parallel with system design, as soon as the requirements are available","D) Only after the requirements are formally approved by the customer"],"correctAnswer":2,"explanation":"The \'shift-left\' approach and the V-model establish that system test design should occur in parallel with system design, not after development, taking advantage of the early requirements.","source":"banco"},{"id":410,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Your team works in Scrum with 2-week sprints. At the start of the sprint, the team has 8 user stories.\\n\\nWhen should testers start working on those stories?","options":["A) On the last day of the sprint, during the demo","B) From day one, collaborating on the definition of acceptance criteria and test cases","C) Halfway through the sprint, when development is 50% complete","D) In the next sprint, doing regression testing"],"correctAnswer":1,"explanation":"In Agile/Scrum, testers participate from the start of the sprint in refinement, definition of acceptance criteria, and test design, integrating testing continuously (whole-team approach).","source":"banco"},{"id":420,"chapter":2,"topic":"Testing Throughout the SDLC","question":"What is the difference between confirmation testing (re-testing) and regression testing?  ","options":["A) They are the same, just different names","B) Confirmation verifies that a specific defect was fixed; regression verifies that the changes did not break anything else","C) Regression is only done by developers; confirmation by testers","D) Confirmation is done before development; regression after"],"correctAnswer":1,"explanation":"Re-testing (confirmation) runs the test case that failed to verify that the specific defect was fixed. Regression testing verifies that the change did not introduce new failures in other areas.","source":"banco"},{"id":431,"chapter":2,"topic":"Testing Throughout the SDLC","question":"In TDD (Test Driven Development),\\n\\nwhat is the correct order of the cycle?","options":["A) Write code -> Write test -> Refactor","B) Write test (that fails) -> Write minimal code to pass the test -> Refactor","C) Design -> Write test -> Write code -> Refactor","D) Write test -> Deploy -> Refactor -> Write code"],"correctAnswer":1,"explanation":"TDD follows the Red-Green-Refactor cycle: 1) Write a test that fails (Red), 2) Write the minimal code to make it pass (Green), 3) Refactor the code while keeping the tests green.","source":"banco"},{"id":432,"chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements about system integration testing is CORRECT?  ","options":["A) They verify the internal logic of each individual component","B) They verify the interactions between the system and external systems or interfaces","C) They are run only by end users","D) They only apply in waterfall development models"],"correctAnswer":1,"explanation":"System integration testing verifies the interfaces and communications between the system under test and other external systems, services, APIs, or hardware it interacts with.","source":"banco"},{"id":433,"chapter":2,"topic":"Testing Throughout the SDLC","question":"A DevOps team implements CI/CD. Tests run automatically on every commit.\\n\\nWhat type of tests are MOST appropriate to run on each pipeline build in CI?","options":["A) Complete user acceptance tests","B) Manual exploratory tests","C) Fast automated component and integration tests","D) Complete performance tests with maximum load"],"correctAnswer":2,"explanation":"In CI, tests must be fast and automated to provide immediate feedback. Automated component and integration tests are ideal. Slow tests (UAT, full load) go in separate phases.","source":"banco"},{"id":442,"chapter":2,"topic":"Testing Throughout the SDLC","question":"What are \'entry criteria\' in the test process?  ","options":["A) The requirements the software must meet in order to be released to the market","B) The conditions that must be met before a test activity can begin","C) The criteria for accepting a new tester onto the team","D) The minimum coverage metrics to complete testing"],"correctAnswer":1,"explanation":"Entry criteria define the preconditions that must be met to start a test phase or activity, for example: software compiled without errors, environment available, test data prepared.","source":"banco"},{"id":447,"chapter":2,"topic":"Testing Throughout the SDLC","question":"What are \'test stubs\' in integration testing?  ","options":["A) Test automation tools","B) Substitutes for components called by the component under test that are not yet available","C) Reports of defects found during integration","D) Automatically generated test data"],"correctAnswer":1,"explanation":"Stubs are substitute components that simulate modules called by the component under test (\'downward\' components in the hierarchy) that are not yet available during integration testing.","source":"banco"},{"id":455,"chapter":2,"topic":"Testing Throughout the SDLC","question":"PRACTICAL CASE: An e-commerce system has 3 tiers: Frontend (React), Backend API (Java), Database (PostgreSQL).\\n\\nWhen testing the \'add to cart\' function, it fails. The backend returns error 500. What type of integration test do you need?","options":["A) Component test of the frontend","B) Integration test between the frontend and backend API to verify the interface contract","C) Complete end-to-end system test","D) User acceptance test"],"correctAnswer":1,"explanation":"The backend\'s 500 error indicates a failure in the interface between frontend and backend. Component integration testing verifies the interfaces and contracts between the integrated modules, which is exactly what you need to diagnose.","source":"banco"},{"id":461,"chapter":2,"topic":"Testing Throughout the SDLC","question":"What is the main objective of user acceptance testing (UAT)?  ","options":["A) Verify that the code has no syntax errors","B) Confirm that the system meets the business needs and is fit to be used by end users","C) Test the system\'s performance under load","D) Verify that the components integrate correctly"],"correctAnswer":1,"explanation":"UAT verifies that the system meets the business requirements and user needs. Users or business representatives confirm whether the system is fit for its purpose before formal acceptance.","source":"banco"},{"id":"q_batch2_4a5g1mcwu","chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements best describes the importance of testing during the software development life cycle?  ","options":["Testing is only necessary at the end of the development cycle to verify the final product.","Testing should be integrated into all phases of the development cycle to detect defects early.","Testing is mainly useful in large and complex projects.","Testing can be skipped if agile methodologies are used."],"correctAnswer":1,"explanation":"A. Incorrect. Testing should be performed throughout the entire life cycle, not just at the end. B. Correct. Integrating testing into all phases helps identify errors from the start. C. Incorrect. Testing is important in all projects, regardless of their size. D. Incorrect. Although agile methodologies foster collaboration, testing is essential in any model.","source":"banco-extra"},{"id":"q_batch2_6ody8pkik","chapter":2,"topic":"Testing Throughout the SDLC","question":"Identify the following test categories (1-4) and the agile testing quadrants (A-D).\\n\\nWhich combinations are correct?\\n\\n1. User acceptance testing\\n2. Performance testing\\n3. Component integration testing\\n4. User story testing\\n\\nA (Q1). Technology-oriented, supports the development team  \\nB (Q2). Business-oriented, supports the development team  \\nC (Q3). Business-oriented, critiques the product  \\nD (Q4). Technology-oriented, critiques the product","options":["1A, 2B, 3C, 4D","1B, 2A, 3D, 4C","1D, 2C, 3B, 4A","1C, 2D, 3A, 4B"],"correctAnswer":3,"explanation":"A. Incorrect. User acceptance testing (1) belongs to Q3 (business, critiques the product), not Q1. Performance testing (2) belongs to Q4, not Q2. B. Incorrect. User acceptance testing (1) belongs to Q3, not Q2. Component integration testing (3) belongs to Q1, not Q4. C. Incorrect. User acceptance testing (1) belongs to Q3, not Q4. User story testing (4) belongs to Q2, not Q1. D. Correct. User acceptance testing (1) -> Q3 (business, critiques the product). Performance testing (2) -> Q4 (technology, critiques the product). Component integration testing (3) -> Q1 (technology, supports the team). User story testing (4) -> Q2 (business, supports the team).","source":"banco-extra"},{"id":"q_batch2_ne2ycbfxp","chapter":2,"topic":"Testing Throughout the SDLC","question":"Which of the following statements BEST describes the test-driven development (TDD) methodology?  ","options":["In TDD, tests are written after software development is complete.","In TDD, a test that fails is created first before writing the code to make the test pass.","In TDD, only acceptance tests are developed at the end of the development cycle.","In TDD, the code and the tests are developed completely independently."],"correctAnswer":1,"explanation":"A. Incorrect. In TDD, tests are created before writing the code to ensure it meets the requirements. B. Correct. In TDD, a test that initially fails is written, which guides the subsequent development of the code. C. Incorrect. In TDD, tests are written continuously during development, not just at the end. D. Incorrect. In TDD, code development and tests are interrelated and not independent.","source":"banco-extra"},{"id":1015,"chapter":3,"topic":"Static Testing","question":"Which of the following statements is TRUE about static testing?  ","options":["Static testing helps reduce development time by finding defects in the early stages.","Static testing always detects all types of defects in the source code.","Static testing is more effective than dynamic testing at validating functionality.","Static testing cannot be used to improve documentation quality."],"correctAnswer":0,"explanation":"Finding problems statically (without executing code) saves a lot of money and time.","source":"Pr\xe1ctica Adicional"},{"id":1016,"chapter":3,"topic":"Static Testing","question":"What advantage does early and frequent feedback from stakeholders provide during software development?  ","options":["It fosters innovation in the proposed solutions.","It reduces the possibility of rework by identifying problems in time.","It increases the duration of the product life cycle.","It improves the development team\'s satisfaction."],"correctAnswer":1,"explanation":"Continuous feedback prevents building the wrong product, reducing costly rework.","source":"Pr\xe1ctica Adicional"},{"id":1017,"chapter":3,"topic":"Static Testing","question":"In your organization: There is no moderator role. The objective is to find defects and improve. There is open discussion. No formal documentation is required at the end.\\n\\nWhat type of review is it?","options":["Informal review","Technical review","Inspection","Guided review"],"correctAnswer":0,"explanation":"Without a moderator, without documentation, and oriented toward improvement with open discussion: Informal review.","source":"Pr\xe1ctica Adicional"},{"id":1018,"chapter":3,"topic":"Static Testing","question":"Which of the following factors is essential to ensure the effectiveness of a review?  ","options":["Having a facilitator to guide the review process.","Allowing only experts to participate in all reviews.","Conducting the review in an improvised way without prior preparation.","Limiting discussion time so it does not run too long."],"correctAnswer":0,"explanation":"A facilitator or other clear roles improve success. However, in some methodologies another key factor is \'prior preparation\'.","source":"Pr\xe1ctica Adicional"},{"id":1041,"chapter":3,"topic":"Static Testing","question":"Which of the following statements is a key factor for the success of reviews?  ","options":["The review should be carried out in a relaxed environment without external pressures.","Reviewers should have prior knowledge of the content they are reviewing.","It is better for only one participant to speak during the review to avoid confusion.","The objective of the review should be to identify only critical errors."],"correctAnswer":0,"explanation":"A relaxed environment allows for better communication and collaboration among participants.","source":"Errores Reportados - Set 2"},{"id":1044,"chapter":3,"topic":"Static Testing","question":"The author of a design document leads a review session. A scribe records the defects found. Participants can ask questions freely and the author explains their design. No formal entry or exit criteria are used.\\n\\nWhat type of review does this scenario describe?","options":["Inspection","Technical review","Walkthrough","Informal review"],"correctAnswer":2,"explanation":"A walkthrough is led by the author, has a scribe, and does not have formal entry or exit criteria.","source":"Errores Reportados - Set 2"},{"id":264,"chapter":3,"topic":"Static Testing","question":"Which of the following is NOT a benefit of static testing?  ","options":["A) Have less expensive defect management due to the ease of detecting defects later in the SDLC","B) Fixing defects found during static testing is generally much less expensive than fixing defects found during dynamic testing","C) Find coding defects that might not have been found by doing dynamic testing alone","D) Detect gaps and inconsistencies in requirements"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#15, LO: FL-3.1.2). Rationale: Have less costly defect management due to the ease of detecting defects later in the SDLC","source":"Official Sample Exam A Q#15"},{"id":265,"chapter":3,"topic":"Static Testing","question":"Which of the following is a benefit of early and frequent feedback?  ","options":["A) Improve the testing process for future projects","B) Forces customers to prioritize their requirements based on agreed risks","C) Provides a measure for the quality of changes","D) Helps avoid misunderstandings in requirements"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#16, LO: FL-3.2.1). Rationale: Helps avoid misunderstandings in requirements","source":"Official Sample Exam A Q#16"},{"id":266,"chapter":3,"topic":"Static Testing","question":"The reviews that are being used in your organization have the following attributes: \u2022 There is a role of a scribe \u2022 The primary purpose is to assess quality \u2022 The meeting is led by the author of the work product \u2022 There is individual preparation \u2022 A review report is produced\\n\\nWhich of the following types of review is MOST likely being used?","options":["A) Informal review","B) Walkthrough","C) Technical review","D) Inspection"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#17, LO: FL-3.2.4). Rationale: Walkthrough","source":"Official Sample Exam A Q#17"},{"id":267,"chapter":3,"topic":"Static Testing","question":"Which of these statements is NOT a contributing factor to successful reviews?  ","options":["A) Participants must allocate adequate time for review","B) Divide large work products into small parts so that the effort required is less intense","C) Participants should avoid behavior that may indicate boredom, exasperation, or hostility toward other participants.","D) Failures found must be recognized, appreciated and handled objectively"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#18, LO: FL-3.2.5). Rationale: Failures found must be recognized, appreciated and handled objectively","source":"Official Sample Exam A Q#18"},{"id":302,"chapter":3,"topic":"Static Testing","question":"Which of the following is an example of a defect that can be found through static testing but NOT through dynamic testing?  ","options":["A) Lack of usability in the user interface","B) Code that no execution path reaches (dead code)","C) Poor response times for most expected users","D) Required functionalities that are not implemented in the code"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#15, LO: FL-3.1.3). Rationale: Unreachable code (dead code) can only be detected through static analysis, since it is never executed.","source":"Official Sample Exam B Q#15"},{"id":303,"chapter":3,"topic":"Static Testing","question":"Which of the following is an advantage of early and frequent feedback from stakeholders?  ","options":["A) Managers know which developers are less productive","B) It allows project managers to prioritize their interactions with stakeholders","C) It facilitates early communication of potential quality problems","D) End users better understand why the work product delivery is delayed"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#16, LO: FL-3.2.1). Rationale: Early feedback facilitates the early communication of potential quality problems.","source":"Official Sample Exam B Q#16"},{"id":304,"chapter":3,"topic":"Static Testing","question":"Given the following task descriptions:\\n\\nWhich of the following options gives the BEST match between the task descriptions and the activities?\\n\\n1. The quality characteristics to be evaluated and the exit criteria are selected\\n2. Everyone has access to the work product\\n3. Anomalies in the work product are identified\\n4. Anomalies are discussed\\n\\nA. Individual review  \\nB. Review initiation  \\nC. Planning  \\nD. Communication and analysis","options":["A) 1B, 2C, 3D, 4A","B) 1B, 2D, 3C, 4A","C) 1C, 2A, 3B, 4D","D) 1C, 2B, 3A, 4D"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#17, LO: FL-3.2.2). Rationale: Planning defines the criteria (1C), initiation gives access to the document (2B), individual review identifies anomalies (3A), and communication and analysis discusses them (4D).","source":"Official Sample Exam B Q#17"},{"id":305,"chapter":3,"topic":"Static Testing","question":"Given the following review roles:\\n\\nWhich of the following options gives the BEST match between the roles and the responsibilities?\\n\\n1. Secretary/Scribe\\n2. Review leader\\n3. Facilitator\\n4. Manager\\n\\nA. Ensures the effective running of review meetings and establishes a safe environment  \\nB. Records review information, such as decisions and new anomalies found  \\nC. Decides what will be reviewed and provides resources such as staff and time  \\nD. Takes overall responsibility for the review: when and where it will take place","options":["A) 1A, 2B, 3D, 4C","B) 1A, 2C, 3B, 4D","C) 1B, 2D, 3A, 4C","D) 1B, 2D, 3C, 4A"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#18, LO: FL-3.2.3). Rationale: The Scribe records (1B), the Leader organizes the review (2D), the Facilitator manages the meeting (3A), and the Manager decides resources (4C).","source":"Official Sample Exam B Q#18"},{"id":339,"chapter":3,"topic":"Static Testing","question":"Given the following examples of defects:\\n\\ni. Two different parts of the design specification contradict each other due to the complexity of the design\\n\\nii. A response time is too long and makes users lose patience\\n\\niii. A path in the code cannot be reached during execution\\n\\niv. A variable is declared but never used in the program\\n\\nv. The amount of memory the program needs to generate a report is excessive.\\n\\nWhich of the following BEST identifies the defects that could be found through static testing (rather than dynamic)?","options":["A) ii, v","B) iii, v","C) i, ii, iv","D) i, iii, iv"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#15, LO: FL-3.1.3). Rationale: Contradictions in the specification (i), unreachable code (iii), and unused variables (iv) are detected through review or static analysis without executing the code.","source":"Official Sample Exam C Q#15"},{"id":340,"chapter":3,"topic":"Static Testing","question":"Given the following review types:\\n\\nWhich of the following gives the BEST match?\\n\\n1. Technical review\\n2. Informal review\\n3. Inspection\\n4. Walkthrough\\n\\nA. Includes objectives such as reaching consensus, generating new ideas, and motivating authors to improve  \\nB. Includes objectives such as training reviewers, reaching consensus, generating new ideas, and detecting potential defects  \\nC. The main objective is to detect potential defects and requires the collection of metrics for process improvement  \\nD. The main objective is to detect potential defects and does not generate formal output documentation","options":["A) 1A, 2B, 3C, 4D","B) 1A, 2D, 3C, 4B","C) 1B, 2C, 3D, 4A","D) 1C, 2D, 3A, 4B"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#16, LO: FL-3.2.1). Rationale: Technical review->consensus and new ideas (1A), Informal->no formal documentation (2D), Inspection->metrics (3C), Walkthrough->trains reviewers and generates ideas (4B).","source":"Official Sample Exam C Q#17"},{"id":341,"chapter":3,"topic":"Static Testing","question":"Which of the following is a factor that contributes to a successful review?  ","options":["A) The reviewers are experts in the domain of the object to be reviewed","B) The reviewers carry out their reviews aloud during the review meeting","C) The author does not participate in the review planning","D) Participants review their own work products"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#17, LO: FL-3.2.4). Rationale: Having reviewers who are domain experts ensures they can detect relevant defects.","source":"Official Sample Exam C Q#18"},{"id":373,"chapter":3,"topic":"Static Testing","question":"Which of the following CANNOT be examined through static testing?  ","options":["A) Contract","B) Test plan","C) Encrypted code","D) Test charter"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#15, LO: FL-3.1.1). Rationale: Encrypted code cannot be analyzed statically because its content is unreadable for static analysis tools and reviewers.","source":"Official Sample Exam D Q#15"},{"id":374,"chapter":3,"topic":"Static Testing","question":"Which of the following statements about the value of static testing is CORRECT?  ","options":["A) The types of defects found by static testing are different from those that dynamic testing can find","B) Dynamic testing can detect the types of defects found by static testing, plus some additional ones","C) Dynamic testing can identify some of the defects found by static testing, but not all of them","D) Static testing can identify the types of defects found by dynamic testing, plus some additional ones"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#16, LO: FL-3.1.2). Rationale: Dynamic testing cannot find defects such as unreachable code, unused variables, or documentation inconsistencies, which only static testing detects.","source":"Official Sample Exam D Q#16"},{"id":375,"chapter":3,"topic":"Static Testing","question":"Given the following descriptions of review activities:\\n\\n1. Detected anomalies are discussed and decisions are made about their status, owner, and next steps\\n\\n2. Defects are recorded and the necessary updates are addressed before the work product is accepted\\n\\n3. Reviewers use techniques to generate suggestions and questions about the work product and identify anomalies\\n\\n4. The objective of the review and its schedule are set to ensure a focused and efficient review\\n\\n5. Participants are given access to the item to be reviewed.\\n\\nWhat is the CORRECT sequence of review process activities?","options":["A) 4 - 3 - 5 - 2 - 1","B) 4 - 5 - 3 - 1 - 2","C) 5 - 4 - 1 - 3 - 2","D) 5 - 4 - 3 - 2 - 1"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#17, LO: FL-3.2.2). Rationale: Correct sequence: Planning (4) -> Review initiation/access (5) -> Individual review (3) -> Communication and analysis (1) -> Fixing and reporting (2).","source":"Official Sample Exam D Q#17"},{"id":376,"chapter":3,"topic":"Static Testing","question":"Which participant in the review process is responsible for ensuring that review meetings run effectively and that everyone can express their opinions freely?  ","options":["A) Manager","B) Moderator","C) Chairperson","D) Review Leader"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#18, LO: FL-3.2.3). Rationale: Moderator.","source":"Official Sample Exam D Q#18"},{"id":411,"chapter":3,"topic":"Static Testing","question":"During a requirements inspection, the moderator finds the sentence: \'The system shall be fast\'.\\n\\nWhat type of requirement defect does this statement represent?","options":["A) Duplicate requirement","B) Ambiguous and non-verifiable requirement","C) Conflicting requirement","D) Out-of-scope requirement"],"correctAnswer":1,"explanation":"\'Fast\' is ambiguous and non-verifiable because it does not specify a measurable criterion. A correct requirement would say, for example, \'The system shall respond in less than 2 seconds for 95% of requests\'.","source":"banco"},{"id":412,"chapter":3,"topic":"Static Testing","question":"A static analysis tool reports: \'Variable x declared but never used in the function calculateTotal()\'.\\n\\nHow is this finding classified in ISTQB terminology?","options":["A) Failure","B) Error (mistake)","C) Defect (bug/fault)","D) Incident"],"correctAnswer":2,"explanation":"Static analysis finds defects (faults/bugs) in the code without executing it. A declared but unused variable is a code defect detected statically.","source":"banco"},{"id":421,"chapter":3,"topic":"Static Testing","question":"Which of the following documents can be the subject of static review?  ","options":["A) Only the source code","B) Only the requirements","C) Any work product: requirements, design, code, test cases, plans","D) Only the documents delivered to the client"],"correctAnswer":2,"explanation":"Static testing can be applied to any written work product: requirements, design specifications, source code, test cases, test plans, contracts, etc.","source":"banco"},{"id":434,"chapter":3,"topic":"Static Testing","question":"An organization conducts a review\\n\\nwhere: there is an independent moderator, reviewers prepare individually, defect metrics are recorded, and a formal report is produced. What type of review is it?","options":["A) Informal review","B) Walkthrough","C) Technical review","D) Inspection"],"correctAnswer":3,"explanation":"Inspection is the most formal review: it has a trained moderator, individual preparation, defined roles (author, moderator, scribe, reviewers), collected metrics, and a formal output report.","source":"banco"},{"id":435,"chapter":3,"topic":"Static Testing","question":"What is the main difference between an inspection and a walkthrough in static reviews?  ","options":["A) The walkthrough is more formal than the inspection","B) In the walkthrough the author leads the meeting; in the inspection an independent moderator does","C) The inspection requires no prior preparation; the walkthrough does","D) The walkthrough produces formal metrics; the inspection does not"],"correctAnswer":1,"explanation":"In a Walkthrough, the author guides the participants through their work product. In an Inspection, an independent moderator leads the process following a defined process with more formality and rigor.","source":"banco"},{"id":441,"chapter":3,"topic":"Static Testing","question":"Which of the following defects is more likely to be found through static analysis than through dynamic testing?  ","options":["A) A calculation that returns the wrong result under specific conditions","B) A variable that can be null (null pointer) on a certain code path never reached in dynamic tests","C) A UI button that does not work in Firefox","D) A slow response time under high load"],"correctAnswer":1,"explanation":"Static analysis can detect possible null pointer exceptions, dead code, or never-executed paths that dynamic testing does not cover. It is especially useful for defects in rarely executed code paths.","source":"banco"},{"id":453,"chapter":3,"topic":"Static Testing","question":"PRACTICAL CASE: In a requirements specification review you find: \'The system shall process transactions quickly and the interface shall be friendly\'.\\n\\nWhat types of requirement defects are present?","options":["A) Only ambiguity","B) Ambiguity (\'quickly\', \'friendly\') and lack of verifiability: they are neither measurable nor testable","C) Contradiction between requirements","D) Duplicate requirements"],"correctAnswer":1,"explanation":"\'Quickly\' and \'friendly\' are ambiguous and non-verifiable terms. Good requirements must be specific and measurable (e.g.: \'process in <2s\', \'SUS score >75\'). This is the most common defect in requirements reviews.","source":"banco"},{"id":458,"chapter":3,"topic":"Static Testing","question":"PRACTICAL CASE: Your organization implements mandatory code reviews. The development team complains that they slow down the process.\\n\\nWhat is the STRONGEST argument to justify the reviews?","options":["A) They are mandatory by regulation, there is no alternative","B) The cost of fixing defects found in review is significantly lower than fixing them in production","C) Reviews improve team morale","D) The review tool was paid for and must be amortized"],"correctAnswer":1,"explanation":"The economic argument is the strongest: finding a defect in code review costs ~1x; in system testing ~10x; in production ~100x. Reviews have the highest ROI in early defect detection.","source":"banco"},{"id":465,"chapter":3,"topic":"Static Testing","question":"Which of the following is an example of a static analysis technique?  ","options":["A) Running the software with test data","B) Using a linter or code analysis tool to detect standards violations","C) Testing the user interface manually","D) Measuring the system\'s response time"],"correctAnswer":1,"explanation":"Static analysis examines the code without executing it. Linter tools (such as SonarQube, ESLint, Checkstyle) detect standards violations, dead code, possible null pointers, etc. without running the program.","source":"banco"},{"id":"q_batch2_j6kuaxygc","chapter":3,"topic":"Static Testing","question":"Which of the following statements best describes an advantage of static testing?  ","options":["Static testing is useful for identifying defects that manifest only during software execution.","Static testing allows the review of documents and code without needing to execute the software.","Static testing generally requires more time than dynamic testing to be effective.","Static testing is less effective at detecting design defects compared to dynamic testing."],"correctAnswer":1,"explanation":"A. Incorrect. Static testing does not involve executing the software, so it cannot identify defects that manifest only at runtime. B. Correct. This is one of the main advantages of static testing, since it allows reviewing documents and code without execution. C. Incorrect. Static testing is usually faster than dynamic testing as it requires no execution. D. Incorrect. Static testing can be effective at detecting design defects, contrary to what is suggested here.","source":"banco-extra"},{"id":"q_batch2_n23h74aj8","chapter":3,"topic":"Static Testing","question":"In your organization, reviews are conducted with the following characteristics: No scribe is required. The objective is to detect anomalies in an unstructured way. The participants are experts in the area. There is no designated moderator.\\n\\nWhat type of review is MOST likely being conducted?","options":["Informal review","Technical review","Inspection","Guided review"],"correctAnswer":0,"explanation":"A. Correct. Informal reviews are the type of review described. According to the CTFL v4.0 syllabus, section 3.2.4, informal reviews do not follow a defined process and do not require a formally documented output. Their main objective is to detect anomalies. The scenario\'s characteristics - no scribe, no designated moderator, expert participants, the objective of detecting anomalies in an unstructured way - are fully consistent with this type of review. B. Technical reviews usually require a moderator and a more structured focus on product quality, which is not mentioned in the given characteristics. C. Incorrect. Inspections are the most formal type of review. They require specific roles (trained moderator, scribe, author), follow a structured process, and collect metrics for SDLC process improvement. The scenario describes none of these formal elements. D. Guided reviews require preparation and a moderator, which are not mentioned in the description, and their main objective is to assess quality, not improve the process.","source":"banco-extra"},{"id":1019,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements best describes a white-box testing technique?  ","options":["It is based on knowledge of the internal workings of the software and its code structure.","It is mainly used to evaluate the user experience and the system\'s usability.","Test cases are designed without taking into account the internal logic of the system.","It focuses on identifying defects in the requirements through interface testing."],"correctAnswer":0,"explanation":"White-box is based on the internal structure (code, architecture).","source":"Pr\xe1ctica Adicional"},{"id":1020,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"A grading system accepts scores 0-100. Fail: 0-59, Pass: 60-69, Good: 70-89, Excellent: 90-100. Using equivalence partitioning,\\n\\nwhat is the MINIMUM number of test cases to achieve 100% coverage of the VALID partitions?","options":["3","4","5","6"],"correctAnswer":1,"explanation":"There are 4 valid partitions: [0,59], [60,69], [70,89], [90,100]. One case is needed for each, so 4 cases.","source":"Pr\xe1ctica Adicional"},{"id":1021,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"The \'Age\' field accepts 16 to 65 years. Your set includes: 15, 16, 17, 64, 65, 66.\\n\\nWhat percentage of 3-value Boundary Value Analysis (BVA) coverage do you achieve?","options":["50%","67%","83%","100%"],"correctAnswer":3,"explanation":"In 3-value BVA, a boundary \'X\' needs X-1, X, X+1. For 16 you need 15,16,17. For 65 you need 64,65,66. You have them all, 100% coverage.","source":"Pr\xe1ctica Adicional"},{"id":1022,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"In a decision table for loans you have 4 conditions. If you wanted to minimize the table due to the large number of combinations,\\n\\nwhat would be the best strategy?","options":["Remove all the least important conditions","Use a risk-based approach to reduce the rules to be tested","Combine all conditions into a single rule","Create multiple separate small tables"],"correctAnswer":1,"explanation":"When a table is massive (e.g. 2^N rules), the strategy suggested by ISTQB is to minimize using a risk-based approach.","source":"Pr\xe1ctica Adicional"},{"id":1023,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements about coverage criteria in state transition testing is CORRECT?  ","options":["Coverage of all states is stronger than coverage of valid transitions","Coverage of valid transitions guarantees complete coverage of all states","Coverage of all transitions includes only valid transitions","To achieve valid transition coverage you must test only one transition per test case"],"correctAnswer":1,"explanation":"If you cover all valid transitions (arrows), you have necessarily visited all states (nodes). Therefore, valid transition coverage is stronger than state coverage.","source":"Pr\xe1ctica Adicional"},{"id":1024,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements is true regarding statement coverage in software testing?  ","options":["Statement coverage guarantees that all test cases have found defects.","Achieving 100% statement coverage means that all statements in the code have been executed at least once.","Statement coverage is irrelevant if exhaustive functional testing is performed.","100% statement coverage ensures that there are no loops in the code."],"correctAnswer":1,"explanation":"100% statement coverage means that each line/instruction has been executed at least once.","source":"Pr\xe1ctica Adicional"},{"id":1025,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements best describes an advantage of white-box testing?  ","options":["White-box testing allows the internal logic of the code and its execution flow to be verified.","White-box testing is useful for validating the user experience in the graphical interface.","White-box testing ensures that all functional requirements have been implemented correctly.","White-box testing is always more effective than black-box testing without needing design analysis."],"correctAnswer":0,"explanation":"It allows verifying the internal logic, finding dead branches, and checking code structures.","source":"Pr\xe1ctica Adicional"},{"id":1026,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements REFERS to error guessing in a testing process?  ","options":["Error guessing is based solely on quantitative metrics of previous defects.","Error guessing involves identifying the areas of the software most likely to contain defects based on experience.","Error guessing requires testers to perform unit tests on all functions.","Error guessing is a process that only developers can perform."],"correctAnswer":1,"explanation":"Error guessing relies heavily on the tester\'s experience to intuit where developers have typically made mistakes.","source":"Pr\xe1ctica Adicional"},{"id":1027,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"A team is creating an innovative mobile app, and exploratory testing will be used due to lack of documentation.\\n\\nWhich of the following statements about exploratory testing is CORRECT?","options":["Exploratory testing is always less effective than requirements-based testing.","Exploratory testing allows testers to adapt quickly to changes in the software.","Exploratory testing requires a detailed test plan before being performed.","Exploratory testing is not suitable for complex applications."],"correctAnswer":1,"explanation":"It is flexible, adaptive, and ideal when documentation is scarce or changing.","source":"Pr\xe1ctica Adicional"},{"id":1028,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements describes A suitable technique for writing acceptance criteria?  ","options":["Setting criteria in the form of open questions to encourage discussion.","Using concrete examples that illustrate how the functionality is expected to work.","Documenting criteria in a separate document to improve organization.","Writing criteria in technical language to ensure precision in the details."],"correctAnswer":1,"explanation":"In agile/ATDD approaches, concrete examples (e.g. Behavior Driven Development with Given-When-Then) are the best way to document acceptance criteria.","source":"Pr\xe1ctica Adicional"},{"id":1029,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"An agile team uses ATDD.\\n\\nWhen are the acceptance test cases created in the ATDD approach?","options":["After the developer has finished implementing the user story.","During the specification workshop, before development begins.","Only during the regression testing phase at the end of the sprint.","When the customer performs user acceptance testing (UAT)."],"correctAnswer":1,"explanation":"The key to Acceptance Test Driven Development (ATDD) is to write the acceptance test collaboratively *before* writing code.","source":"Pr\xe1ctica Adicional"},{"id":1031,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements about coverage criteria in state transition testing is CORRECT?  ","options":["Coverage of all states is stronger than coverage of valid transitions","Coverage of valid transitions guarantees complete coverage of all states","Coverage of all transitions includes only valid transitions","To achieve valid transition coverage you must test only one transition per test case"],"correctAnswer":1,"explanation":"Achieving complete valid transition coverage guarantees complete coverage of all states, since to exercise all valid transitions you must necessarily visit all states.","source":"Errores Reportados - Set 2"},{"id":1032,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements is true regarding statement coverage in software testing?  ","options":["Statement coverage guarantees that all test cases have found defects.","Achieving 100% statement coverage means that all statements in the code have been executed at least once.","Statement coverage is irrelevant if exhaustive functional testing is performed.","100% statement coverage ensures that there are no loops in the code."],"correctAnswer":1,"explanation":"100% statement coverage means that each statement in the code has been executed at least once during testing.","source":"Errores Reportados - Set 2"},{"id":1033,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements is correct regarding white-box testing?  ","options":["White-box testing focuses on the software\'s functionality without considering its internal structure.","Data flow analysis is a technique used in white-box testing to identify possible errors.","White-box testing is less effective than black-box testing for detecting defects in the business logic.","White-box testing is limited to verifying the correct implementation of user requirements."],"correctAnswer":1,"explanation":"Data flow analysis is a white-box testing technique that helps identify errors in the use of variables and their flow through the code.","source":"Errores Reportados - Set 2"},{"id":1034,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements most appropriately describes\\n\\nhow acceptance criteria can be defined for a user story?","options":["By specifying only the functional requirements without details about validation.","By describing the expected results using a clear and concise format that includes concrete examples.","By focusing only on the technical implementation that must be done to fulfill the user story.","By generating an extensive document that includes all aspects of the project, not just those related to the user story."],"correctAnswer":1,"explanation":"Using a clear format and concrete examples helps all stakeholders better understand the acceptance criteria.","source":"Errores Reportados - Set 2"},{"id":1045,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are in charge of a software project\\n\\nwhere several risks have been identified, but the time for testing is limited. The development team has delivered the application without detailed documentation. What would be the best testing technique to use in this situation?","options":["Risk-based testing","Exploratory testing","Automated testing","Regression testing"],"correctAnswer":1,"explanation":"Exploratory testing is suitable when there is little documentation and time is limited; testers use their experience to explore and evaluate the system heuristically.","source":"Errores Reportados - Set 2"},{"id":1049,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You have a block of code with 120 executable statements. After running your test set, the reports indicate that exactly 90 statements have been exercised.\\n\\nWhat level of statement coverage has been achieved?","options":["25%","90%","120%","75%"],"correctAnswer":3,"explanation":"Statement coverage is calculated as: (executed statements / total statements) * 100. In this case: (90 / 120) * 100 = 75%.","source":"Generadas (Agile/Metrics)"},{"id":1050,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"A software tester wants to calculate the coverage achieved by their tests. The component under test has 50 executable statements and 12 possible branches. During testing, 45 statements and 9 branches were executed.\\n\\nWhat is the achieved BRANCH coverage metric?","options":["90%","75%","45%","12%"],"correctAnswer":1,"explanation":"Branch coverage focuses only on the number of branches (decisions) exercised. It is calculated: (exercised branches / total branches) * 100. Therefore: (9 / 12) * 100 = 75%. The executed statements (45/50 = 90%) are irrelevant for calculating branch coverage.","source":"Generadas (Agile/Metrics)"},{"id":1051,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"A test set covers 8 of the 10 total valid transitions of a state diagram.\\n\\nWhat percentage of valid transition coverage has been achieved, and what can be stated with full certainty about state coverage?","options":["80%; It is guaranteed that all states have been visited (100% state coverage).","80%; Not necessarily all states have been visited.","20%; Not necessarily all states have been visited.","100%; It is guaranteed that all states have been visited."],"correctAnswer":1,"explanation":"Transition coverage is 8/10 = 80%. According to the ISTQB Syllabus, only 100% valid transition coverage GUARANTEES 100% state coverage. Being 80%, each state may have been visited, but it CANNOT be guaranteed.","source":"Generadas (Agile/Metrics)"},{"id":268,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following is a characteristic of experience-based testing techniques?  ","options":["A) Test cases are created based on detailed design information","B) Tested elements within the interface code section are used to measure coverage","C) Testing techniques depend largely on the tester\'s knowledge of the software and the business domain.","D) Test cases are used to identify deviations from requirements"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#19, LO: FL-4.1.1). Rationale: Testing techniques largely depend on the tester\'s knowledge of the software and the business domain.","source":"Official Sample Exam A Q#19"},{"id":269,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are testing a simplified apartment search form that only has two search criteria: \u2022 floor (with three possible options: ground floor; first floor; second floor or higher) \u2022 garden type (with three possible options: no garden; small garden; large garden) All apartments on the ground floor have a garden, apartments on the upper floors do not. The form has a built-in validation mechanism that will not allow you to use search criteria that violate this rule. Each test has two input values: floor and garden type. You want to apply equivalence partitioning (EP) to cover each floor and each type of garden in your tests.\\n\\nWhat is the minimum number of test cases to achieve 100% EP coverage for valid partitions?","options":["A) 3","B) 4","C) 5","D) 6"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#20, LO: FL-4.2.1). Justification: 4","source":"Official Sample Exam A Q#20"},{"id":271,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Your favorite daily bike rental shop just introduced a new customer relationship management (CRM) system and asked you, one of its most loyal members, to try it out. The features implemented are as follows: \u2022 Anyone can rent a bike, but members receive a 20% discount \u2022 However, if the return deadline is missed, the discount is no longer available \u2022 After 15 rentals, members get a gift: a t-shirt. The decision table describing the implemented features looks like this: Conditions R1 R2 R3 R4 R5 R6 R7 R8 Be a member T T T T F F F F Missed deadline T F T F T F F T 15th rental F F T T F F T T Shares 20% discount X  ","options":["A) R4","B) R2","C) R6","D) R8"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#22, LO: FL-4.2.3). Justification: R8","source":"Official Sample Exam A Q#22"},{"id":272,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Test a system whose life cycle is modeled by the state transition diagram shown below. The system starts in the INIT state and ends its operation in the OFF state.\\n\\nWhat is the MINIMUM number of test cases to achieve valid transition coverage?","options":["A) 4","B) 2","C) 7","D) 3"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#23, LO: FL-4.2.4). Justification: 3","source":"Official Sample Exam A Q#23"},{"id":273,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Their test suite achieved 100% sentence coverage.\\n\\nWhat is the consequence of this fact?","options":["A) Every statement in the code that contains a defect has been executed at least once","B) Any test suite that contains more test cases than your test suite will also achieve 100% statement coverage","C) Every route in the code has been executed at least once","D) Each combination of input values \u200b\u200bhas been tested at least once"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#24, LO: FL-4.3.1). Rationale: Every statement in the code that contains a defect has been executed at least once","source":"Official Sample Exam A Q#24"},{"id":274,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements is NOT true for white box testing?  ","options":["A) During white box testing the entire software implementation is considered","B) White box coverage metrics can help identify additional tests to increase code coverage","C) White box testing techniques can be used in static testing","D) White box testing can help identify gaps in the implementation of requirements"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#25, LO: FL-4.3.3). Rationale: White box testing can help identify gaps in the implementation of requirements","source":"Official Sample Exam A Q#25"},{"id":275,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following BEST describes the concept behind error guessing?  ","options":["A) Bug prediction involves using your knowledge and experience about defects found in the past and typical mistakes made by developers","B) Bug prediction involves using your personal development experience and the mistakes you made as a developer","C) Error prediction requires you to imagine that you are the user of the test object and guess the errors that the user might make interacting with it","D) Bug prediction requires you to quickly duplicate the development task to identify the type of bugs a developer might make"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#26, LO: FL-4.4.1). Rationale: Bug prediction involves using your knowledge and experience about defects found in the past and typical errors made by developers","source":"Official Sample Exam A Q#26"},{"id":276,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Started late but has very detailed domain knowledge and good analytical skills. The full list of requirements has not yet been shared with the team, but management is asking for some test results to be submitted.\\n\\nWhich testing technique BEST fits this situation?","options":["A) Tests based on checklists","B) Error prediction","C) Exploratory tests","D) Branch testing"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#27, LO: FL-4.4.2). Rationale: Exploratory testing","source":"Official Sample Exam A Q#27"},{"id":277,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following BEST describes\\n\\nhow acceptance criteria can be documented?","options":["A) Conducting retrospectives to determine the real needs of stakeholders regarding a given user story","B) Using the given/when/then format to describe an example test condition related to a given user story","C) Using verbal communication to reduce the risk of others misunderstanding the acceptance criteria","D) Documenting the risks related to a given user story in a test plan to facilitate risk-based testing of a given user story"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#28, LO: FL-4.5.2). Rationale: Using the given/when/then format to describe an example test condition related to a given user story","source":"Official Sample Exam A Q#28"},{"id":278,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Consider the following user story: As an Editor I want to review the content before it is published to ensure that the grammar is correct and its acceptance criteria: \u2022 The user can log in to the content management system with the role of \\"Editor\\" \u2022 The editor can view existing content pages \u2022 The editor can edit the content of the page \u2022 The editor can add markup comments \u2022 The editor can save changes \u2022 The editor can reassign to the \\"content owner\\" role to make updates\\n\\nWhich of the following is the BEST example of an ATDD test for this user story?","options":["A) Test if the editor can save the document after editing the page content","B) Test if the content owner can log in and make updates to the content","C) Test if the editor can schedule the edited content for publication","D) Test if the editor can reassign to another editor to make updates"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#29, LO: FL-4.5.3). Rationale: Test if the editor can save the document after editing the page content","source":"Official Sample Exam A Q#29"},{"id":306,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements BEST describes the difference between decision table testing and branch testing?  ","options":["A) In decision table testing, test cases are derived from the decision statements in the code. In branch testing, test cases are derived from knowledge of the test object\'s control flow.","B) In decision table testing, test cases are derived from the specification describing the business logic. In branch testing, cases are based on anticipating possible defects in the source code.","C) In decision table testing, test cases are derived from knowledge of the test object\'s control flow. In branch testing, cases are derived from the specification describing the business logic.","D) In decision table testing, test cases are independent of how the software is implemented. In branch testing, test cases can only be created after the code design or implementation."],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#19, LO: FL-4.1.1). Rationale: Decision tables are implementation-independent (black-box), while branch testing requires knowing the code (white-box).","source":"Official Sample Exam B Q#19"},{"id":307,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Customers of the TestWash car wash chain have cards with the number of washes they have purchased. The initial value is 0. On entering the wash, the system increments the number on the card by one. This value represents the current wash number. Based on this number the system decides the discount: every tenth wash gives a 10% discount and every twentieth wash gives an additional 40% (i.e., 50% in total).\\n\\nWhich of the following sets of input data (the current wash numbers) achieves the highest equivalence partition coverage?","options":["A) 19, 20, 30","B) 11, 12, 20","C) 1, 10, 50","D) 10, 29, 30, 31"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#20, LO: FL-4.2.1). Rationale: The partitions are: no discount (not a multiple of 10), 10% (multiple of 10 but not of 20), and 50% (multiple of 20). 19 (no discount), 20 (50%), and 30 (10%) cover 3 distinct partitions.","source":"Official Sample Exam B Q#20"},{"id":308,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are testing a form that checks whether the length of the entered password is correct. The form accepts passwords of the correct length and rejects those that are too short or too long. The length is correct if it is between 6 and 12 characters inclusive. The form is initially empty (length = 0). You apply boundary value analysis to the \'password length\' variable. Your test case set achieves 100% 2-value boundary coverage. The team decides that, due to the high risk of the component, cases must be added to reach 100% 3-value boundary coverage.\\n\\nWhich additional password lengths should be tested?","options":["A) 4, 5, 13, 14","B) 7, 11","C) 1, 5, 13","D) 1, 4, 7, 11, 14"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#21, LO: FL-4.2.2). Rationale: With 2 values we already have 0, 6, 12 and a value above the upper range. With 3 values we also need the neighbors: 5, 7, 11, 13 and the value 1 for the left lower boundary.","source":"Official Sample Exam B Q#21"},{"id":310,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"A storage system can hold up to three elements and is modeled by the following state transition diagram. The variable N represents the number of elements currently stored.\\n\\nWhich of the following test cases, represented as event sequences, achieves the highest level of valid transition coverage?","options":["A) Add, Remove, Add, Add, Add","B) Add, Add, Add, Add, Remove, Remove","C) Add, Add, Add, Remove, Remove","D) Add, Add, Add, Remove, Add"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#23, LO: FL-4.2.4). Rationale: The sequence Add x3, Remove x2 traverses all the valid transitions of the state diagram.","source":"Official Sample Exam B Q#23"},{"id":311,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You execute two test cases, T1 and T2, on the same code. T1 achieves 40% statement coverage and T2 achieves 65%.\\n\\nWhich of the following statements is necessarily true?","options":["A) The test set T1+T2 achieves 105% statement coverage","B) There is at least one statement that has been executed by both T1 and T2","C) At least 5% of the statements in the tested code are not executable","D) The test set T1+T2 achieves full branch coverage"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#24, LO: FL-4.3.1). Rationale: If T1 covers 40% and T2 covers 65%, and total coverage cannot exceed 100%, there is necessarily overlap: both have executed at least one common statement.","source":"Official Sample Exam B Q#24"},{"id":312,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"The branch coverage metric is defined as: BCov = (X / Y) x 100%.\\n\\nWhat do X and Y represent in this formula?","options":["A) X = number of decision outcomes exercised by the test cases. Y = total number of decision outcomes in the code","B) X = number of conditional branches exercised by the test cases. Y = total number of branches in the code","C) X = number of branches exercised by the test cases. Y = total number of branches in the code","D) X = number of conditional branches exercised by the test cases. Y = total number of decision outcomes in the code"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#25, LO: FL-4.3.2). Rationale: X is the number of branches exercised and Y the total number of branches in the code.","source":"Official Sample Exam B Q#25"},{"id":313,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"What BEST justifies the use of exploratory testing?","options":["A) Little time for design and experienced testers","B) Required use of formal black-box techniques","C) Formal language specification","D) Testers with good programming skills"],"correctAnswer":0,"explanation":"Options A) and E) are the correct answers according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#26, LO: FL-4.4.2). Rationale: Exploratory testing is ideal when there is little time for formal design (A) and when the tester has domain experience (E).","source":"Official Sample Exam B Q#26"},{"id":314,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following options BEST fits as an item in a checklist for checklist-based testing?  ","options":["A) \'The developer made a mistake when implementing the code\'","B) \'The achieved statement coverage exceeds 85%\'","C) \'The program works correctly with respect to the functional and non-functional requirements\'","D) \'The error messages are written in language understandable to the user\'"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#27, LO: FL-4.4.3). Rationale: Checklist items must be verifiable by observation, such as checking whether the messages are understandable to the user.","source":"Official Sample Exam B Q#27"},{"id":315,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Consider the following acceptance criterion for a user story written from the perspective of an online store owner. GIVEN the user is logged in and is on the home page,\\n\\nWHEN the user clicks the \'Add item\' button, THEN the \'Create item\' form should appear, AND the user should be able to enter a name and a price for the new item. In which format is this acceptance criterion written?","options":["A) Rule-oriented","B) Scenario-oriented","C) Product-oriented","D) Process-oriented"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#28, LO: FL-4.5.2). Rationale: The GIVEN/WHEN/THEN format is the scenario-oriented format, typical of BDD.","source":"Official Sample Exam B Q#28"},{"id":316,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Your team analyzes the following user story to define the acceptance criteria: \'As a registered customer, I want to be able to view my previous orders on the company website, so that I can keep track of my purchases.\'\\n\\nWhich of the following test cases will NOT be relevant for this user story?","options":["A) Input: the customer logs in and clicks \'view order history\'. Expected result: the system shows a list of all previous orders with date, order number, and total cost","B) Input: the customer clicks an order in the list. Expected result: the system shows the individual items purchased with their prices and quantities","C) Input: the customer clicks \'Sort ascending\' on the order history screen. Expected result: the system shows the history sorted by order number in ascending order","D) Input: an unregistered customer registers as a new customer with a valid email that does not exist in the database. Expected result: the system accepts the registration and creates the account"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#29, LO: FL-4.5.3). Rationale: The user story is about viewing previous orders (an already registered customer), not about the new customer registration process.","source":"Official Sample Exam B Q#29"},{"id":342,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"What is the MAIN difference between black-box test techniques and experience-based techniques?  ","options":["A) Black-box techniques use formal models; experience-based techniques use the testers\' knowledge","B) Black-box techniques use the system specification; experience-based techniques use the testers\' knowledge and intuition","C) Black-box techniques are derived from the code; experience-based techniques are derived from the specification","D) Black-box techniques include exploratory testing; experience-based techniques include equivalence partition testing"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#18, LO: FL-4.1.1). Rationale: Black-box techniques are based on the system specification; experience-based techniques are based on the tester\'s knowledge and intuition.","source":"Official Sample Exam C Q#19"},{"id":343,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are testing a PIN validator that accepts valid PINs and rejects invalid ones. A PIN is a sequence of 4 digits\\n\\nwhere each digit is between 0 and 9. You apply equivalence partitioning to the \'number of PIN digits\' field. How many partitions are there in total (including valid and invalid)?","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#19, LO: FL-4.2.1). Rationale: There are 3 partitions: length less than 4 (invalid), exactly 4 digits (valid), and more than 4 digits (invalid).","source":"Official Sample Exam C Q#20"},{"id":344,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"A developer was asked to implement the following business rule: INPUT: value (integer). IF (value > 0) AND (value <= 10) -> Action A. IF (value > 10) AND (value <= 20) -> Action B. IF (value > 20) -> Action C.\\n\\nHow many test cases are needed at minimum to achieve 100% branch coverage?","options":["A) 2","B) 3","C) 4","D) 6"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#20, LO: FL-4.2.2). Rationale: 4 test cases are needed to cover all branches: a value <=0 (no condition), one in 1-10 (Action A), one in 11-20 (Action B), and one >20 (Action C).","source":"Official Sample Exam C Q#21"},{"id":345,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are working on a project to develop a driving test results analysis system. You have been asked to design test cases using decision table testing for the following rule: A candidate PASSES if they get at least 43 of 50 answers correct AND make no serious mistake. A candidate FAILS in any other case.\\n\\nHow many rules (columns) will the complete decision table have?","options":["A) 2","B) 3","C) 4","D) 6"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#21, LO: FL-4.2.3). Rationale: There are 2 conditions with 2 values each (>=43/no, no serious mistake/serious mistake), giving 4 combinations (rules).","source":"Official Sample Exam C Q#22"},{"id":346,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are designing test cases based on a state transition diagram.\\n\\nWhat is the MINIMUM number of test cases needed to achieve coverage of all valid transitions (100%)?","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#23, LO: FL-4.2.4). Rationale: The minimum number of test cases for valid transition coverage depends on the diagram; in this case, 3 cases cover all the transitions.","source":"Official Sample Exam C Q#23"},{"id":347,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You want to apply branch testing to the code represented by the following control flow graph.\\n\\nHow many test cases are needed at MINIMUM to achieve 100% branch coverage?","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#25, LO: FL-4.3.2). Rationale: For the given control flow graph, 2 test cases are needed to cover all branches (TRUE and FALSE of each decision).","source":"Official Sample Exam C Q#24"},{"id":348,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"How can white-box testing be useful as support for black-box testing?  ","options":["A) It can be used to verify that all requirements are implemented in the code","B) It can be used to create test cases that cover code that the black-box cases do not execute","C) It can be used to assess whether the specification correctly reflects the system\'s business logic","D) It can be used to avoid creating test cases redundant with the black-box ones"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#26, LO: FL-4.3.2). Rationale: White-box testing can identify and cover code that the black-box cases do not exercise, thus complementing the coverage.","source":"Official Sample Exam C Q#25"},{"id":349,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Consider the following list of possible defects: - Correct input not accepted - Incorrect input accepted - Incorrect output produced - Omitted functionality.\\n\\nWhich of the following test techniques is SPECIFICALLY designed to detect all these types of defects?","options":["A) Equivalence partition testing","B) Decision table testing","C) State transition testing","D) Boundary value analysis testing"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#27, LO: FL-4.4.1). Rationale: Equivalence partitioning is specifically designed to detect these types of defects by testing representative values of each partition.","source":"Official Sample Exam C Q#26"},{"id":350,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following BEST describes\\n\\nhow the use of checklist-based testing can result in greater coverage compared to specification-based testing without a checklist?","options":["A) Checklists include items based on experience of past defects, which helps detect more defects","B) Checklists are formal documents automatically generated by static analysis tools","C) Checklists allow the tester to cover more test conditions without needing a specification","D) Checklists guarantee 100% branch coverage of the code"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#28, LO: FL-4.4.3). Rationale: Checklists incorporate experience from past projects, which allows detecting defects that formal specifications do not explicitly cover.","source":"Official Sample Exam C Q#27"},{"id":351,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following provides the BEST example of a scenario-oriented acceptance criterion?  ","options":["A) The system must show an error message if the username exceeds 50 characters","B) GIVEN a customer is logged in, WHEN they click \'Place order\', THEN the system shows an order confirmation","C) The system response time must not exceed 2 seconds for 95% of requests","D) The password field must accept between 8 and 20 alphanumeric characters"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#29, LO: FL-4.5.2). Rationale: The GIVEN/WHEN/THEN format is the scenario-oriented format typical of BDD.","source":"Official Sample Exam C Q#28"},{"id":352,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are using acceptance test-driven development (ATDD) and designing test cases based on the following user story: \'As a registered user, I want to be able to change my password, to keep my account secure.\'\\n\\nWhich of the following test cases is NOT relevant for this user story?","options":["A) Verify that the user can change their password by entering the correct current password and a valid new password","B) Verify that the system rejects the change if the entered current password is incorrect","C) Verify that the system sends a confirmation email to the user after the password change","D) Verify that an unregistered user can reset their password using the \'forgot my password\' link"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample C, Q#30, LO: FL-4.5.3). Rationale: The user story is about changing the password of an ALREADY registered user, not about resetting passwords for unregistered users.","source":"Official Sample Exam C Q#29"},{"id":377,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are performing system testing of an e-commerce web application and are given the following requirement: REQ 05-017. If the total cost of purchases exceeds $100, the customer gets a 5% discount on subsequent purchases. Otherwise, the customer receives no discount.\\n\\nWhich test techniques will be MOST useful for designing test cases based on this requirement?","options":["A) White-box test techniques","B) Black-box test techniques","C) Experience-based techniques","D) Risk-based test techniques"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#19, LO: FL-4.1.1). Rationale: Black-box test techniques (the requirement describes externally observable behavior, independent of the code).","source":"Official Sample Exam D Q#19"},{"id":378,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"The cinema ticket sales system calculates the discount type based on the customer\'s year of birth (YB) and the current year (CY) as follows: Let D be the difference between CY and YB, i.e., D = CY - YB. - If D < 0, show the error \'the year of birth cannot be greater than the current year\'. - If 0 <= D < 18, apply the student discount. - If 18 <= D < 65, apply no discount. - If D >= 65, apply the retiree discount. Your test set already contains two cases: - YB = 1990, CY = 2020, expected result: no discount. - YB = 2030, CY = 2029, expected result: show error.\\n\\nWhich of the following test data sets should be added to achieve full valid equivalence partition coverage for the discount type?","options":["A) AN = 2001, AA = 2065","B) AN = 1900, AA = 1965","C) AN = 1965, AA = 1900","D) AN = 2011, AA = 2029"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#20, LO: FL-4.2.1). Rationale: YB = 1900, CY = 1965 gives D = 65, covering the retiree discount partition (D >= 65), which was missing.","source":"Official Sample Exam D Q#20"},{"id":379,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are testing a temperature control system for a cold storage facility. The system receives the temperature (in whole Celsius degrees) as input. If the temperature is between 0 and 2 degrees inclusive, it shows \'temperature OK\'. For lower temperatures, it shows \'temperature too low\', and for higher ones \'temperature too high\'. Using 2-value boundary value analysis,\\n\\nwhich of the following sets provides the highest level of boundary value coverage?","options":["A) -1, 3","B) 0, 2","C) -1, 0, 2, 3","D) -2, 0, 2, 4"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#21, LO: FL-4.2.2). Rationale: -1, 0, 2, 3 cover both boundaries and their immediate neighbors (2-value BVA at the boundaries 0 and 2).","source":"Official Sample Exam D Q#21"},{"id":380,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are designing test cases based on a decision table of ages and experience. So far you have designed 4 test cases.\\n\\nWhich of the following test cases, when added to the existing set, will increase the decision table coverage?","options":["A) Man aged 66, unregistered, no experience; expected result: category B","B) Woman aged 55, unregistered, with 2 years of experience; expected result: category A","C) Woman aged 19, registered, with 5 years of experience; expected result: category D","D) No additional case can increase the achieved coverage"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#22, LO: FL-4.2.3). Rationale: The case of a man aged 66, unregistered, no experience (category B) covers a rule not yet exercised by the existing set.","source":"Official Sample Exam D Q#22"},{"id":381,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are applying state transition testing to a hotel room booking system. Assuming that all test cases start in the \'Requesting\' state,\\n\\nwhich of the following test cases, represented as event sequences, achieves the highest valid transition coverage?","options":["A) NotAvailable, Available, ChangeRoom, NotAvailable, Cancel","B) Available, ChangeRoom, NotAvailable, Available, Pay","C) Available, ChangeRoom, Available, ChangeRoom, NotAvailable","D) NotAvailable, Cancel, ChangeRoom, Available, Pay"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#23, LO: FL-4.2.4). Rationale: The sequence Available, ChangeRoom, NotAvailable, Available, Pay traverses the most valid transitions of the diagram.","source":"Official Sample Exam D Q#23"},{"id":382,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Your test set S for a program P achieves 100% statement coverage. It consists of three test cases, each of\\n\\nwhich achieves 50% statement coverage. Which of the following statements is CORRECT?","options":["A) Running S will cause all possible failures in P","B) S achieves 100% branch coverage for P","C) Every executable statement in P that contains a defect has been executed at least once during the run of S","D) After removing one test case from S, the remaining two will still achieve 100% statement coverage"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#24, LO: FL-4.3.1). Rationale: 100% statement coverage guarantees that every executable statement (including any containing a defect) has been executed at least once, although this does not guarantee that all failures are triggered.","source":"Official Sample Exam D Q#24"},{"id":383,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Why does white-box testing facilitate defect detection even\\n\\nwhen the software specification is vague, outdated, or incomplete?","options":["A) Test cases are designed based on the structure of the test object instead of the specification","B) For each white-box technique, coverage can be well defined and easily measured","C) White-box techniques are very well designed to detect omissions in the requirements","D) White-box techniques can be used in both static and dynamic testing"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#25, LO: FL-4.3.3). Rationale: Test cases are designed based on the structure of the test object instead of the specification, so they do not depend on the quality of the specification.","source":"Official Sample Exam D Q#25"},{"id":384,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following situations is NOT anticipated by the tester\\n\\nwhen applying the error guessing technique?","options":["A) The developer misunderstood the formula in the user story for calculating interest","B) The developer wrote \'FA = A*(1+IR^N)\' instead of \'FA = A*(1+IR)^N\' in the code","C) The developer missed the seminar about the new compound interest rate legislation","D) The accuracy of the interest calculated by the system is not precise enough"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#26, LO: FL-4.4.1). Rationale: Error guessing anticipates likely defects in the software, not organizational facts such as the developer missing a seminar.","source":"Official Sample Exam D Q#26"},{"id":385,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements is true about exploratory testing?  ","options":["A) Test cases are designed before the exploratory testing session starts","B) The tester can execute tests, but cannot design them","C) The results of exploratory testing are good predictors of the number of remaining defects","D) During exploratory testing, the tester can use black-box techniques"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#27, LO: FL-4.4.2). Rationale: During exploratory testing, the tester can use black-box techniques to guide the simultaneous design and execution of tests.","source":"Official Sample Exam D Q#27"},{"id":386,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which collaborative practice for writing user stories allows the team to achieve a collective understanding of\\n\\nwhat needs to be delivered?","options":["A) Planning poker, to reach a consensus on the effort","B) Reviews, to detect inconsistencies and contradictions","C) Iteration planning, to prioritize higher-value stories","D) Conversation, so that team members understand how the software will be used"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#28, LO: FL-4.5.1). Rationale: Conversation is the collaborative practice (the \'C\' of the 3 Cs: Card, Conversation, Confirmation) that builds shared understanding.","source":"Official Sample Exam D Q#28"},{"id":387,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are designing test cases for a user story\\n\\nwhere the customer wants to filter products by price range. Precondition: only two products are available, A ($100) and B ($110). What is the BEST example of a test case for this user story?","options":["A) Go to the website and set the filter between $90 and $100. Result: shows only A. Change the maximum to $110. Result: shows A and B.","B) Go to the website. Add product C priced at $120. Refresh the page. Result: the default maximum price changes to $120.","C) Go to the website and set the filter between $90 and $115. Result: shows A and B. Change the currency to EUR. Result: the filter changes to values in EUR.","D) Go to the website with Edge, Chrome, and Opera. In each one set the filter between $90 and $110. Result: they show A and B with the same layout in all."],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#29, LO: FL-4.5.3). Rationale: This case directly tests the filtering behavior described in the user story using boundary values of the price range.","source":"Official Sample Exam D Q#29"},{"id":400,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are a tester of a banking system. The \'transfer amount\' field accepts values between 1 euro and 10,000 euros. Applying 3-value BVA per boundary,\\n\\nwhich set of test values is correct?","options":["A) 0, 1, 2, 9999, 10000, 10001","B) 1, 10000","C) 0, 1, 5000, 10000, 10001","D) -1, 0, 1, 9999, 10000, 10001"],"correctAnswer":0,"explanation":"3-value BVA per boundary includes: below the boundary (0), at the boundary (1), just inside (2) for the lower boundary; and just inside (9999), at the boundary (10000), above (10001) for the upper boundary.","source":"banco"},{"id":401,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"A discount system applies: 0% if purchase < 100 euros, 5% if 100 euros <= purchase < 500 euros, 10% if 500 euros <= purchase < 1000 euros, 15% if purchase >= 1000 euros. Using equivalence partitioning,\\n\\nhow many valid equivalence classes are there?","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":2,"explanation":"There are 4 valid equivalence classes: [0-99 euros], [100-499 euros], [500-999 euros], [>=1000 euros], one for each different discount range.","source":"banco"},{"id":402,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are designing a decision table for a loan system with 3 boolean conditions (sufficient income, good credit history, collateral provided).\\n\\nHow many rule columns will the complete table have?","options":["A) 3","B) 6","C) 8","D) 9"],"correctAnswer":2,"explanation":"With 3 boolean conditions (T/F each), the number of possible combinations is 2^3 = 8 rules/columns.","source":"banco"},{"id":403,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"An ATM has states: Idle, Waiting for PIN, Verifying, Dispensing, Blocked. If you enter 3 incorrect PINs in a row, the transition goes to \'Blocked\'.\\n\\nWhich test design technique is MOST suitable for modeling and verifying this behavior?","options":["A) Equivalence partitioning","B) Boundary values","C) State transition testing","D) Decision tables"],"correctAnswer":2,"explanation":"State transition testing models the system\'s behavior when it moves from one state to another based on events or conditions, ideal for systems with states such as an ATM.","source":"banco"},{"id":404,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You have the following code: IF (a > 0 AND b > 0) THEN result = a + b ELSE result = 0. To achieve 100% decision coverage,\\n\\nhow many test cases are needed at minimum?","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"For 100% decision coverage you need at least 2 cases: one that makes the condition true (e.g. a=1, b=1) and another that makes it false (e.g. a=-1, b=1).","source":"banco"},{"id":405,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You work on a flight booking app. You are applying the \'use cases\' method to design tests.\\n\\nWhich flow MUST you test to find the most critical defects in the booking flow?","options":["A) Only the basic flow (happy path)","B) Only the alternative error flows","C) The basic flow and all the alternative and exception flows","D) Only the flows that are most likely to occur"],"correctAnswer":2,"explanation":"Use-case-based testing must cover the basic flow (happy path) AND all the alternative and exception flows to ensure complete coverage of the specified behavior.","source":"banco"},{"id":406,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"For a module with 5 independent conditions in a decision table,\\n\\nhow many rules would the complete table have, and how many would result from \'collapsing\' by removing irrelevant conditions if there are only 3 distinct actions?","options":["A) 32 complete; 3 collapsed","B) 10 complete; 3 collapsed","C) 32 complete; can be fewer than 32 when collapsed","D) 16 complete; 3 collapsed"],"correctAnswer":2,"explanation":"With 5 boolean conditions: 2^5 = 32 complete rules. Collapsing reduces rules by combining those where some condition is irrelevant (\'don\'t care\'), resulting in fewer than 32.","source":"banco"},{"id":422,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"A form field accepts age values between 18 and 65 years. Using equivalence partitioning,\\n\\nhow many classes are identified (valid + invalid)?","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":1,"explanation":"3 classes are identified: invalid (<18), valid (18-65), invalid (>65). There is 1 valid class and 2 invalid = 3 total classes.","source":"banco"},{"id":424,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Analyze the following flowchart: START -> A -> IF X THEN B ELSE C -> IF Y THEN D ELSE E -> END.\\n\\nHow many test cases are needed to achieve 100% statement coverage?","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"To execute all statements (A, B or C, D or E) you need at least 2 cases: one with X=true,Y=true (executes A,B,D) and another with X=false,Y=false (executes A,C,E). With 2 cases you cover all statements.","source":"banco"},{"id":425,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You have a function with 4 independent conditions in an AND expression: (A AND B AND C AND D). To achieve 100% modified condition/decision coverage (MC/DC),\\n\\nhow many test cases are needed at minimum?","options":["A) 2","B) 4","C) 5","D) 16"],"correctAnswer":2,"explanation":"MC/DC requires N+1 test cases for N independent conditions. With 4 conditions: 4+1=5 minimum cases. MC/DC demonstrates that each condition independently affects the outcome.","source":"banco"},{"id":426,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"A traffic light system has states: Red, Amber_to_Green, Green, Amber_to_Red. The transition Red->Amber_to_Green occurs after 60 seconds.\\n\\nHow many valid transitions does the complete traffic light diagram have?","options":["A) 2","B) 3","C) 4","D) 8"],"correctAnswer":2,"explanation":"The complete cycle has 4 transitions: Red->Amber_to_Green, Amber_to_Green->Green, Green->Amber_to_Red, Amber_to_Red->Red. There are exactly 4 transitions in the normal cycle.","source":"banco"},{"id":427,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"You are testing a search function. From your experience, you know that searches with special characters (%, _, *) often cause SQL injection.\\n\\nWhich experience-based technique are you using?","options":["A) Structured exploration","B) Error guessing","C) White-box testing","D) Equivalence partitioning"],"correctAnswer":1,"explanation":"Error guessing is an experience-based technique where the tester predicts where defects are most likely, based on their knowledge of common failures such as SQL injection with special characters.","source":"banco"},{"id":428,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"For the following code IF (age >= 18 AND country == \'ES\') THEN access = true ELSE access = false,\\n\\nhow many test cases do you need for 100% decision coverage?","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"Decision coverage requires the compound condition to be evaluated as TRUE and as FALSE. You need: case 1 (age=20, country=\'ES\' -> true) and case 2 (age=15, country=\'ES\' -> false). Minimum 2 cases.","source":"banco"},{"id":439,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Pairwise testing is applied to a system with 5 parameters, each with 3 possible values. If all combinations were tested it would be 3^5=243 cases.\\n\\nWhat is pairwise for?","options":["A) To test all possible combinations systematically","B) To reduce the number of test cases by ensuring each pair of values appears at least once","C) To test only the boundary values of each parameter","D) To automate the generation of test data"],"correctAnswer":1,"explanation":"Pairwise (or all-pairs) testing ensures that each combination of 2 parameters is tested at least once, drastically reducing the number of cases (from 243 to ~25 approx.) while maintaining good defect detection.","source":"banco"},{"id":445,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following techniques is \'white-box\'?  ","options":["A) Equivalence partitioning","B) Boundary value analysis","C) Statement coverage","D) Decision tables"],"correctAnswer":2,"explanation":"White-box (structure-based) techniques are based on the internal code: statement, branch, condition coverage. The other options (EP, BVA, decision tables) are black-box techniques based on specifications.","source":"banco"},{"id":448,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"PRACTICAL CASE: You are testing a hotel booking system. Prices vary by season: Low (January-March, Oct-Nov): 80 euros/night; Mid (April-June, Sep): 120 euros/night; High (July-August, Dec): 200 euros/night. Using EP,\\n\\nhow many valid equivalence classes are there for the price per night?","options":["A) 2","B) 3","C) 6","D) 12"],"correctAnswer":1,"explanation":"There are 3 valid price equivalence classes: [80 euros - low season], [120 euros - mid season], [200 euros - high season]. EP groups by equivalent system behavior, not by number of months.","source":"banco"},{"id":449,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"PRACTICAL CASE: Online voting system. Voting conditions: (1) Registered citizen, (2) Over 18 years old, (3) Has not already voted. They can only vote if they meet all 3. Design the minimal decision table.\\n\\nHow many distinct behavior rules (not impossible rules) are there?","options":["A) 2","B) 3","C) 4","D) 8"],"correctAnswer":3,"explanation":"With 3 boolean conditions there are 2^3=8 combinations. Only 1 combination (T,T,T) allows voting; the other 7 deny it. There are 8 possible rules describing distinct system behaviors.","source":"banco"},{"id":450,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"PRACTICAL CASE: Testing a pedestrian traffic light. States: RED_PEDESTRIAN, GREEN_PEDESTRIAN, FLASHING. Transitions: RED->GREEN (after 60s), GREEN->FLASHING (after 25s), FLASHING->RED (after 5s).\\n\\nWhat 0-switch coverage (all transitions) does it require at minimum?","options":["A) 1 test case","B) 2 test cases","C) 3 test cases that cover the complete cycle","D) 6 test cases, one per each possible transition"],"correctAnswer":2,"explanation":"0-switch coverage requires each valid transition to be exercised at least once. With 3 transitions in a cycle (R->G->F->R), a path that traverses the complete cycle covers them all. In practice, multiple cases are used for variants.","source":"banco"},{"id":457,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"PRACTICAL CASE: Testing a registration form. Fields: name (required), email (valid format), password (8-20 chars, at least 1 uppercase). Using EP,\\n\\nhow many equivalence classes are there ONLY for the password field?","options":["A) 2 (valid and invalid)","B) 4 (valid; invalid due to short length; invalid due to long length; invalid due to no uppercase)","C) 3 (short, valid, long)","D) 6 (all combinations of length and format)"],"correctAnswer":1,"explanation":"For password: 1) Valid (8-20 chars + uppercase), 2) Invalid-short (<8 chars), 3) Invalid-long (>20 chars), 4) Invalid-no uppercase (length OK but no uppercase). These are 4 distinct classes with different system behavior.","source":"banco"},{"id":462,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"A specification says: \'If the user is premium AND has been a member for more than 1 year, apply a 20% discount\'.\\n\\nWhich test design technique is MOST directly applicable to this business rule?","options":["A) Boundary value analysis","B) Decision tables","C) State transition","D) Statement coverage"],"correctAnswer":1,"explanation":"Decision tables are ideal for business rules with multiple conditions and combinations (premium: yes/no, membership: >1 year/<=1 year) that determine different actions (discount or not).","source":"banco"},{"id":467,"chapter":4,"topic":"Test Analysis and Design Techniques","question":"What does 100% \'branch coverage\' mean?  ","options":["A) That all lines of code were tested","B) That each decision in the code took the value true AND false at least once","C) That all possible input values were tested","D) That all functions of the system were executed"],"correctAnswer":1,"explanation":"100% branch (or decision) coverage means that every possible outcome of every decision point (if/else, switch) was executed at least once: both the true and the false branch of each condition.","source":"banco"},{"id":"q_batch2_3dfvl4agj","chapter":4,"topic":"Test Analysis and Design Techniques","question":"In an agile project, the team is implementing the following user story: \'As a customer, I want to search for products by category to quickly find\\n\\nwhat I need\'. The acceptance criteria are: The system shows available categories; the user can select a category; products from the selected category are shown; a message is shown if there are no products in the category. What is the BEST example of an ATDD test case for this story?","options":["Verify that the database contains at least 10 categories","Given there are products in \'Electronics\', when I select \'Electronics\', then I see the list of electronic products","Test that the response time is less than 2 seconds","Verify that the code complies with the coding standards"],"correctAnswer":1,"explanation":"A. Incorrect. This case focuses on technical implementation aspects rather than user-visible behavior. B. Correct. This test case is based on specific acceptance criteria (select category and show products), uses the typical Given/When/Then format, is understandable for stakeholders, and covers specific characteristics of the user story without going beyond its scope. C. Incorrect. Although important, performance is not covered in the acceptance criteria of this specific story. D. Incorrect. Coding standards are technical aspects, not user-visible acceptance criteria.","source":"banco-extra"},{"id":"q_batch2_7kt0gtwqg","chapter":4,"topic":"Test Analysis and Design Techniques","question":"A development team has implemented a new financial system, but not all requirements have been documented. The time for testing is limited and the team needs to obtain information about the system\'s behavior quickly.\\n\\nWhich testing approach would be the MOST suitable in this situation?","options":["Regression testing","Exploratory testing","Load testing","Unit testing"],"correctAnswer":1,"explanation":"A. Incorrect. Regression testing requires understanding the changes made to the system and is normally used when there is an established test basis. B. Correct. Exploratory testing is ideal when there is little time and little documentation, allowing testers to use their creativity and knowledge to discover defects. C. Incorrect. Load testing focuses on the system\'s performance under specific conditions and requires a clear set of load requirements. D. Incorrect. Unit testing focuses on individual components of the code.","source":"banco-extra"},{"id":"q_batch2_j594nrl15","chapter":4,"topic":"Test Analysis and Design Techniques","question":"A music player system has the following states: STOPPED, PLAYING, PAUSED. The valid transitions are: STOPPED -> PLAYING (play), PLAYING -> PAUSED (pause), PAUSED -> PLAYING (resume), PLAYING -> STOPPED (stop), PAUSED -> STOPPED (stop).\\n\\nWhat is the MINIMUM number of test cases to achieve 100% valid transition coverage with the constraint that the case must start and end in the STOPPED state?","options":["2","3","4","5"],"correctAnswer":0,"explanation":"A. Correct. With 2 cases that start and end in STOPPED, all transitions are covered. Case 1: S -> P(lay) -> Pause -> S (covers play, pause, stop from Paused). Case 2: S -> Play -> Pause -> Resume -> S (covers resume and stop from Playing). B. Incorrect. Possible, but not minimal. All transitions can be covered with 3 cases, but 2 is already enough. C. Incorrect. Redundant. It can also be achieved with 4 cases, but that is more than needed. D. Incorrect. Very inefficient. It would cover each transition separately, totally redundant.","source":"banco-extra"},{"id":"q_batch2_sho8tyfr5","chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements about error guessing is most accurate?  ","options":["Error guessing is based on the analysis of the system\'s characteristics and on previous experiences to anticipate possible failures.","Error guessing is a process that is performed exclusively after tests have been executed.","Error guessing focuses only on regression testing and recent code changes.","Error guessing can only be done by developers with a lot of experience."],"correctAnswer":0,"explanation":"A. Correct. Error guessing uses knowledge about the system and past experiences to formulate hypotheses about where errors are most likely to occur. B. Incorrect. Error guessing should be done before executing the tests, using prior knowledge to anticipate problems. C. Incorrect. Although regression testing can be part of the process, error guessing is not limited to these tests or to recent changes. D. Incorrect. Error guessing can be performed by any tester, not only by experienced developers.","source":"banco-extra"},{"id":"q_batch2_v5j9hx3qq","chapter":4,"topic":"Test Analysis and Design Techniques","question":"A web registration form has the following fields: Age: 18-65 years (valid), under 18 or over 65 (invalid). Membership type: \'Basic\', \'Premium\', \'VIP\' (valid), any other value (invalid). Applying equivalence partitioning with the \'Each Choice\' coverage criterion,\\n\\nhow many test cases are needed at MINIMUM to cover all the valid partitions?","options":["2","3","4","5"],"correctAnswer":1,"explanation":"A. Incorrect. 2 test cases would not cover the 3 partitions of the membership type. B. Correct. With the \'Each Choice\' coverage criterion, we need to cover each partition of each set at least once. For the Age field we have 1 valid partition (18-65), and for Membership type we have 3 valid partitions (\'Basic\', \'Premium\', \'VIP\'). 3 test cases are needed: TC1(valid age, Basic), TC2(valid age, Premium), TC3(valid age, VIP). C. Incorrect. 4 test cases would be more than needed. D. Incorrect. 5 test cases exceed the required minimum.","source":"banco-extra"},{"id":"q_batch2_yr0f7ze9n","chapter":4,"topic":"Test Analysis and Design Techniques","question":"Which of the following statements best describes black-box test techniques?  ","options":["They focus on the internal structure of the code to design test cases.","They are based on validating the functional requirements and specifications without considering the code.","They use the tester\'s knowledge of the source code to identify test cases.","They focus on executing tests at the unit level of the software components."],"correctAnswer":1,"explanation":"A. Incorrect. This description applies to white-box test techniques, which involve analyzing the internal structure of the software. B. Correct. Black-box test techniques focus on verifying that the software works according to the specifications, without considering how it is implemented internally. C. Incorrect. Using knowledge of the source code is more aligned with white-box techniques, where the internal structures of the software are analyzed. D. Incorrect. This statement describes tests performed at the unit level of the components.","source":"banco-extra"},{"id":"q_batch2_zdybwbzfz","chapter":4,"topic":"Test Analysis and Design Techniques","question":"A discount system for an online store applies the following rules:\\n\\n- If the customer is VIP AND the order is > $100: 20% discount\\n- If the customer is VIP AND the order is <= $100: 10% discount\\n- If the customer is NOT VIP AND the order is > $100: 5% discount\\n- If the customer is NOT VIP AND the order is <= $100: no discount\\n\\nHow many decision rules are needed in the complete decision table?","options":["2","3","4","8"],"correctAnswer":2,"explanation":"A. Incorrect. 2 rules would not cover all the possible combinations of the conditions. B. Incorrect. 3 rules would leave one combination uncovered. C. Correct. There are 2 conditions (Is VIP: True/False, Order > $100: True/False), so mathematically there are 2^2 = 4 possible combinations, and all are feasible according to the business rules presented. The complete table needs 4 decision rules to cover all combinations. D. Incorrect. 8 rules would be more than needed for two boolean conditions.","source":"banco-extra"},{"id":1004,"chapter":5,"topic":"Managing the Test Activities","question":"You are participating in a software project developing an e-learning platform. The team has decided to perform regression testing on the current version of the system.\\n\\nWhich of the following activities is performed during the test planning phase?","options":["Define which features will be tested in the next iteration.","Execute test cases to verify that the e-learning platform\'s functionality works.","Review the test results and document the defects found.","Analyze the system requirements to identify test cases."],"correctAnswer":0,"explanation":"Planning includes defining the scope, that is, what will be tested. Executing is execution; analyzing is analysis; reviewing results is closure or monitoring.","source":"Pr\xe1ctica Adicional"},{"id":1006,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following activities is TYPICAL of a test manager role?  ","options":["Developing test cases","Managing the test team","Executing automated tests","Performing defect analysis"],"correctAnswer":1,"explanation":"The Test Manager supervises, plans, and manages. Developing and executing cases is usually the tester\'s role.","source":"Pr\xe1ctica Adicional"},{"id":1030,"chapter":5,"topic":"Managing the Test Activities","question":"In your previous project, the ratio between development effort and testing effort was 5:3. The current project estimates 800 person-days of development. Using ratio-based estimation,\\n\\nwhat would the testing effort estimate be?","options":["400 person-days","480 person-days","533 person-days","600 person-days"],"correctAnswer":1,"explanation":"Rule of three: If 5 devs = 3 QA, then 800 devs = X QA. X = (800 * 3) / 5 = 480 days.","source":"Pr\xe1ctica Adicional"},{"id":1035,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following options represents an entry criterion for a test cycle?  ","options":["The customer\'s acceptance criteria have been defined.","All regression tests have been completed.","Requirements coverage has been documented.","The project deliverables meet the specifications."],"correctAnswer":0,"explanation":"Defining the acceptance criteria is an entry criterion that ensures the requirements are clear before starting testing. (Options B and D are exit criteria).","source":"Errores Reportados - Set 2"},{"id":1036,"chapter":5,"topic":"Managing the Test Activities","question":"Your team is in the third iteration of an agile project. The test efforts of the previous iterations were: Iteration 1: 45 person-days, Iteration 2: 52 person-days. Using extrapolation,\\n\\nwhat would be the most appropriate estimate for Iteration 3?","options":["45 person-days (the historical minimum)","48.5 person-days (average of the two iterations)","52 person-days (increasing trend)","59 person-days (extrapolation of the trend)"],"correctAnswer":1,"explanation":"According to the syllabus, in extrapolation the team can extrapolate the test effort in the next iteration as the averaged effort of the last iterations. With two iterations, the average is (45 + 52) / 2 = 48.5 days.","source":"Errores Reportados - Set 2"},{"id":1046,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following is an entry criterion to start testing a software?  ","options":["The design documentation is complete","The previous test reports have been reviewed","A production environment has been set up","The unit tests have been completed"],"correctAnswer":0,"explanation":"Complete design documentation indicates that the base requirements and specifications are ready to allow creating conditions and planning the test cycle (a valid entry criterion).","source":"Errores Reportados - Set 2"},{"id":1052,"chapter":5,"topic":"Managing the Test Activities","question":"The team uses the three-point estimation technique for a new feature. The estimates in days are: Optimistic = 10, Most Likely = 15, Pessimistic = 26.\\n\\nWhat is the final rounded estimate using the weighted formula E = (o + 4m + p) / 6?","options":["15 days","16 days","17 days","18 days"],"correctAnswer":1,"explanation":"Applying the formula E = (o + 4m + p) / 6: (10 + (4 * 15) + 26) / 6 = (10 + 60 + 26) / 6 = 96 / 6 = 16 days.","source":"Generadas (Agile/Metrics)"},{"id":1053,"chapter":5,"topic":"Managing the Test Activities","question":"To plan the test effort for the next Sprint, the manager proposes an optimistic scenario\\n\\nwhere everything works on the first try (5 days), a pessimistic scenario with multiple blockers (15 days), and a most likely scenario based on recent experience (7 days). Using the three-point technique, what is the estimated effort?","options":["8 days","9 days","7 days","10 days"],"correctAnswer":0,"explanation":"Applying the weighted three-point formula: (5 + 4*7 + 15) / 6 = (5 + 28 + 15) / 6 = 48 / 6 = 8 days.","source":"Generadas (Agile/Metrics)"},{"id":1054,"chapter":5,"topic":"Managing the Test Activities","question":"The test team needs to estimate the effort for a new project. They decide to base their estimate on the \'Number of Use Cases\' metric. Historically, testing a complete use case takes 3 days. If the new project has 12 use cases, they estimate 36 days.\\n\\nWhich technique has been used?","options":["Consensus-based estimation (Planning Poker)","Three-point estimation","Ratio-based estimation (or proportional metrics-based)","Extrapolation"],"correctAnswer":2,"explanation":"A metrics/ratio-based estimation has been used. Multiplying a standard metric (3 days per use case) by the size of the new project (12 cases) is the basis of parametric or ratio-based estimates.","source":"Generadas (Agile/Metrics)"},{"id":1055,"chapter":5,"topic":"Managing the Test Activities","question":"What is the estimation technique known as Planning Poker mainly based on?  ","options":["On complex mathematical formulas based on lines of code.","On the experience of the team members seeking an iterative and interactive consensus.","On the direct extrapolation of the team\'s last three iterations.","On the mathematical three-point estimation formula."],"correctAnswer":1,"explanation":"Planning Poker is an estimation technique based on experience and interactive consensus. The team discusses and votes anonymously until reaching a common agreement on the required effort.","source":"Generadas (Agile/Metrics)"},{"id":1057,"chapter":5,"topic":"Managing the Test Activities","question":"In the context of software testing,\\n\\nwhich of the following statements best describes the objective of test planning?","options":["Identify all possible defects in the software.","Define the resources, scope, and approach of the testing to be performed.","Create specific test cases for each software module.","Review the source code to ensure software quality."],"correctAnswer":1,"explanation":"A. Incorrect. Although identifying defects is an objective of testing, planning focuses on defining how the testing will be carried out. B. Correct. Planning defines the necessary resources, the scope, and the testing approach. C. Incorrect. Creating test cases is part of execution, not planning. D. Incorrect. Reviewing the source code is part of quality review.","source":"Generadas (Test Planning)"},{"id":1077,"chapter":5,"topic":"Managing the Test Activities","question":"You are participating in a software project developing an e-learning platform. The team has decided to perform regression testing.\\n\\nWhich of the following activities is performed during the test planning phase?","options":["Define which features will be tested in the next iteration.","Execute test cases to verify that the platform\'s functionality works.","Review the test results and document the defects found.","Analyze the system requirements to identify test cases."],"correctAnswer":0,"explanation":"A. Correct. Defining the features to be tested is part of test planning. B. Incorrect. Execution is part of the test execution phase. C. Incorrect. Reviewing results and documenting defects is done after execution. D. Incorrect. Analyzing requirements to identify test cases is part of test analysis.","source":"Generadas (Test Planning)"},{"id":1078,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following activities is TYPICAL of a test manager role?  ","options":["Developing test cases","Managing the test team","Executing automated tests","Performing defect analysis"],"correctAnswer":1,"explanation":"A. Incorrect. Developing test cases is a task usually performed by a tester. B. Correct. Managing the test team is a key responsibility of the test manager. C. Incorrect. Executing automated tests is the testers\' task. D. Incorrect. Defect analysis is mainly the testers\' responsibility.","source":"Generadas (Test Roles)"},{"id":1079,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following tasks is TYPICALLY performed by a test leader?  ","options":["Developing test cases","Coordinating test team resources","Executing regression tests","Specifying system requirements"],"correctAnswer":1,"explanation":"A. Incorrect. Developing test cases is the responsibility of testers or analysts. B. Correct. A test leader is in charge of coordinating the resources and activities of the test team. C. Incorrect. Executing regression tests is more commonly done by testers. D. Incorrect. Specifying requirements is the responsibility of business analysts or the product owner.","source":"Generadas (Test Roles)"},{"id":279,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following is a typical exit criteria for system testing?","options":["A) Test environment readiness","B) Ability to log in","C) Estimated defect density is reached","D) Requirements translated to given/when/then"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#31, LO: FL-5.1.3). Justification: Estimated defect density is reached","source":"Official Sample Exam A Q#31"},{"id":280,"chapter":5,"topic":"Managing the Test Activities","question":"His team uses the three-point estimation technique to estimate the testing effort for a new high-risk feature. The following estimates were made: \u2022 Most optimistic estimate: 2 person-hours \u2022 Most probable estimate: 11 person-hours \u2022 Most pessimistic estimate: 14 person-hours\\n\\nWhat is the final estimate?","options":["A) 9 person-hours","B) 14 person-hours","C) 11 person-hours","D) 10 person-hours"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#32, LO: FL-5.1.4). Justification: 10 person-hours","source":"Official Sample Exam A Q#32"},{"id":281,"chapter":5,"topic":"Managing the Test Activities","question":"It is testing a mobile app that allows users to find a nearby restaurant based on the type of food they want to eat. Consider the following list of test cases, priorities (i.e., a lower number means a higher priority), and dependencies: Test Case Number Test Condition Covered Priority Logical Dependency TC 001 Select Food Type 3 none TC 002 Select Restaurant 2 TC 001 TC 003 Get Directions 1 TC 002 TC 004 Call Restaurant 2 TC 002 TC 005 Make a Reservation 3 TC 002\\n\\nWhich Of the following test cases should be executed thirdly?","options":["A) TC 003","B) TC 005","C) TC 002","D) TC 001"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#33, LO: FL-5.1.5). Justification: TC 003","source":"Official Sample Exam A Q#33"},{"id":282,"chapter":5,"topic":"Managing the Test Activities","question":"Consider the following test categories (1-4) and Agile Testing Quadrants (A-D):\\n\\nHow do the following test categories map to the agile testing quadrants?\\n\\n1. Usability Testing\\n2. Component Testing\\n3. Functional Testing\\n4. Reliability Testing\\n\\nA. Agile Testing Quadrant Q1: Technology-oriented, supporting the development team  \\nB. Agile Testing Quadrant Q2: Business-oriented, supporting the development team  \\nC. Agile Testing Quadrant Q3: Business-oriented, Product Critique  \\nD. Agile Testing Quadrant Q4: Technology Oriented, Product Critique","options":["A) 1C, 2A, 3B, 4D","B) 1D, 2A, 3C, 4B","C) 1C, 2B, 3D, 4A","D) 1D, 2B, 3C, 4A"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#34, LO: FL-5.1.7). Rationale: 1C, 2A, 3B, 4D","source":"Official Sample Exam A Q#34"},{"id":283,"chapter":5,"topic":"Managing the Test Activities","question":"During a risk analysis the following risk was identified and evaluated: \u2022 Risk: Response time is too long to generate a report \u2022 Risk probability: medium; risk impact: high \u2022 Risk response: o An independent testing team performs performance efficiency testing during system testing o A selected sample of end users performs alpha testing and beta testing prior to release\\n\\nWhat action do you propose to take in response to this analyzed risk?","options":["A) Acceptance of risk","B) Contingency plan","C) Risk mitigation","D) Risk transfer"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#35, LO: FL-5.2.4). Rationale: Risk mitigation","source":"Official Sample Exam A Q#35"},{"id":284,"chapter":5,"topic":"Managing the Test Activities","question":"What work product can an agile team use to show the amount of work that has been completed and the total amount of work remaining for a given iteration?  ","options":["A) Acceptance criteria","B) Defect report","C) Test completion report","D) Burndown chart"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#36, LO: FL-5.3.3). Rationale: Burndown chart","source":"Official Sample Exam A Q#36"},{"id":285,"chapter":5,"topic":"Managing the Test Activities","question":"You need to update one of the automated test scripts to be aligned with a new requirement.\\n\\nWhich process indicates that you should create a new version of the test script in the test repository?","options":["A) Traceability management","B) Maintenance tests","C) Configuration management","D) Requirements engineering"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#37, LO: FL-5.4.1). Rationale: Configuration Management","source":"Official Sample Exam A Q#37"},{"id":286,"chapter":5,"topic":"Managing the Test Activities","question":"Received the following defect report from the developers stating that the anomaly described in this test report is not reproducible. Application freezes 2022-May-03 \u2013 John Doe \u2013 Rejected Application freezes after entering \u201cTest Input: $\xe4\u201d in the Name field on the new user creation screen. Tried logging out, logging in with test_admin01 account, same issue. Tried with other test admin accounts, same issue. No error message received; The log (see attached) contains a fatal error notification. Based on test case TC-1305, the application should accept the provided input and create the user. Please fix with high priority, this feature is related to REQ-0012\\n\\nwhich is a new critical business requirement. What critical information is MISSING from this test report that would have been helpful to the developers?","options":["A) Expected result and actual result","B) References and status of the defect","C) Test environment and test element","D) Priority and severity"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#38, LO: FL-5.5.1). Rationale: Test Environment and Test Item","source":"Official Sample Exam A Q#38"},{"id":317,"chapter":5,"topic":"Managing the Test Activities","question":"Your team follows a process that uses the DevOps delivery pipeline. The first three steps are: (1) Code development (2) Push the code to the version control system and merge it with the \'test\' branch (3) Run component tests of the pushed code.\\n\\nWhich of the following is the BEST option as an entry criterion for step (2) of this pipeline?","options":["A) Static analysis returns no high-severity warnings for the pushed code","B) The version control system reports no conflicts when merging the code with the \'test\' branch","C) The component tests are compiled and ready to run","D) Statement coverage is at least 80%"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#30, LO: FL-5.1.3). Rationale: Static analysis with no serious warnings is the most appropriate entry criterion before pushing the code to the version control system.","source":"Official Sample Exam B Q#30"},{"id":318,"chapter":5,"topic":"Managing the Test Activities","question":"You want to estimate the testing effort for a new project using ratio-based estimation. You calculate the testing effort/development effort ratio using averaged data from four similar historical projects. The table shows: P1: Development $800,000, Testing $40,000 | P2: $1,200,000 / $130,000 | P3: $600,000 / $70,000 | P4: $1,000,000 / $120,000. The estimated development effort for the new project is $800,000.\\n\\nWhat is your estimate of the testing effort?","options":["A) $40,000","B) $80,000","C) $81,250","D) $82,500"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#31, LO: FL-5.1.4). Rationale: The average ratio is (40+130+70+120)/(800+1200+600+1000) = 360/3600 = 10%. 10% of $800,000 = $80,000.","source":"Official Sample Exam B Q#31"},{"id":320,"chapter":5,"topic":"Managing the Test Activities","question":"According to the testing quadrants model,\\n\\nwhich of the following falls in quadrant Q1 (\'technology-oriented\' and \'supports the team\')?","options":["A) Usability testing","B) Functional testing","C) User acceptance testing","D) Component integration testing"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#33, LO: FL-5.1.7). Rationale: Component integration tests are technical and support the development team, which is why they belong to quadrant Q1.","source":"Official Sample Exam B Q#33"},{"id":321,"chapter":5,"topic":"Managing the Test Activities","question":"Given the following risks:\\n\\nWhich of the following gives the BEST match between risks and mitigation activities?\\n\\n1. An inefficient loop implementation causes slow system responses\\n2. Consumers change their preferences\\n3. Flooding of the server room\\n4. Patients over a certain age receive incorrect reports\\n\\nA. Risk acceptance  \\nB. Performance efficiency testing  \\nC. Use of boundary value analysis as a technique  \\nD. Risk transfer","options":["A) 1C, 2D, 3A, 4B","B) 1B, 2D, 3A, 4C","C) 1B, 2A, 3D, 4C","D) 1C, 2A, 3D, 4B"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#34, LO: FL-5.2.4). Rationale: Performance risk->performance testing (1B), market risk->acceptance (2A), flood risk->transfer/insurance (3D), accuracy risk->boundary values (4C).","source":"Official Sample Exam B Q#34"},{"id":322,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following is a product quality metric?  ","options":["A) Mean time to failure (MTTF)","B) Number of defects found","C) Requirements coverage","D) Defect detection percentage"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#35, LO: FL-5.3.1). Rationale: MTTF (mean time to failure) measures the product\'s reliability in production, so it is a product quality metric.","source":"Official Sample Exam B Q#35"},{"id":323,"chapter":5,"topic":"Managing the Test Activities","question":"You are a member of a test team located in North America, developing a product for a customer in Europe. The team is agile, follows DevOps, and uses a CI/CD pipeline.\\n\\nWhich of the following is the LEAST effective way to communicate test progress to the customer?","options":["A) Face to face (in person)","B) Dashboards","C) Email","D) Video conference"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#36, LO: FL-5.3.3). Rationale: With the team in North America and the customer in Europe, in-person communication is impractical and is the least effective option.","source":"Official Sample Exam B Q#36"},{"id":324,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following options BEST describes an example of\\n\\nhow configuration management (CM) supports testing?","options":["A) With the environment version number, the CM tool can retrieve the version numbers of the libraries, stubs, and drivers used in that environment","B) With a record of input values, the CM tool can run the test cases for those configurations and calculate coverage","C) With data about the purchase date of a software license, the CM tool automatically generates information about how close the license is to expiring","D) With the test case version number, the CM tool can automatically generate test data for that case"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#37, LO: FL-5.4.1). Rationale: CM allows linking environment versions with specific versions of libraries, stubs, and drivers, ensuring reproducibility of test environments.","source":"Official Sample Exam B Q#37"},{"id":353,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following is NOT a purpose of a test plan?  ","options":["A) Document the means and schedule of the test activities","B) Serve as a means of communication among the test team members","C) Record the defects found during test execution","D) Document the risks and mitigation approaches"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#1, LO: FL-5.1.1). Rationale: Recording defects is the responsibility of the defect management system, not the test plan.","source":"Official Sample Exam C Q#30"},{"id":354,"chapter":5,"topic":"Managing the Test Activities","question":"At the start of each iteration, the team estimates the amount of work (in person-days) it can complete during that iteration. At the end of the iteration, the actual work completed is measured. Over time, the historical data shows that the team completes on average 80% of the estimated work. If in the next iteration the team estimates 50 person-days of work,\\n\\nhow many person-days should the test manager plan as actual effort?","options":["A) 40","B) 50","C) 62","D) 63"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#2, LO: FL-5.1.4). Rationale: If historically 80% of the estimate is completed, the actual estimate would be 50 x 0.80 = 40 person-days.","source":"Official Sample Exam C Q#31"},{"id":356,"chapter":5,"topic":"Managing the Test Activities","question":"What does the test pyramid model show?  ","options":["A) The different test levels and the most likely defect types at each level","B) The relative number of tests recommended at each test level, with more tests at the lower levels","C) The relative cost of finding and fixing defects at each test level","D) The recommended sequence in which the different test levels should be executed"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#4, LO: FL-5.1.7). Rationale: The test pyramid shows that there should be many component tests (base) and few system or E2E tests (top), since the lower ones are faster and cheaper.","source":"Official Sample Exam C Q#33"},{"id":357,"chapter":5,"topic":"Managing the Test Activities","question":"What is the relationship between test quadrants, test levels, and test types?  ","options":["A) Test quadrants include test levels; test types help identify which test quadrants apply to each level","B) Test types help identify which test quadrants apply; test quadrants help identify which test levels should be used","C) Test quadrants help identify which test types apply to each level; test types can span multiple levels","D) Test levels are subsets of test quadrants; test quadrants are subsets of test types"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#5, LO: FL-5.1.7). Rationale: Test quadrants help identify which test types (functional, non-functional, white-box, etc.) are applicable at each test level.","source":"Official Sample Exam C Q#34"},{"id":358,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following is an example of\\n\\nhow product risk analysis can influence the thoroughness and approach of testing?","options":["A) Increase the test coverage of the highest-risk features","B) Prioritize testing of recently implemented features over older ones","C) Run the shortest tests first to get quick results","D) Concentrate the testing effort on the components developed by less experienced testers"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#6, LO: FL-5.2.3). Rationale: Risk analysis directs the testing effort toward the highest-risk areas, increasing their coverage.","source":"Official Sample Exam C Q#35"},{"id":359,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following test process activities makes the MOST use of test progress reports?  ","options":["A) Test planning","B) Test monitoring and control","C) Test analysis","D) Test design"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#7, LO: FL-5.3.2). Rationale: Test monitoring and control uses the progress reports to compare actual progress with the planned progress and make corrective decisions.","source":"Official Sample Exam C Q#36"},{"id":360,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following is NOT an example of\\n\\nhow configuration management (CM) supports testing?","options":["A) Maintaining a record of the configuration items that make up the test environment","B) Automatically generating additional test cases when defects are detected in the software","C) Enabling traceability between test cases and the work items they test","D) Ensuring that all team members use the same version of the test cases"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#8, LO: FL-5.4.1). Rationale: Automatic generation of test cases is not a function of configuration management.","source":"Official Sample Exam C Q#37"},{"id":361,"chapter":5,"topic":"Managing the Test Activities","question":"Consider the following defect report for a shopping web application: Application: WebShop v0.9.1. Module: Shopping cart. Summary: \'The cart Delete button does not work\\n\\nwhen there is exactly 1 item\'. Steps:\\n\\n1) Log in\\n\\n2) Add 1 item to the cart\\n\\n3) Click Delete. Expected result: The item is removed and the cart is empty. Actual result: Nothing happens. Which of the following elements is MISSING from this defect report?","options":["A) The identifier of the test case that revealed the defect","B) The system environment/configuration data","C) The defect severity","D) The defect priority"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#9, LO: FL-5.5.1). Rationale: The report does not specify the operating system version, browser, or other environment data needed to reproduce the defect.","source":"Official Sample Exam C Q#38"},{"id":388,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following BEST defines the EXIT criteria in a testing project?  ","options":["A) The budget is approved","B) The budget is exhausted","C) The test basis is available","D) The test cases achieved at least 80% statement coverage"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#30, LO: FL-5.1.3). Rationale: The budget is exhausted.","source":"Official Sample Exam D Q#30"},{"id":389,"chapter":5,"topic":"Managing the Test Activities","question":"The team wants to estimate the time to execute four test cases. The measures for one case are: Best case: 1h, Worst case: 8h, Most likely: 3h. Using the three-point estimation technique,\\n\\nwhat is the final estimate for the FOUR test cases?","options":["A) 14 hours","B) 3.5 hours","C) 16 hours","D) 12 hours"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#31, LO: FL-5.1.4). Rationale: Three-point per case = (1 + 4x3 + 8)/6 = 3.5h; x4 cases = 14 hours.","source":"Official Sample Exam D Q#31"},{"id":390,"chapter":5,"topic":"Managing the Test Activities","question":"You have a traceability matrix and you want to prioritize the test cases following the additional coverage prioritization technique. You will execute four test cases. According to standard techniques,\\n\\nwhich test case should be executed LAST?","options":["A) TC1","B) TC2","C) TC3","D) TC4"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#32, LO: FL-5.1.5). Rationale: TC2.","source":"Official Sample Exam D Q#32"},{"id":391,"chapter":5,"topic":"Managing the Test Activities","question":"How can testing quadrants be beneficial?  ","options":["A) They help plan by dividing into four phases: component, integration, system, acceptance","B) They help assess high-level coverage based on low-level coverage","C) They help non-technical stakeholders understand the different test types and their relevance by levels","D) They help agile teams communicate according to psychological profiles"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#33, LO: FL-5.1.7). Rationale: They help non-technical stakeholders understand the different test types and their relevance by levels.","source":"Official Sample Exam D Q#33"},{"id":392,"chapter":5,"topic":"Managing the Test Activities","question":"For a given risk, the risk level is $1,000 and its probability is estimated at 50%.\\n\\nWhat is the risk impact?","options":["A) $500","B) $2,000","C) $50,000","D) $200"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#34, LO: FL-5.2.1). Rationale: Risk level = impact x probability, so impact = 1,000 / 0.50 = $2,000.","source":"Official Sample Exam D Q#34"},{"id":393,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following is a product risk?  ","options":["A) Scope creep","B) Poor architecture","C) Cost cutting","D) Lack of tool support"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#35, LO: FL-5.2.2). Rationale: Poor architecture.","source":"Official Sample Exam D Q#35"},{"id":394,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following is NOT a valid purpose for a test report?  ","options":["A) Tracking progress and identifying areas of attention","B) Providing information about the tests executed, results, and defects","C) Providing information about how to reproduce each defect step by step","D) Providing information about the tests planned for the next period"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#36, LO: FL-5.3.2). Rationale: Providing information about how to reproduce each defect step by step (that belongs in the defect report, not the test report).","source":"Official Sample Exam D Q#36"},{"id":395,"chapter":5,"topic":"Managing the Test Activities","question":"A user reported a failure. Support asked them for the software version. With that version, the team rebuilt the release files,\\n\\nwhich allowed the developer to analyze and fix the defect. What process made this activity possible?","options":["A) Risk management","B) Test monitoring and control","C) Whole team approach","D) Configuration management"],"correctAnswer":3,"explanation":"Option D) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#37, LO: FL-5.4.1). Rationale: Configuration management.","source":"Official Sample Exam D Q#37"},{"id":396,"chapter":5,"topic":"Managing the Test Activities","question":"Consider a defect report for a Book Lending System.\\n\\nWhich of the following actions would MOST help the developer reproduce the failure quickly?","options":["A) Add information about which users and which books are affected in the \'Description\' section","B) Fill in the missing value of the \'Priority\' field","C) Add memory dumps after each step to the \'Attachments\' section","D) Repeat the test case for different environments and create a separate report for each one"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#38, LO: FL-5.5.1). Rationale: Adding information about which users and which books are affected helps the developer reproduce the failure.","source":"Official Sample Exam D Q#38"},{"id":413,"chapter":5,"topic":"Managing the Test Activities","question":"You are a test manager and you need to estimate the test effort for a new project. You have historical data from 5 similar projects.\\n\\nWhich estimation approach would you use PRIMARILY?","options":["A) Wideband Delphi exclusively","B) Metrics-based estimation using historical data from similar projects","C) Planning Poker with the development team","D) Function point estimation without historical data"],"correctAnswer":1,"explanation":"Metrics-based estimation uses historical data from previous similar projects to calculate the effort. With 5 historical projects available, this approach is the most solid and objective.","source":"banco"},{"id":414,"chapter":5,"topic":"Managing the Test Activities","question":"Your test plan indicates 200 planned test cases for the week. At the end of the week, you executed 140 and found 25 defects, of\\n\\nwhich 8 are critical and still unfixed. What information is MOST relevant for deciding whether to release the software?","options":["A) Only the execution percentage (70%)","B) Only the total number of defects (25)","C) The density of unresolved critical defects and the exit criteria defined in the plan","D) The number of pending tests (60)"],"correctAnswer":2,"explanation":"The exit criteria of the test plan define the conditions for releasing. The unresolved critical defects are the most relevant factor for the release decision.","source":"banco"},{"id":415,"chapter":5,"topic":"Managing the Test Activities","question":"A defect has \'critical\' severity (the system crashes) but \'low\' priority assigned by the product owner.\\n\\nWhat is the MOST likely explanation?","options":["A) It is an error; severity and priority should always match","B) The defect affects a rarely used feature or one that is not critical for the business at this time","C) The product owner does not understand the technical severity","D) Priority is always more important than severity in Agile"],"correctAnswer":1,"explanation":"Severity (technical impact) and priority (business urgency) are independent concepts. A crash in a rarely used feature can have high technical severity but low business priority.","source":"banco"},{"id":416,"chapter":5,"topic":"Managing the Test Activities","question":"You work on a project with an identified product risk: \'The payment module could fail under high load\'.\\n\\nWhat type of testing should you prioritize to mitigate this risk?","options":["A) Regression testing of the payment module","B) Performance/load testing of the payment module","C) Static review of the payment module code","D) User acceptance testing of the payment module"],"correctAnswer":1,"explanation":"The identified risk is performance under load, so performance/load testing is the most appropriate to validate and mitigate that specific product risk.","source":"banco"},{"id":423,"chapter":5,"topic":"Managing the Test Activities","question":"Which document describes the scope, approach, resources, schedule, and objectives of the test activities for a specific project?  ","options":["A) Test strategy","B) Test plan","C) Test case specification","D) Test summary report"],"correctAnswer":1,"explanation":"The Test Plan describes, for a specific project: scope, objectives, approach, entry/exit criteria, resources, risks, and schedule of the test activities.","source":"banco"},{"id":436,"chapter":5,"topic":"Managing the Test Activities","question":"You are a test manager. The project is 2 weeks behind schedule. The director asks to cut the testing time in half.\\n\\nWhat is the MOST professional response?","options":["A) Accept and run all the tests faster","B) Randomly remove half of the test cases","C) Present the risk analysis: what coverage is lost, what risks increase, and propose risk-based prioritization","D) Completely refuse to reduce the testing time"],"correctAnswer":2,"explanation":"The professional response is to use risk management: show which areas will be left uncovered, the impact on quality, and propose a risk-based prioritization strategy to maximize value with the available time.","source":"banco"},{"id":437,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following is an example of a \'project risk\' (vs product risk) in the context of testing?  ","options":["A) The payment module may have security vulnerabilities","B) The unavailability of the test environment may delay execution","C) The search algorithm may return incorrect results","D) The system may degrade under high user load"],"correctAnswer":1,"explanation":"Project risks threaten the project plan (resources, environments, tools, schedule). Product risks threaten the software quality. The lack of an environment is a project risk.","source":"banco"},{"id":443,"chapter":5,"topic":"Managing the Test Activities","question":"What is the purpose of the \'test summary report\' at the end of a phase?  ","options":["A) List all the test cases to be executed","B) Communicate the results, metrics, defects, and exit criteria evaluation to the stakeholders","C) Describe the test design techniques used","D) Define the budget for the next test phase"],"correctAnswer":1,"explanation":"The test summary report communicates the test results to the stakeholders: executed/passed/failed cases, defects found, coverage achieved, and evaluation of the exit criteria.","source":"banco"},{"id":451,"chapter":5,"topic":"Managing the Test Activities","question":"PRACTICAL CASE: You have 100 test cases to execute in 5 days. After 3 days you have executed 50 cases, found 15 defects (5 critical), and the development team has fixed 8. The exit criteria require: 90% execution, 0 open critical defects.\\n\\nWhat is your situation?","options":["A) You can release: you have met the exit criteria","B) You cannot release: test cases are missing and you have open critical defects","C) You can release because you have found and fixed most defects","D) You must escalate to the customer to decide whether to release or not"],"correctAnswer":1,"explanation":"You do not meet the exit criteria: you only have 50% execution (you need 90%) and there are still open critical defects. With open critical defects, the exit criteria are not met.","source":"banco"},{"id":452,"chapter":5,"topic":"Managing the Test Activities","question":"PRACTICAL CASE: Your team identified the following product risks: R1(prob=High, impact=High), R2(prob=Low, impact=High), R3(prob=High, impact=Low), R4(prob=Low, impact=Low). Using risk-based testing, in\\n\\nwhat order do you prioritize the tests?","options":["A) R4, R3, R2, R1","B) R1, R2, R3, R4","C) R1, R3, R2, R4","D) R2, R1, R4, R3"],"correctAnswer":2,"explanation":"The risk level = probability x impact. R1(H x H = very high), R3 and R2 (medium-high), R4(L x L = low). R1 first, then R3 and R2 (similar level), finally R4. The correct order is R1, R3, R2, R4.","source":"banco"},{"id":459,"chapter":5,"topic":"Managing the Test Activities","question":"PRACTICAL CASE: You are managing testing of a mobile app. 3 days before release, your team finds a serious defect in the payment flow. The developer\'s fix will take 2 days.\\n\\nWhat is the correct process according to ISTQB?","options":["A) Automatically cancel the release","B) Record the defect, assess the impact and risk, escalate for a business decision on delaying or releasing with a documented workaround","C) The tester must fix the defect directly","D) Ignore the defect if the customer has not reported it yet"],"correctAnswer":1,"explanation":"The correct process is: document the defect (bug report), analyze impact/risk, and escalate to the stakeholders with information to decide. It is not the tester\'s unilateral decision to delay or release; it is an informed business decision.","source":"banco"},{"id":464,"chapter":5,"topic":"Managing the Test Activities","question":"Which of the following options best describes the \'exit criteria\' of a test phase?  ","options":["A) The conditions for starting testing","B) The conditions that must be met to consider a test phase complete","C) The maximum number of defects allowed in production","D) The project deadline"],"correctAnswer":1,"explanation":"The exit criteria (or Definition of Done) define when a test phase can be considered complete: e.g., 95% of cases executed, 0 open critical defects, coverage at least 80%.","source":"banco"},{"id":"q_batch2_1ksnvb89h","chapter":5,"topic":"Managing the Test Activities","question":"Which of the following statements best describes\\n\\nhow configuration management contributes to effective testing?","options":["It allows testers to work with obsolete versions of the test cases.","It facilitates the identification and control of the test items and their versions.","It ensures that all defects are documented without the need for versions.","It eliminates the need to maintain change records for the test cases."],"correctAnswer":1,"explanation":"A. Incorrect. Working with obsolete versions can cause confusion and errors in testing. B. Correct. Configuration management allows controlling and identifying the test items throughout their life cycle, thus facilitating effective testing. C. Incorrect. Defect documentation does not depend on this management. D. Incorrect. Configuration management does require maintaining change records to ensure traceability and version control.","source":"banco-extra"},{"id":"q_batch2_apxr5xluy","chapter":5,"topic":"Managing the Test Activities","question":"In\\n\\nwhat way can testers contribute to process improvement in release planning?","options":["Testers analyze the results of previous tests to identify areas for improvement in the development process.","Testers only execute test cases without getting involved in planning.","Testers are in charge of documenting all the errors they find, without participating in planning discussions.","Testers have no influence on release planning, since their role is strictly technical."],"correctAnswer":0,"explanation":"A. Correct. Analyzing the results of previous tests allows testers to suggest process improvements, which adds value to planning. B. Incorrect. The active participation of testers in planning is essential to the project\'s success. C. Incorrect. Documenting errors is important, but testers should also participate in planning and process discussions. D. Incorrect. Testers play a crucial role in planning and delivery, since their experience can influence the process.","source":"banco-extra"},{"id":"q_batch2_du99np3p4","chapter":5,"topic":"Managing the Test Activities","question":"During the testing of a system, several errors were reported and fixed. After a new version of the software was released, it is decided to run the tests again.\\n\\nWhich of the following tests are considered confirmation tests?","options":["Testing a new module that had not been tested before.","Tests that were previously run and failed, now performed to verify the fix.","Load tests performed to verify performance under extreme conditions.","Integration tests of modules added in the new version."],"correctAnswer":1,"explanation":"A. This option is not considered a confirmation test, since it concerns a new module and is not related to verifying fixed defects. B. Correct. The tests that were previously run and failed are repeated to confirm that the defects have been fixed, which classifies them as confirmation tests. C. Load tests focus on performance and are not related to verifying defect fixes. D. Integration tests are not confirmation tests unless run specifically to validate fixes from previous tests.","source":"banco-extra"},{"id":"q_batch2_j0vlxcr58","chapter":5,"topic":"Managing the Test Activities","question":"Which of the following reports is most appropriate for communicating the current test status to the stakeholders during the software development life cycle?  ","options":["Test progress report","Regression test report","Open defects report","Incident report"],"correctAnswer":0,"explanation":"A. Correct. The test progress report provides a summary of the current test status, including which tests have been completed and which are pending. B. Incorrect. The regression test report focuses on the tests performed after software changes. C. Incorrect. The open defects report shows existing problems but does not communicate the test progress itself. D. Incorrect. The incident report refers to problems found, not an overview of the test status.","source":"banco-extra"},{"id":"q_batch2_jfwjvhmmc","chapter":5,"topic":"Managing the Test Activities","question":"You prepared the following defect report: Defect ID: BUG-00456. Date: 15-01-2025. Title: The \'Submit Payment\' button does not respond after selecting a payment method. Severity: High. Priority: Critical. Reported by: Test Analyst. Configuration: Application version 2.15.087, Browser: Firefox 118.0.2.0. Expected result: The \'Submit Payment\' button should process the payment information and redirect to the payment confirmation page. Attachments: Screenshot, Screen recording.\\n\\nWhat is the MOST important information missing from this defect report that a test analyst should include to facilitate a quick resolution?","options":["The detailed sequence of actions that reproduced the failure.","The analysis method used to identify the problem.","The operating system specifications and device architecture.","A proposed technical solution to resolve the incident."],"correctAnswer":0,"explanation":"A. Correct. Without the reproduction steps, developers cannot replicate or investigate the defect. B. Incorrect. The test technique used is not necessary to resolve the defect. C. Incorrect. The environment configuration is already partially included and is not the most critical. D. Incorrect. Testers should not suggest technical solutions; that is the developers\' responsibility.","source":"banco-extra"},{"id":"q_batch2_p48e09xyk","chapter":5,"topic":"Managing the Test Activities","question":"A risk has been identified during the analysis of a new software: Risk: The application may not be compatible with old browsers. Risk probability: high; risk impact: medium. Risk response: perform compatibility testing on various old browsers, provide documentation about the system requirements.\\n\\nWhat would be the most appropriate measure to implement for this analyzed risk?","options":["Risk mitigation","Risk transfer","Risk acceptance","Risk elimination"],"correctAnswer":0,"explanation":"A. Correct. Compatibility testing is a risk mitigation action. B. Incorrect. Risk transfer is not applicable in this context. C. Incorrect. Accepting the risk does not involve taking concrete actions to handle it. D. Incorrect. Risk elimination is not feasible in this case.","source":"banco-extra"},{"id":"q_batch2_py9kk1zxn","chapter":5,"topic":"Managing the Test Activities","question":"Which of the following situations would best justify the use of 3-value Boundary Value Analysis (BVA) instead of 2-value BVA?  ","options":["When the number of test cases needs to be reduced due to time constraints","When very subtle off-by-one implementation defects are suspected","When the partitions are not ordered numerically","When the code implements simple comparisons such as \'greater than\' or \'less than\'"],"correctAnswer":1,"explanation":"A. Incorrect. 3-value BVA requires more test cases, not fewer. B. Correct. According to the syllabus, 3-value Boundary Value Analysis is more rigorous than 2-value BVA since it can detect defects overlooked by 2-value BVA (for example, an off-by-one defect that the extra boundary value catches). C. Incorrect. BVA can only be used for ordered partitions. D. Incorrect. 2-value BVA would be sufficient for well-implemented simple comparisons.","source":"banco-extra"},{"id":"q_batch2_zras116y8","chapter":5,"topic":"Managing the Test Activities","question":"Which of the following statements BEST describes the role of a test leader in a test team?  ","options":["They are responsible for executing all manual tests.","They coordinate the test activities and manage the test team.","They are the main contact with the client for delivering requirements.","They are in charge of documenting the software requirements."],"correctAnswer":1,"explanation":"A. Incorrect. Although they may participate in testing, they are not in charge of executing all manual tests. B. Correct. The test leader coordinates the activities and manages the team. C. Incorrect. This role generally corresponds to the product owner or business analyst. D. Incorrect. Documenting requirements is typically done by business analysts or developers.","source":"banco-extra"},{"id":1042,"chapter":6,"topic":"Test Tools","question":"Which of the following test tools facilitates requirements management and traceability?  ","options":["Test management tools","Test automation tools","Defect management tools","Requirements management tools"],"correctAnswer":3,"explanation":"A. Incorrect. Although test management tools help plan and control tests, they are not specifically focused on requirement management and traceability. B. Incorrect. Test automation tools are used to execute tests automatically, but they do not focus on requirement management. C. Incorrect. Defect management tools are used to track errors and problems, not to manage requirement traceability. D. Correct. Requirement management tools are specifically designed to facilitate the management and traceability of requirements throughout the project lifecycle.","source":"Errores Reportados - Set 2"},{"id":287,"chapter":6,"topic":"Test Tools","question":"What testing activity does a data preparation tool support?  ","options":["A) Test monitoring and test control","B) Test analysis","C) Test design and test implementation","D) Test completion"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#39, LO: FL-6.1.1). Rationale: Test Design and Test Implementation","source":"Official Sample Exam A Q#39"},{"id":288,"chapter":6,"topic":"Test Tools","question":"Which element correctly identifies a potential risk of performing test automation?  ","options":["A) Test impediments","B) Branch coverage achieved","C) Test progress","D) New risks within the test cycle"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#40, LO: FL-6.2.1). Rationale: Branch coverage achieved","source":"Official Sample Exam A Q#40"},{"id":326,"chapter":6,"topic":"Test Tools","question":"Given the following descriptions:\\n\\nWhich of the following options gives the BEST match between the descriptions and the categories?\\n\\n1. Support workflow tracking\\n2. Facilitate communication\\n3. Virtual machines\\n4. Support reviews\\n\\nA. Static testing tools  \\nB. Tools that support scalability and standardization of deployment  \\nC. DevOps tools  \\nD. Collaboration tools","options":["A) 1A, 2B, 3C, 4D","B) 1B, 2D, 3C, 4A","C) 1C, 2D, 3B, 4A","D) 1D, 2C, 3A, 4B"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#39, LO: FL-6.1.1). Rationale: DevOps\u2192workflow tracking (1C), Collaboration\u2192communication (2D), Scalability\u2192virtual machines (3B), Static\u2192reviews (4A).","source":"Official Sample Exam B Q#39"},{"id":327,"chapter":6,"topic":"Test Tools","question":"Which of the following is MOST LIKELY an advantage of test automation?  ","options":["A) Provides coverage measures that are too complex for humans to obtain manually","B) Shares testing responsibility with the tool vendor","C) Eliminates the need for critical thinking when analyzing test results","D) Generates test cases from analysis of the program code"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample B, Q#40, LO: FL-6.2.1). Rationale: Automation makes it possible to obtain complex coverage metrics that would be impractical to calculate manually.","source":"Official Sample Exam B Q#40"},{"id":362,"chapter":6,"topic":"Test Tools","question":"Tools in\\n\\nwhich category help organize test cases, detected defects, and test results?","options":["A) Test management tools","B) Static analysis tools","C) Test execution tools","D) Test automation tools"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#10, LO: FL-6.1.1). Rationale: Test management tools (such as Jira, TestRail) organize and track test cases, defects, and results.","source":"Official Sample Exam C Q#39"},{"id":397,"chapter":6,"topic":"Test Tools","question":"Given the test tool categories (i. Collaboration,\\n\\nii. DevOps,\\n\\niii. Management,\\n\\niv. Non-functional,\\n\\nv. Design/Implementation). Tools of\\n\\nwhich categories are MOST likely to support test execution?","options":["A) i, v","B) ii, iv","C) i, iii, v","D) ii, iii, iv"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#39, LO: FL-6.1.1). Rationale: ii, iv (DevOps, Non-functional).","source":"Official Sample Exam D Q#39"},{"id":398,"chapter":6,"topic":"Test Tools","question":"Which of the following is MOST likely a risk of test automation?  ","options":["A) Detection of additional high-severity defects","B) Providing metrics too complex for humans","C) Incompatibility with the development platform","D) Substantial reduction in execution time"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the Official ISTQB CTFL v4.0 Exam (Sample D, Q#40, LO: FL-6.2.1). Rationale: Incompatibility with the development platform.","source":"Official Sample Exam D Q#40"},{"id":417,"chapter":6,"topic":"Test Tools","question":"Your organization wants to implement a GUI test automation tool.\\n\\nWhich of the following factors represents the GREATEST long-term risk?","options":["A) The initial cost of the tool license","B) The fragility of scripts when the user interface changes frequently","C) The team\'s initial learning time","D) Incompatibility with the system\'s programming language"],"correctAnswer":1,"explanation":"GUI automation scripts are very fragile to interface changes (locators, IDs, positions). In projects with a rapidly evolving UI, maintenance can outweigh the benefit of automation.","source":"banco"},{"id":418,"chapter":6,"topic":"Test Tools","question":"What is the key difference between a test execution tool and a test management tool?  ","options":["A) There is no difference, they are the same tool","B) The execution tool automates running scripts; the management tool organizes, plans, and records the progress and results of testing","C) The management tool is only for manual testing; the execution tool for automated testing","D) The execution tool generates reports; the management tool runs the test cases"],"correctAnswer":1,"explanation":"Execution tools (e.g., Selenium, JUnit) run tests automatically. Management tools (e.g., TestRail, Zephyr) organize cases, plans, test cycles, and track results and coverage.","source":"banco"},{"id":438,"chapter":6,"topic":"Test Tools","question":"A company is evaluating the ROI of automating its regression suite (500 manual cases, 2h per manual run). If automating costs 200 hours and each automated run takes 15 min,\\n\\nhow many runs are needed to recoup the investment?","options":["A) 10 runs","B) 50 runs","C) 100 runs","D) 200 runs"],"correctAnswer":2,"explanation":"Savings per run: 2h - 0.25h = 1.75h. To recoup 200h of investment: 200/1.75 \u2248 114 runs. The closest option is 100, although the exact math gives ~114. (In many exams the calculation is simplified.)","source":"banco"},{"id":444,"chapter":6,"topic":"Test Tools","question":"Which of the following is a REAL benefit of test automation?  ","options":["A) It completely eliminates the need for manual testing","B) It allows frequent and consistent regression to be run with less effort per run after the initial investment","C) It finds more types of defects than manual testing","D) It is always cost-effective regardless of the type of project"],"correctAnswer":1,"explanation":"Automation allows regression to be run repeatedly with consistency and less effort per cycle. It does not eliminate manual testing, is not always cost-effective, and humans detect some defects that automation does not.","source":"banco"},{"id":456,"chapter":6,"topic":"Test Tools","question":"PRACTICAL CASE: Your company wants to adopt an API test automation tool. The team evaluates: cost, learning curve, CI/CD integration, REST/SOAP protocol support, and maintainability.\\n\\nWhich is the MOST critical factor to ensure long-term success?","options":["A) The lowest license cost","B) Ease of maintenance and integration with the existing CI/CD pipeline","C) Supporting the largest possible number of protocols","D) Having the most intuitive interface"],"correctAnswer":1,"explanation":"In the long term, script maintainability and CI/CD integration are critical. Tests that are hard to maintain get abandoned. Without pipeline integration, automation does not provide continuous value.","source":"banco"},{"id":463,"chapter":6,"topic":"Test Tools","question":"What is a \'keyword-driven test automation framework\'?  ","options":["A) A framework where the keywords are access passwords","B) A framework where test cases are described using high-level keywords that represent actions (e.g.: \'Login\', \'ClickButton\', \'VerifyText\')","C) A framework only for security testing","D) A framework that uses artificial intelligence to generate tests"],"correctAnswer":1,"explanation":"Keyword-driven testing uses keywords or action words that represent system operations. Test cases are written in tables with these keywords, separating test design from its technical implementation.","source":"banco"},{"id":"q_batch3_bi3fp7yfr","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following statements about test management is correct?  ","options":["Test management is not necessary if development is done in an agile environment.","Test management should be applied only in the final stages of development.","Test management helps to plan, monitor and control the testing process.","Test management is the sole responsibility of the development team."],"correctAnswer":2,"explanation":"A. Incorrect. Test management is important in all environments, including agile ones. B. Incorrect. Test management must be continuous throughout the entire development lifecycle. C. Correct. Test management is essential for proper planning and control. D. Incorrect. Test management is the responsibility of the entire team, not just development.","source":"User Provided Batch 3"},{"id":"q_batch3_nfi6e89ri","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which level of testing best corresponds to the identification of defects related to the interface between different modules of a system?  ","options":["Acceptance tests","System tests","Integration tests","Component testing"],"correctAnswer":2,"explanation":"A. Incorrect. Acceptance testing focuses on validating whether the system meets the customer\'s requirements, not on the interface between modules. B. Incorrect. System testing evaluates the system as a whole, but does not focus specifically on the interaction between modules. C. Correct. Integration testing focuses on verifying the communication and interaction between different components or modules of the system. D. Incorrect. Component testing focuses on testing a single module in isolation, not its interaction with others.","source":"User Provided Batch 3"},{"id":"q_batch3_vitftajfv","chapter":2,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following statements adequately describe the levels of testing (1-4) and their specific approaches (A-D)?\\n\\n1. Testing performed to validate full system functionality in a simulated production environment.\\n2. Tests that focus on verifying that individual modules are working correctly.\\n3. Tests that ensure that different modules integrate and work together.\\n4. Testing that involves validation of requirements from the perspective of the end user.\\n\\nA. System testing  \\nB. Component testing  \\nC. Integration testing  \\nD. Acceptance testing","options":["A. 1A, 2B, 3C, 4D","B. 1C, 2A, 3D, 4B","C. 1D, 2C, 3A, 4B","D. 1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"A. Statement 1 correctly describes system tests (1A), which validate the entire system. Statement 2 refers to component testing (2B), where the functionality of individual modules is verified. 3 is related to integration testing (3C), which focuses on the interaction between modules. 4 corresponds to acceptance testing (4D), where the requirements are validated from the perspective of the end user. B. Choice B is incorrect. Statement 1 is not associated with integration testing (1C), but with system testing. Statement 2 correctly describes component testing, but statement 3 does not correctly relate to acceptance testing. C. Choice C is incorrect. Statement 1 does not describe acceptance testing (1D), but rather is a system testing approach. The other descriptions also do not match the corresponding test levels. D. Choice D is incorrect. Statement 1 does not correspond to component testing (1B), but to system testing. The other descriptions are also incorrect regarding the testing levels.","source":"User Provided Batch 3"},{"id":"q_batch4_x1vez8tp7","chapter":2,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following elements are factors that can affect the test strategy in a software project?\\n\\ni. The profile of the test team\\nii. The complexity of the system to be tested\\niii. The availability of hardware resources\\niv. The project management techniques used","options":["i, ii and iii are factors that affect the testing strategy","ii, iii and iv are factors that affect the testing strategy","i, iii and iv are factors that affect the testing strategy","i, ii, iii and iv are factors that affect the testing strategy"],"correctAnswer":0,"explanation":"A.i. It\'s true. The profile of the testing team can influence how testing is carried out. ii. It\'s true. The complexity of the system directly affects the approach and tools used in testing. iii. It\'s true. The availability of hardware resources is crucial for test execution. Therefore, they are all factors that affect the testing strategy. B. ii. It\'s true. The complexity of the system affects the testing approach. iii. It\'s true. The availability of hardware resources is important. iv. It\'s true. Project management techniques can play a role, but it doesn\'t cover all aspects. Therefore, it is not the most complete option. C.i. It\'s true. The profile of the test team is important. iii. It\'s true. The availability of resources is crucial. iv. It\'s true. Project management techniques can play a role, but they are not as relevant as the other factors mentioned. Therefore, it does not cover all relevant aspects. D.i. It\'s true. The profile of the test team influences the testing strategy. ii. It\'s true. The complexity of the system to be tested impacts the strategy. iii. It\'s true. The availability of hardware resources is essential. iv. It\'s true. Project management techniques also have an impact. Therefore, the correct answer is D.P","source":"User Provided Batch 4"},{"id":"q_batch4_d9p5xynen","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following skills is essential for a tester\\n\\nwhen evaluating the quality of a software product? Effective communication Technical knowledge Analytical skills Time management","options":["i and ii are essential; iii and iv are not","iii and iv are essential; i and ii are not","ii and iii are essential; i and iv are not","i and iii are essential; ii and iv are not"],"correctAnswer":3,"explanation":"A. While effective communication and technical knowledge are important, they are not the most essential in quality assessment, as analysis and time management are key in the testing process. B. Although analytical skills and time management are important, the need for communication skills and technical knowledge to correctly evaluate a product cannot be ignored. C. Technical knowledge is crucial, but quality assessment cannot be carried out without communication skills and analytical skills, which are equally essential. D. Correct. Effective communication and analytical skills are fundamental skills for a tester, allowing them to correctly interpret and evaluate test results. Q","source":"User Provided Batch 4"},{"id":"q_batch4_fb7uzan6z","chapter":3,"topic":"Desarrollo y Testing","difficulty":"medium","question":"In your organization, reviews are conducted that have the following characteristics: There is no specific role assigned for the moderator. The goal is to find defects and improve the product. Participants openly discuss their opinions. No formal documentation required at the end.\\n\\nWhat type of review is being carried out?","options":["Informal review","Technical review","Inspection","Guided review"],"correctAnswer":0,"explanation":"A. The features mentioned are typical of an informal review, where a moderator is not required and documentation is minimal or non-existent. B. Technical reviews typically include a moderator and a more structured approach, which is not mentioned here. C. In an inspection, formal documentation and a methodical approach to finding defects are expected, which is not the case here. D. Guided reviews include a moderator and a focus on quality assessment, which does not apply to the given description. Q","source":"User Provided Batch 4"},{"id":"q_batch4_8s5zi6k9s","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"You are testing a grading system that accepts scores on a scale of 0-100. The system ranks the scores as follows: 0-59: Fail 60-69: Pass 70-89: Good 90-100: Excellent Using equivalence partitioning,\\n\\nwhat is the MINIMUM number of test cases needed to achieve 100% coverage of valid partitions?","options":["3","4","5","6"],"correctAnswer":1,"explanation":"A. It is not correct. 3 test cases would not cover the 4 valid partitions identified. B. It is correct. 4 test cases are needed to cover the 4 valid partitions identified: one for Fail (0-59), one for Pass (60-69), one for Good (70-89) and one for Excellent (90-100). According to the syllabus, to achieve 100% coverage with equivalence partitioning, test cases must exercise all identified partitions covering each partition at least once. C. It is not correct. 5 test cases would be more than necessary to cover the minimum valid partitions. D. It is not correct. 6 test cases exceed the minimum number required. Q","source":"User Provided Batch 4"},{"id":"q_batch4_9dq3pcf6l","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"For an \'Age\' field that accepts values \u200b\u200bfrom 16 to 65 years, your test suite includes the following values: 15, 16, 17, 64, 65, 66.\\n\\nWhat percentage of 3-value Limit Value Analysis (LVA) coverage do you achieve?","options":["50%","67%","83%","100%"],"correctAnswer":3,"explanation":"A. It is not correct. 50% would be 3 of 6 items covered. B. It is not correct. 67% would be 4 of 6 items covered. C. It is not correct. 83% would be 5 of 6 items covered. D. It is correct. In 3-value BVA, for each cutoff value (16 and 65) there are three coverage elements: the cutoff value and its two neighbors. For limit 16: 15, 16, 17. For limit 65: 64, 65, 66. The test suite covers the 6 required elements (15, 16, 17, 64, 65, 66), therefore 6/6 = 100%. Q","source":"User Provided Batch 4"},{"id":"q_batch4_lwvrb8dbo","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"In a decision table for a loan approval system, you have the following conditions: Age \u2265 18 years Income \u2265 $30,000 Good credit history Employed for \u2265 2 years If you wanted to minimize the table due to the large number of combinations,\\n\\nwhat would be the best strategy?","options":["Remove all less important conditions","Use a risk-based approach to narrow down the rules to test","Combine all conditions into a single rule","Create multiple separate small tables"],"correctAnswer":1,"explanation":"A. It is not correct. Removing conditions can leave significant gaps in coverage. B. It is correct. According to the syllabus, \'if there are many conditions, exercising all the decision rules can take a long time, since the number of rules grows exponentially with the number of conditions. In such a case, to reduce the number of rules that must be exercised, a minimized decision table or a risk-based approach can be used.\' C. It is not correct. Combining all conditions does not solve the complexity problem. D. It is not correct. Multiple separate tables do not address the problem of exponential joins. Q","source":"User Provided Batch 4"},{"id":"q_batch4_paz05v6hi","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following statements REFERS to error prediction in a testing process?  ","options":["Bug prediction is based solely on quantitative metrics of past defects without considering the development context.","Bug prediction involves identifying areas of the software that are most likely to contain defects, based on bug history and code complexity.","Bug prediction requires testers to perform unit tests on all functions before they can predict bugs.","Bug prediction is a process that only developers can perform, since they know their code best."],"correctAnswer":1,"explanation":"A. It is not correct. Although quantitative metrics are useful, error prediction also considers context and prior experience to be effective. B. It is correct. Bug prediction involves using bug history along with factors such as code complexity to identify problem areas. C. It is not correct. Bug prediction does not depend on performing unit testing, but on analyzing past defect patterns. D. It is not correct. Bug prediction is a task that can also be performed by testers, who can provide a different perspective on risk areas. Q","source":"User Provided Batch 4"},{"id":"q_batch4_a4nevsfk4","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"A development team is creating an innovative mobile application, and has decided to use exploratory testing due to a lack of documentation.\\n\\nWhich of the following statements about exploratory testing is CORRECT?","options":["Exploratory testing is always less effective than requirements-based testing.","Exploratory testing allows testers to quickly adapt to changes in the software.","Exploratory testing requires a detailed test plan before being performed.","Exploratory testing is not suitable for complex applications."],"correctAnswer":1,"explanation":"A. It is not correct. Exploratory testing can be very effective, especially in environments where requirements are ambiguous or change frequently. B. It is correct. Exploratory testing allows testers to adapt and respond to software changes more flexibly. C. It is not correct. Although there may be a general approach, exploratory testing is characterized by not depending on a rigorous and detailed test plan. D. It is not correct. Exploratory testing can be very useful in complex applications by allowing for more dynamic and creative exploration. Q","source":"User Provided Batch 4"},{"id":"q_batch4_q2p8s0mdy","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following statements BEST describes\\n\\nhow acceptance criteria can be structured in a user story?","options":["Defined solely by the development team, without the need for review by stakeholders.","Written in a clear and concise format that facilitates understanding by all interested parties involved.","Creating an extensive list of technical requirements that must be met for the delivery of the user story.","Established based on the personal expectations of the team members, without considering the project objectives."],"correctAnswer":1,"explanation":"A. It is not correct. Acceptance criteria should be reviewed and agreed upon by all stakeholders, not just the development team. B. It is correct. A clear and concise format helps all stakeholders understand what is needed to consider the user story complete. C. It is not correct. Although technical requirements may be important, acceptance criteria should focus on user satisfaction conditions, not an exhaustive technical list. D. It is not correct. Acceptance criteria should align with project objectives and user needs, not be based on individual expectations. Q","source":"User Provided Batch 4"},{"id":"q_batch4_m7s7cmw0j","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"During an ATDD specification workshop, the team identifies ambiguities in a user story about payment processing.\\n\\nWhat is the MOST appropriate action according to the ATDD approach?","options":["The tester must create test cases that cover all possible interpretations","Resolve ambiguities during the workshop before creating test cases","Postpone creating test cases until development is complete","Create test cases only for the most likely scenarios"],"correctAnswer":1,"explanation":"A. It is not correct. Creating cases for all interpretations without resolving ambiguities can lead to conflicting or incorrect cases. B. It is correct. According to the syllabus, during the specification workshop \'incompleteness, ambiguities or defects in the user story are resolved during this process\' before proceeding to create the test cases. This is critical at ATDD to ensure everyone has the same understanding. Q","source":"User Provided Batch 4"},{"id":"q_batch4_s9bm5wa3g","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following is an entry criterion for test execution?  ","options":["The results of previous tests have been documented.","The acceptance criteria for the requirements have been defined.","The test team has completed test planning.","The software has passed all unit tests."],"correctAnswer":1,"explanation":"A. It is not correct. Documenting previous test results is good practice, but it is not a specific entry criterion. B. It is correct. Defining requirements acceptance criteria is essential to ensure entry criteria are clear before testing. C. It is not correct. Completing test planning may be a preliminary step, but it is not an entry criterion in itself. D. It is not correct. Passing all unit tests is an exit criterion, as it indicates that a testing phase has completed successfully. Q","source":"User Provided Batch 4"},{"id":"q_batch4_jq145tq22","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"In your test plan, you have prioritized test cases based on requirements. However, you realize that some high-priority cases cannot be executed in the ideal order due to dependencies and resource availability.\\n\\nWhat is the MOST appropriate action according to the syllabus?","options":["Maintain order based on priority of requirements ignoring dependencies","Adjust the order considering dependencies and resource availability","Switch to a different prioritization strategy","Run only high-priority standalone cases"],"correctAnswer":1,"explanation":"A. It is not correct. Ignoring dependencies can cause tests to fail for technical reasons rather than actual defects. B. It is correct. The syllabus states that \'if a test case with a higher priority depends on a test case with a lower priority, the lower priority test case should be executed first\' and that \'the test execution order should also take into account resource availability.\' C. It is not correct. There is no need to change the prioritization strategy, just adjust the order of execution. D. It is not correct. This would excessively limit test coverage. Q","source":"User Provided Batch 4"},{"id":"q_batch4_f4ffyxzso","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"How are the following tests classified according to the agile testing quadrants (A-D)? Select the correct option.\\n\\n1. Component testing\\n2. Functional testing\\n3. Exploratory testing\\n4. Non-functional testing\\n\\nA (Q1). Technology-oriented, supports the team  \\nB (Q2). Business-oriented, supports the team  \\nC (Q3). Business-oriented, product critical  \\nD (Q4). Technology-oriented, product critical","options":["1A, 2B, 3C, 4D","1B, 2A, 3D, 4C","1C, 2D, 3A, 4B","1D, 2C, 3B, 4A"],"correctAnswer":0,"explanation":"A. Correct \u2013 according to the syllabus (section 5.1.7, p. 53): 1 (component testing) \u2192 Q1 (technology, team support) 2 (functional testing) \u2192 Q2 (business, team support) 3 (exploratory testing) \u2192 Q3 (business, product critique) 4 (non-functional testing) \u2192 Q4 (technology, product critique) Tests in these quadrants relate directly to the levels and types of testing indicated in the Marick/Crispin model. B. Incorrect \u2013 component tests (1) are not in Q2; They are in Q1. Functional tests (2) are not in Q1; They are in Q2. C. Incorrect \u2013 exploratory tests (3) are not in Q1; They are in Q3. Non-functional tests (4) are not in Q2; They are in Q4. D. Incorrect \u2013 component tests (1) are not in Q4; They are in Q1. Exploratory tests (3) are not in Q2; They are in Q3. Q","source":"User Provided Batch 4"},{"id":"q_batch4_z9hth9gwh","chapter":3,"topic":"Desarrollo y Testing","difficulty":"medium","question":"In a software development project, the following risk was identified: Risk: User documentation is not up to date. Risk probability: high; risk impact: medium Risk response: a thorough review of the documentation is organized with the development team users are informed about possible inconsistencies in the documentation\\n\\nWhat is the most appropriate measure to respond to this analyzed risk?","options":["Risk mitigation","Risk acceptance","Risk transfer","Risk elimination"],"correctAnswer":0,"explanation":"A. That is correct. Reviewing documentation helps mitigate the risk of inconsistencies. B. It is not correct. Accepting the risk does not address the problem of outdated documentation. C. It is not correct. Risk is not being transferred, but rather addressed directly. D. It is not correct. This risk cannot be completely eliminated, but steps can be taken to mitigate it. Q","source":"User Provided Batch 4"},{"id":"q_batch4_kzxw2m4i9","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"When tracking defects found during testing,\\n\\nwhat is the benefit of configuration management in this process?","options":["Helps document testing requirements.","It allows you to identify the version of the software in which the defect was found.","Facilitates the creation of new test cases.","Ensures all defects are resolved before delivery."],"correctAnswer":1,"explanation":"A. It is not correct. Configuration management does not focus on requirements, but on the management of test items and their version. B. It is correct. Configuration management allows defects to be associated with specific versions of the software, making them easier to track and resolve. C. It is not correct. Creating new test cases is part of test design, not a direct benefit of configuration management. D. It is not correct. Although P configuration management","source":"User Provided Batch 4"},{"id":"q_batch4_attdk2hjt","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"A test analyst prepares the following defect report: ID: BUG-00721 \u200b\u200b| Title: \'Date of Birth\' field accepts future dates | Severity: Medium | Priority: High | Reported by: A. L\xf3pez | Configuration: App v3.2.1, Chrome 120 | Steps to reproduce: (1) Open registration form, (2) Enter date of birth \'08/15/2030\', (3) Click \'Save\'.\\n\\nWhat is the MOST important information missing from this report?","options":["The name of the developer assigned to resolve the defect.","The actual result obtained and the expected result, to facilitate reproduction and correction.","An estimate of the time required to correct the defect.","The number of users affected by the defect."],"correctAnswer":1,"explanation":"A. Incorrect. Assigning the defect to a developer is a post-management activity, not an essential component of the initial report. B. Correct. According to CTFL Syllabus v4.0 \xa75.5.1, a complete defect report must include the actual results obtained and the expected results. Without this information, the developer cannot confirm the incorrect behavior or validate the fix. C. Incorrect. Estimating fix time is the responsibility of the development team, not the defect report. D. Incorrect. The impact on users may be indicated in the priority/severity, but is not an essential field of the defect report according to the syllabus. Q","source":"User Provided Batch 4"},{"id":"q_batch4_83alrpwtk","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following testing tools is generally used to automate test execution?  ","options":["Test management tools","Performance testing tools","Test automation tools","Defect management tools"],"correctAnswer":2,"explanation":"A. It is not correct. Test management tools are used to plan, organize, and track the testing process, but not to execute tests in an automated manner. B. It is not correct. Performance testing tools are designed to evaluate system performance under load, not to automate test execution in general. C. It is correct. Test automation tools are specifically designed to run tests automatically, allowing for faster and more efficient testing. D. It is not correct. Defect management tools are used to track and manage bugs found during the testing process, not to automate test execution. Q","source":"User Provided Batch 4"},{"id":"q_batch4_7576lzkad","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following statements describes a benefit of test automation?  ","options":["Increase test coverage in less time","Completely eliminates the need for manual testing","Reduces the complexity of software development","Increases the possibility of human errors in execution"],"correctAnswer":0,"explanation":"A. That is correct. Automation allows you to run tests faster and more frequently, which can increase test coverage. B. It is not correct. Although automation can reduce the need for manual testing, it cannot eliminate it completely in all cases. C. It is not correct. Automation does not necessarily reduce software complexity, it can, in fact, introduce its own complexity. D. It is not correct. Automation, if done correctly, can reduce the chance of human error during test execution.","source":"User Provided Batch 4"},{"id":263,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"You are testing a user story with three acceptance criteria: AC1, AC2 and AC3. AC1 is covered by test case TC1, AC2 by TC2, and AC3 by TC3. The test execution history had three rounds of testing on three consecutive versions of the software as follows:\\n\\n| | Execution 1 | Execution 2 | Execution 3 |  \\n|---|---|---|---|  \\n| TC1 (1) | Failed (4) | Past (7) | Past |  \\n| TC2 (2) | Past (5) | Failed (8) | Past |  \\n| TC3 (3) | Failed (6) | Failed (9) | Past |\\n\\nTesting is repeated once you are informed that all defects found in the round of testing are fixed and a new version of the software is available.\\n\\nWhich of the above tests are run as regression tests?","options":["A) Only 4, 7, 8, 9","B) Only 5, 7","C) Only 4, 6, 8, 9","D) Only 5, 6"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#14, LO: FL-2.2.3). Justification: Only 5, 7","source":"Official Sample Exam A Q#14"},{"id":270,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"You are testing a system that calculates the final course grade for a given student. The final grade is assigned based on the final result, according to the following rules:  \\n- 0 \u2013 50 points: fail  \\n- 51 \u2013 60 points: sufficient  \\n- 61 \u2013 70 points: satisfactory  \\n- 71 \u2013 80 points: good  \\n- 81 \u2013 90 points: very good  \\n- 91 \u2013 100 points: excellent\\n\\nYou have prepared the following set of test cases:\\n\\n| TC | Final result | Final note |  \\n|---|---|---|  \\n| TC1 | 91 | excellent |  \\n| TC2 | 50 | suspense |  \\n| TC3 | 81 | very good |  \\n| TC4 | 60 | enough |  \\n| TC5 | 70 | satisfactory |  \\n| TC6 | 80 | good |\\n\\nWhat is the 2-value boundary value analysis (BVA) coverage for the final result achieved with the existing test cases?","options":["A) 50%","B) 60%","C) 33.3%","D) 100%"],"correctAnswer":0,"explanation":"Option A) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample A, Q#21, LO: FL-4.2.2). Justification: 50%","source":"Official Sample Exam A Q#21"},{"id":309,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"The following decision table contains the rules for determining the risk of arteriosclerosis.\\n\\n| | Rule 1 | Rule 2 | Rule 3 | Rule 4 | Rule 5 |  \\n|---|---|---|---|---|---|  \\n| Cholesterol (mg/dl) | \u2264124 | \u2264124 | 125\u2013200 | 125\u2013200 | \u2265201 |  \\n| Blood pressure (mm Hg) | \u2264140 | >140 | \u2264140 | >140 | \u2013 |  \\n| Risk level | very low | low | medium | high | very high |\\n\\nYou have designed the following test cases:  \\n- TC1: Cholesterol=125, BP=141  \\n- TC2: Cholesterol=200, BP=201  \\n- TC3: Cholesterol=124, BP=201  \\n- TC4: Cholesterol=109, BP=200  \\n- TC5: Cholesterol=201, BP=140\\n\\nWhat decision table coverage do these test cases achieve?","options":["A) 40%","B) 60%","C) 80%","D) 100%"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample B, Q#22, LO: FL-4.2.3). Justification: The table has 5 rules. The test cases cover rules 2 (TC1), 4 (TC2 \u2013 not exactly applicable), 1 (TC4) and 5 (TC5). Only 3 out of 5 rules are covered correctly, which gives 60%.","source":"Official Sample Exam B Q#22"},{"id":319,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"You are testing a web application that allows users to SEARCH products, VIEW details, ADD to cart, and place an ORDER. You have 7 test cases with these priorities (1=highest):  \\n- TC1: SEARCH product A (4)  \\n- TC2: SEARCH product B (4)  \\n- TC3: SEE details A (3)  \\n- TC4: SEE details B (2)  \\n- TC5: ADD product TO (3)  \\n- TC6: ADD product B (1)  \\n- TC7: place ORDER (5)\\n\\nDependencies: LOOKUP must be tested before VIEW, VIEW before ADD, and ADD before ORDER.\\n\\nWhich test case should be executed fourth?","options":["A) TC3","B) TC1","C) SS7","D) TC2"],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample B, Q#32, LO: FL-5.1.5). Justification: Respecting dependencies and priority: 1st TC6 (p1), 2nd TC4 (p2), 3rd TC5 or TC3 (p3), 4th TC1 (p4 after fulfilling dependencies).","source":"Official Sample Exam B Q#32"},{"id":325,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"You are testing a sort function that takes a set of numbers and returns them sorted in ascending order. The execution log is:\\n\\n- TC1: Input: `3`. Output: `3`. Result: passed  \\n- TC2: Input: `3 11 6 5`. Output: `3 5 6 11`. Result: passed  \\n- TC3: Input: `8 7 3 7 1`. Output: `1 3 7 8`. Result: failed  \\n- TC4: Input: `-2 -2 -2 -3 -3`. Output: `-3 -2`. Result: failed  \\n- TC5: Input: `0 -2 0 3 4 4`. Output: `-2 0 3 4`. Result: failed\\n\\nWhich of the following provides the BEST description of the bug to use in a defect report?","options":["A) The system fails to sort several sets of numbers. Reference: TC3, TC4, TC5.","B) The system seems to ignore duplicates when sorting. Reference: TC3, TC4, TC5.","C) The system cannot sort negative numbers. Reference: TC4, TC5.","D) TC3, TC4 and TC5 have defects (duplicate input data) and must be corrected."],"correctAnswer":1,"explanation":"Option B) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample B, Q#38, LO: FL-5.5.1). Rationale: The common pattern in all three bugs is that the function ignores duplicate elements when sorting, which is the most accurate description of the defect.","source":"Official Sample Exam B Q#38"},{"id":355,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"You are preparing a test execution schedule for 7 test cases (TC1-TC7).\\n\\nThe dependencies are:  \\n- TC2 depends on TC1  \\n- TC4 depends on TC2 and TC3  \\n- TC5 depends on TC3  \\n- TC6 depends on TC4 and TC5  \\n- TC7 depends on TC6\\n\\nThe priorities (1=highest) are: TC1-p3, TC2-p5, TC3-p1, TC4-p4, TC5-p2, TC6-p6, TC7-p7.\\n\\nWhat is the correct order of execution respecting dependencies and priorities?","options":["A) TC3, TC5, TC1, TC2, TC4, TC6, TC7","B) TC1, TC2, TC3, TC4, TC5, TC6, TC7","C) TC3, TC1, TC5, TC2, TC4, TC6, TC7","D) TC1, TC3, TC2, TC5, TC4, TC6, TC7"],"correctAnswer":2,"explanation":"Option C) is the correct answer according to the ISTQB CTFL Official Exam v4.0 (Sample D, Q#3, LO: FL-5.1.5). Rationale: TC3 has the highest priority (p1) and has no dependencies, so it goes first. Then TC1 (p3, no dependencies), then TC5 (depends on TC3), etc.","source":"Official Sample Exam C Q#32"},{"id":1014,"chapter":2,"topic":"Regresi\xf3n vs Confirmaci\xf3n","question":"The test cases were executed:  \\n- TC1 Failed  \\n- SS2 Passed  \\n- SS3 Failed\\n\\nAfter corrections, TC1, TC2 and TC3 are executed again.\\n\\nWhich of these runs are considered regression testing?","options":["TC1","TC2","TC3","TC1 and TC3"],"correctAnswer":1,"explanation":"The execution of TC2 is a regression, since it previously worked and it is verified that the changes have not broken it. TC1 and TC3 are confirmatory tests.","source":"Pr\xe1ctica Adicional"},{"id":"q_batch2_t5hos07b9","topic":"Gesti\xf3n de las Actividades de Prueba","question":"You have the following test cases for an online banking system:\\n\\n| Case | Functionality Risk | Risk Probability | Risk Impact | Dependency |  \\n|---|---|---|---|---|  \\n| TC1 | Login | 2 | 2 | None |  \\n| TC2 | Check balance | 3 | 3 | TC1 |  \\n| TC3 | Transfer money | 2 | 2 | TC1, TC2 |  \\n| TC4 | Change PIN | 4 | 4 | TC1 |\\n\\nApplying risk-based prioritization,\\n\\nwhere impact and probability is measured on a scale of 1 to 5 (1=Very High, 2=High, 3=Medium, 4=Low, 5=Very Low), what would be the MOST appropriate execution order?","options":["TC1, TC3, TC2, TC4","TC1, TC2, TC3, TC4","TC3, TC1, TC2, TC4","TC1, TC4, TC2, TC3"],"correctAnswer":1,"explanation":"A. Incorrect. Problem 1: TC3 depends on TC2 (needs queried balance), but TC3 runs before TC2. This breaks the dependency. Problem 2: TC2 has higher risk (9) than TC4 (16), but TC4 is executed before TC2. Poorly prioritize risk. B. Correct. TC1 first: It is independent and base for all other cases. TC2 before TC3/TC4: TC2 has a higher risk (9) than TC4 (16), and TC3 depends on TC2. C. Incorrect. Critical issue: TC3 depends on TC1 and TC2, but runs first, before both. It will fail due to lack of dependencies. D. Incorrect. Problem 1: TC2 has higher risk (9) than TC4 (16), but TC4 is executed before TC2. Poorly prioritize risk. Problem 2: TC3 depends on TC2, but TC2 runs after TC3. Break the dependency.","chapter":5,"source":"banco-extra"},{"id":"q_batch3_l6n0dvnvr","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"A development team has fixed several defects in a new version of the application. The following test cases were executed in the previous version:\\n\\n| Test | Result in previous version |  \\n|---|---|  \\n| TC1 | Failed |  \\n| TC2 | Passed |  \\n| TC3 | Failed |\\n\\nAfter corrections, the team runs test cases TC1, TC2, and TC3 again.\\n\\nWhich of these runs are considered regression testing?","options":["TC1 and TC3","TC2 and TC3","TC1 and TC2","TC2 only"],"correctAnswer":3,"explanation":"A. Incorrect. TC1 and TC3 failed in the previous version, so re-running them constitutes confirmation tests (re-testing): it is verified that the defect has been corrected. They are not regression tests. B. Incorrect. TC2 is a regression test, but TC3 failed in the previous version and is therefore a confirmation test. The combination TC2+TC3 is not correct. C. Incorrect. TC2 is a regression test, but TC1 failed in the previous version and is a confirmation test, not a regression test. Furthermore, this option was identical to option D, which constituted a structural defect in the question. D. Correct. TC2 passed in the previous version. By re-running it after the corrections, it is verified that the changes have not introduced new defects in functionality that already worked. This is exactly the definition of regression testing according to CTFL v4.0 sect. 2.2.3. TC1 and TC3, which failed before, are confirmation tests.","source":"User Provided Batch 3"},{"id":"q_batch5_oy2vhh5m6","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"What type of testing tool is best suited for issue management in a software project?  ","options":["Test management tool","Test automation tool","Incident tracking tool","Configuration Management Tool"],"correctAnswer":2,"explanation":"A. It is not correct. Although test management tools help organize and plan tests, they are not specifically designed to manage issues. B. It is not correct. Test automation tools are focused on running tests automatically, not managing issues. C. It is correct. Issue tracking tools are essential for recording, tracking, and managing defects found during testing. D. It is not correct. Configuration management tools are used to control and maintain software configurations, but are not for incident management.","source":"User Provided Batch 4"},{"id":"q_batch5_o536w1du4","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"What is the main benefit of using a test management tool?  ","options":["Automate testing without human intervention","Facilitate test planning and monitoring","Automatically generate test cases from code","Identify errors in code without running tests"],"correctAnswer":1,"explanation":"A. It is not correct. Although some tools can help with automation, the main purpose of a test management tool is planning and tracking. B. It is correct. A test management tool allows teams to plan, organize, and track test progress, facilitating coordination and communication. C. It is not correct. Tools that automatically generate test cases are typically analysis tools, not test management tools. D. It is not correct. Identifying bugs in code without running tests is not a function of test management tools; that\'s more of a function of static analysis tools.","source":"User Provided Batch 4"},{"id":"q_batch5_pdbyrk068","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following statements describes a benefit of test automation?  ","options":["Increased need for staff to be highly trained in programming","Allows execution of repetitive tests quickly and consistently","Test software maintenance cost increases significantly","Requires less time to plan manual tests"],"correctAnswer":1,"explanation":"A. It is not correct. Although automation may require some training, it is not an intrinsic benefit. B. It is correct. Automation allows you to run repetitive tests quickly and consistently, which is a huge benefit. C. It is not correct. Although there may be maintenance costs, the benefit is that efficiency can increase. D. It is not correct. Automation does not necessarily reduce manual test planning time.","source":"User Provided Batch 4"},{"id":"q_batch5_aqadcfs6i","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Which of the following is a benefit of test automation?  ","options":["Increase in test coverage","Increased time required to run tests","Reliance on specific testing tools","Reduction of necessary documentation"],"correctAnswer":0,"explanation":"A. That is correct. Test automation allows you to run more tests in less time, thus increasing coverage. B. It is not correct. Automation generally reduces the time needed to run a test suite. C. It is not correct. Although automation can create tool dependency, this is not a benefit. D. It is not correct. Automation does not necessarily reduce documentation, it often requires additional documentation for test scripts.","source":"User Provided Batch 4"},{"id":"q_batch6_1","chapter":6,"topic":"Herramientas","difficulty":"medium","question":"Which of the following is a key benefit of test automation in software development?","options":["It increases the time required to execute tests.","It allows the efficient repetition of tests.","It completely eliminates the need for manual testing.","It increases the risk of defects in the code."],"correctAnswer":1,"explanation":"A. Incorrect. Test automation aims to reduce execution time, not increase it. B. Correct. Automation allows tests to be executed quickly and repetitively, which is a great benefit. C. Incorrect. Although automation reduces the need for manual testing, it does not eliminate the need for it entirely. D. Incorrect. The goal is to reduce defects, although there can be risks if not managed properly.","source":"User Provided Batch 5"},{"id":"q_batch6_6","chapter":6,"topic":"Herramientas","difficulty":"medium","question":"Which of the following tools is primarily used for test automation?","options":["Test management tools","Test capture tools","Automated testing tools","Requirements analysis tools"],"correctAnswer":2,"explanation":"A. Incorrect. Test management tools are designed to plan, track, and organize testing activities, but they are not used to automate tests. B. Incorrect. Test capture tools are used to record user interaction with the application, but do not automate the testing process itself. C. Correct. Automated testing tools allow the execution of tests without human intervention, facilitating faster and more repeatable execution. D. Incorrect. Requirements analysis tools focus on the management and analysis of software requirements and do not play a role in test automation.","source":"User Provided Batch 5"},{"chapter":1,"topic":"Fundamentos","difficulty":"easy","question":"Which of the following statements represents an appropriate test objective?","options":["To ensure that the system is completely free of defects.","To identify defects and ensure that the requirements are adequately met.","To prove that the system will work under all possible conditions.","To verify that users do not report complaints about system performance."],"correctAnswer":1,"explanation":"A. Incorrect. It cannot be guaranteed that a system is completely free of defects. See testing principle 1. B. Correct. One of the main objectives of testing is to identify defects and confirm that the requirements have been correctly implemented. C. Incorrect. It is impossible to test all possible conditions, which relates to testing principle 2. D. Incorrect. While user satisfaction is important, testing should focus on identifying defects and not on the absence of complaints.","source":"User Provided Batch 7","id":"q_batch7_1"},{"chapter":1,"topic":"Fundamentos","difficulty":"medium","question":"A software company develops applications for the financial sector. The management team asks the test manager\\n\\nwhy testing is essential in their context, beyond finding defects.\\n\\nWhich of the following reasons BEST describes why testing is necessary in this context?","options":["To prove that the software has no defects prior to delivery.","To provide confidence about the level of software quality and comply with the regulatory requirements of the sector.","To replace the requirements review process and reduce documentation.","To ensure that all developers are familiar with the complete system code."],"correctAnswer":1,"explanation":"A. Incorrect. Principle 1 of CTFL v4.0 states that testing shows the presence of defects, not their absence. It is impossible to guarantee that there are no defects. B. Correct. The CTFL v4.0 Syllabus \xa71.2.1 indicates that testing is necessary to provide an assessment of software quality and to comply with contractual or regulatory requirements, which is especially relevant in the financial sector. C. Incorrect. Testing complements reviews; it does not replace them or reduce the need for documentation. D. Incorrect. The purpose of testing is not the training of the development team.","source":"User Provided Batch 7","id":"q_batch7_2"},{"chapter":1,"topic":"Principios","difficulty":"medium","question":"You are the leader of a testing team and you notice that, despite performing exhaustive testing in the development phase, the software still presents defects in production.\\n\\nWhich testing principle could explain this situation?","options":["Defects cluster together","Exhaustive testing is impossible","Tests wear out","Absence-of-defects fallacy"],"correctAnswer":1,"explanation":"A. Incorrect. This principle refers to the fact that a small number of modules usually contain most of the defects, but it does not explain the appearance of defects in production after exhaustive testing. B. Correct. This principle indicates that testing all combinations of inputs and preconditions is impossible, which can lead to defects that were not identified during testing. C. Incorrect. This principle indicates that repeated tests lose effectiveness (pesticide paradox), but not directly the reason why defects appear in production. D. Incorrect. This principle refers to the mistaken belief that finding and fixing a large number of defects will ensure the success of a system, but does not relate to the fact that defects continue to appear.","source":"User Provided Batch 7","id":"q_batch7_3"},{"chapter":1,"topic":"Proceso de Prueba","difficulty":"medium","question":"In a software development project, the team is preparing the testing phase after completing the development phase.\\n\\nWhich of the following activities is part of test planning?","options":["Defining the acceptance criteria to evaluate if the developed functionality meets the requirements.","Executing regression tests to ensure that the new functionalities do not break the existing ones.","Identifying the risks associated with the new functionality and planning how to mitigate them.","Logging the defects found during test execution and communicating them to the development team."],"correctAnswer":2,"explanation":"A. Incorrect. Defining acceptance criteria is part of the requirements analysis phase, not test planning. B. Incorrect. Test execution is an activity that occurs after planning. C. Correct. Identifying risks and planning their mitigation is an essential part of test planning. D. Incorrect. Logging defects is part of test execution, not planning.","source":"User Provided Batch 7","id":"q_batch7_4"},{"chapter":1,"topic":"Contexto de las Pruebas","difficulty":"medium","question":"What factors can affect the scope and depth of testing in a project?\\n\\n1. The complexity of the system to be tested\\n2. The experience of the testing team\\n3. The budget allocated to the project\\n4. The type of data used in the tests","options":["1, 2, 3 affect the scope and depth","2, 3, 4 affect the scope and depth","1, 3, 4 affect the scope and depth","1, 2, 4 affect the scope and depth"],"correctAnswer":0,"explanation":"A. 1. Is true. System complexity is a technical factor that influences the approach and depth of testing. 2. Is true. Team experience is a human factor that determines the effectiveness and detail of testing activities. 3. Is true. The budget is a project constraint that defines the possible scope of testing. According to section 1.4.2 of the syllabus, these are key contextual factors, while the type of data (4) is considered a product of test design (testware) and not a primary context factor. Therefore, the correct answer is A. B. See explanation/justification for answer A. C. See explanation/justification for answer A. D. See explanation/justification for answer A.","source":"User Provided Batch 7","id":"q_batch7_5"},{"chapter":1,"topic":"Roles en las Pruebas","difficulty":"medium","question":"Which of the following activities PRIMARILY corresponds to the role of the tester and NOT to the test manager, according to the CTFL v4.0 Syllabus?","options":["Planning the test effort and negotiating deadlines with project management.","Analyzing, designing, and implementing the test cases for the assigned functionalities.","Managing the budget of the test project.","Selecting and acquiring testing tools for the team."],"correctAnswer":1,"explanation":"A. Incorrect. Planning the test effort and negotiating with management is the responsibility of the test manager. B. Correct. The CTFL v4.0 Syllabus \xa71.4.5 states that the tester is responsible for analyzing requirements, designing test cases, implementing and executing tests. These are technical activities at the test level. C. Incorrect. Managing the budget is the responsibility of the test manager. D. Incorrect. Tool selection is a management decision that corresponds to the test manager.","source":"User Provided Batch 7","id":"q_batch7_6"},{"chapter":1,"topic":"Habilidades Esenciales","difficulty":"medium","question":"Which skills are essential for a tester working in an agile team?\\n\\n1. Active listening\\n2. Deep technical knowledge\\n3. Effective communication\\n4. Ability to work under pressure","options":["1 and 3 are essential; 2 and 4 are not","1, 2, and 4 are essential; 3 is not","3 and 4 are essential; 1 and 2 are not","1, 3, and 2 are essential; 4 is not"],"correctAnswer":3,"explanation":"A. Active listening (1) and effective communication (3) are important skills, but they are not the only necessary ones. It is incorrect to state that 2 and 4 are not relevant at all, but specifically 2 is very valuable. B. Technical knowledge (2) is relevant, but not as crucial as the combination of effective communication and active listening in an agile environment without 3. C. While 3 and 4 are important, the lack of active listening and technical knowledge can limit the tester\'s effectiveness. D. Active listening (1) and effective communication (3) are fundamental skills in an agile team, while deep technical knowledge (2) is also valuable, but working under pressure (4) is considered less of an essential generic skill in this specific syllabus context compared to the others. Thus, this is the correct answer.","source":"User Provided Batch 7","id":"q_batch7_7"},{"chapter":2,"topic":"Pruebas en SDLC","difficulty":"medium","question":"Which of the following statements best describes the importance of testing in each phase of the software development life cycle?","options":["Testing is only necessary at the end of the life cycle to ensure that the software works.","Performing tests in each phase helps identify defects as early as possible, reducing costs and time.","Testing should focus solely on the development phase and not on the analysis or design phases.","Testing is irrelevant in the early phases since significant changes are made to the software."],"correctAnswer":1,"explanation":"A. Incorrect. Testing should be performed in all phases to find and fix defects early. B. Correct. Performing tests in each phase allows detecting problems earlier, which can reduce costs and time. C. Incorrect. Testing is necessary in all phases, not just in development, to ensure quality. D. Incorrect. Testing in early phases is crucial to prevent problems in later stages.","source":"User Provided Batch 7","id":"q_batch7_9"},{"chapter":2,"topic":"Shift Left","difficulty":"medium","question":"Which of the following activities best represents the \\"shift-left\\" philosophy in software development?","options":["Performing regression tests after completing software development.","Initiating the design review before the code is written.","Creating user documentation after the product is ready for release.","Executing acceptance tests in a production environment."],"correctAnswer":1,"explanation":"A. Incorrect. Regression testing performed at the end is not an example of the shift-left approach, which promotes testing earlier in the life cycle. B. Correct. Initiating design review before coding is a clear example of the shift-left approach, as it aims to detect defects early. C. Incorrect. User documentation should be created before launch to facilitate software adoption, not after. D. Incorrect. Executing acceptance tests in production is not part of the shift-left approach, which focuses on early problem detection.","source":"User Provided Batch 7","id":"q_batch7_11"},{"chapter":2,"topic":"Niveles de Prueba","difficulty":"hard","question":"A development team is working on a flight reservation system. Match each testing activity (1-4) with the corresponding test level (A-D):\\n\\n1. The team verifies that the fare calculation module produces correct results in isolation.\\n2. The team verifies that the reservation module communicates correctly with the payment module.\\n3. The team executes complete end-to-end flight purchase scenarios.\\n4. The airline\'s end users validate that the system meets their operational needs.\\n\\nA. Acceptance testing\\nB. Integration testing\\nC. System testing\\nD. Component testing","options":["1D, 2B, 3C, 4A","1C, 2A, 3D, 4B","1A, 2C, 3B, 4D","1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"A. Correct. (1) Verifying an isolated module = Component testing (D). (2) Verifying communication between modules = Integration testing (B). (3) Complete end-to-end scenarios = System testing (C). (4) End users validating their needs = Acceptance testing (A). B. Incorrect. This combination confuses test levels; system tests do not verify isolated modules. C. Incorrect. Acceptance tests are not for verifying individual modules. D. Incorrect. Integration tests are not limited to isolated components.","source":"User Provided Batch 7","id":"q_batch7_13"},{"chapter":2,"topic":"Tipos de Prueba","difficulty":"medium","question":"A development team has fixed several defects in the application and released a new version. Before the fix, certain test cases were executed, some of\\n\\nwhich failed. Now the team needs to verify that the defects have been fixed and also that the changes have not affected other parts of the system. Which of the following descriptions best fits the tests that will be carried out?","options":["Confirmation testing focuses solely on the test cases that failed previously.","Regression testing ensures that the functionalities that were not modified continue to work correctly.","Confirmation testing includes the test cases that failed in previous versions and those executed for the first time.","Regression testing only applies to new defects discovered in the new version."],"correctAnswer":1,"explanation":"A. Incorrect. Confirmation testing focuses on verifying that the fixed defects now work, but the scenario also requires checking unaffected parts (regression). B. Correct. Regression tests are necessary to verify that modifications have not affected existing functionalities, which meets the team\'s need to check unaffected parts. C. Incorrect. Confirmation testing only relates to the corrected defects, not to cases executed for the first time. D. Incorrect. Regression testing applies to all existing functionalities, not just new defects.","source":"User Provided Batch 7","id":"q_batch7_14"},{"chapter":3,"topic":"Pruebas Est\xe1ticas","difficulty":"medium","question":"Which of the following statements best describes a benefit of static testing in software development?","options":["Static testing helps ensure that the code meets specifications before it is executed.","Static testing is more effective than dynamic testing in identifying runtime execution defects.","Static testing allows testing in environments where the software cannot be executed.","Static testing eliminates the need for dynamic testing on the software."],"correctAnswer":0,"explanation":"A. Correct. Static testing allows reviewing the code and documents prior to execution, helping to ensure compliance with specifications. B. Incorrect. Static testing does not identify runtime errors, since the software is not executed. C. Incorrect. Although static testing can be done without an execution environment, its main purpose is not to facilitate testing in non-executable environments. D. Incorrect. Static testing does not completely replace the need for dynamic testing, as both serve complementary purposes.","source":"User Provided Batch 7","id":"q_batch7_15"},{"chapter":3,"topic":"Retroalimentaci\xf3n","difficulty":"easy","question":"What is a key benefit of obtaining early and frequent feedback from stakeholders?","options":["It helps identify performance issues in the tests.","It allows adapting development to the changing needs of the stakeholders.","It increases the total time of the project.","It reinforces the confidentiality of customer data."],"correctAnswer":1,"explanation":"A. Incorrect. While feedback can help identify problems, it does not specifically focus on test performance. B. Correct. Early and frequent feedback allows adjusting development to meet changing stakeholder needs. C. Incorrect. Effective feedback usually helps reduce total project time by addressing issues early. D. Incorrect. Feedback is not related to data confidentiality, but to improving the development process.","source":"User Provided Batch 7","id":"q_batch7_16"},{"chapter":3,"topic":"Revisiones","difficulty":"medium","question":"The author of a design document leads a review session. A scribe logs the defects found. Participants can freely ask questions and the author explains their design. No formal entry or exit criteria are used.\\n\\nWhat type of review does this scenario describe?","options":["Inspection","Technical review","Walkthrough","Informal review"],"correctAnswer":2,"explanation":"A. Incorrect. In an inspection, the leader is a trained moderator (not the author), and formal entry/exit criteria are used. B. Incorrect. In a technical review, the results are formally documented, and it is not necessarily led by the author. C. Correct. The CTFL v4.0 Syllabus \xa73.2.4 defines a walkthrough as a review led by the author where a scribe logs defects, participants can ask questions, and the author explains the work. It has no formal entry/exit criteria. D. Incorrect. An informal review does not have a scribe or a defined structure; it is completely ad hoc.","source":"User Provided Batch 7","id":"q_batch7_17"},{"chapter":3,"topic":"Revisiones","difficulty":"medium","question":"A team introduces formal reviews into their process. However, reviewers are not given enough time to review the documents and management does not consider the review results in project decisions.\\n\\nWhich success factor for reviews is MISSING?","options":["The use of standardized checklists.","Management support that allocates time and values the review results.","The presence of a security expert in each review session.","Limiting reviews to requirements documents only."],"correctAnswer":1,"explanation":"A. Incorrect. Checklists are useful, but they are not the main missing factor here. B. Correct. The CTFL v4.0 Syllabus \xa73.2.5 identifies management support as a key success factor: management must allocate enough time for preparation and value the results, otherwise reviews become a worthless formality. C. Incorrect. The involvement of specialists is useful in specific contexts, but it is not the universal success factor. D. Incorrect. Reviews can be applied to any work product (requirements, design, code, test cases), not just requirements.","source":"User Provided Batch 7","id":"q_batch7_18"},{"chapter":4,"topic":"Partici\xf3n de Equivalencia","difficulty":"hard","question":"A climate control system validates the room temperature. Acceptable values are between 16\xb0C and 30\xb0C inclusive. Temperatures outside that range generate an alert.\\n\\nUsing equivalence partitioning,\\n\\nwhat is the MINIMUM number of test cases needed to cover ALL partitions (valid and invalid)?","options":["2","3","4","6"],"correctAnswer":1,"explanation":"A. Incorrect. With 2 test cases only 2 of the 3 partitions identified by EP are covered. B. Correct. EP divides the domain into 3 partitions: (1) temperature < 16\xb0C (invalid), (2) 16\xb0C\u201330\xb0C (valid), (3) temperature > 30\xb0C (invalid). The \'Each Choice\' coverage criterion requires at least 1 case per partition, that is, 3 cases in total. C. Incorrect. 4 test cases exceed the minimum needed to satisfy the EP coverage criterion. D. Incorrect. 6 cases correspond to the Boundary Value Analysis technique with 2 values (BVA-2), not to EP.","source":"User Provided Batch 7","id":"q_batch7_20"},{"chapter":4,"topic":"Partici\xf3n de Equivalencia","difficulty":"medium","question":"A user registration system validates the user\'s age. The requirement states: \'Age must be between 18 and 65 years inclusive to be valid\'. Applying the equivalence partitioning technique,\\n\\nwhat is the MINIMUM set of test cases that covers all equivalence partitions?","options":["Age = 18, Age = 40, Age = 66","Age = 18, Age = 65","Age = 17, Age = 40, Age = 66","Age = 0, Age = 17, Age = 40, Age = 66"],"correctAnswer":2,"explanation":"A. Incorrect. Although it has 3 test cases, it does not cover the lower invalid partition (age < 18) and presents redundancy by including two values from the valid partition (18 and 40). B. Incorrect. It only covers the valid partition with 2 redundant cases, leaving the invalid partitions (lower and upper) uncovered. C. Correct. 3 test cases are needed to cover the 3 identified equivalence partitions: one for the lower invalid partition (age < 18), one for the valid partition (18 \u2264 age \u2264 65), and one for the upper invalid partition (age > 65). According to the equivalence partitioning technique, to achieve 100% coverage, test cases must exercise all identified partitions, covering each partition at least once. D. Incorrect. 4 test cases exceed the minimum number required, as it includes redundancy in the lower invalid partition (age = 0 and age = 17).","source":"User Provided Batch 8","id":"q_batch8_21"},{"chapter":4,"topic":"Tabla de Decisiones","difficulty":"medium","question":"In a decision table for a loan approval system, you have the following conditions:\\n\\n- Age \u2265 18 years\\n- Income \u2265 $30,000\\n- Good credit history\\n- Employed for \u2265 2 years\\n\\nIf you wanted to minimize the table due to the large number of combinations,\\n\\nwhat would be the best strategy?","options":["Eliminate all less important conditions","Use a risk-based approach to reduce the rules to test","Combine all conditions into a single rule","Create multiple separate small tables"],"correctAnswer":1,"explanation":"A. Incorrect. Eliminating conditions can leave significant gaps in coverage. B. Correct. According to the syllabus, \'if there are many conditions, exercising all decision rules can be very time-consuming, as the number of rules grows exponentially with the number of conditions. In such a case, to reduce the number of rules that must be exercised, a minimized decision table or a risk-based approach can be used.\' C. Incorrect. Combining all conditions does not solve the complexity problem. D. Incorrect. Multiple separate tables do not address the problem of exponential combinations effectively without risk analysis.","source":"User Provided Batch 8","id":"q_batch8_22"},{"chapter":4,"topic":"Basadas en Experiencia","difficulty":"medium","question":"Which of the following statements BEST describes\\n\\nhow error guessing is used in software testing?","options":["Error guessing is based on identifying the areas of the software where defects are most likely to occur, using historical data and past error patterns.","Error guessing focuses solely on reviewing requirements to detect potential flaws before development begins.","Error guessing involves randomly guessing errors in the software without any basis in prior experience.","Error guessing requires the tester to constantly evaluate the performance of the software during its execution."],"correctAnswer":0,"explanation":"A. Correct. Error guessing focuses on identifying risk areas in the software that are most likely to contain defects, based on past experience and historical data. B. Incorrect. Although reviewing requirements is important, error guessing is based more on experience and defect patterns in already developed software. C. Incorrect. Random guessing is not an effective way to predict errors; predicting should be grounded in data and prior experiences. D. Incorrect. Evaluating software performance is a different activity; error guessing focuses on identifying and anticipating defects before testing the software.","source":"User Provided Batch 8","id":"q_batch8_26"},{"chapter":4,"topic":"Basadas en Experiencia","difficulty":"medium","question":"Your development team has implemented a new functionality in the software, but it has not been properly documented. You have little time to run tests before the release.\\n\\nWhat is the best test strategy you can use in this situation?","options":["Automated testing","Exploratory testing","Regression testing","Requirements-based testing"],"correctAnswer":1,"explanation":"A. Incorrect. Automated testing requires time to be designed and configured, which is not viable with little time available. B. Correct. Exploratory testing allows a quick evaluation of the new functionality without the need for detailed documentation. C. Incorrect. Regression testing is useful, but requires a clear understanding of previous functionalities that are not documented. D. Incorrect. Requirements-based testing is not effective here, since the lack of documentation limits the ability to design tests based on requirements.","source":"User Provided Batch 8","id":"q_batch8_27"},{"chapter":4,"topic":"ATDD/BDD","difficulty":"medium","question":"An agile team is starting the implementation of ATDD for their next sprint. The Scrum Master wants to know\\n\\nwho should participate in the ATDD specification workshop.\\n\\nWhich of the following statements BEST describes participation in an ATDD specification workshop?","options":["Only testers, as they are responsible for defining the acceptance criteria.","Only developers, because they are the ones who will implement the automated tests.","Business representatives, developers, and testers collaborate together.","Only business representatives, because the acceptance criteria are customer requirements."],"correctAnswer":2,"explanation":"A. Incorrect. Testers participate, but ATDD requires the collaboration of the entire team, not just testers. B. Incorrect. Developers participate, but without the business and testing perspective, the acceptance criteria would be incomplete. C. Correct. The CTFL v4.0 Syllabus \xa74.5.3 states that the ATDD specification workshop involves business representatives, developers, and testers to collaborate in defining concrete examples. D. Incorrect. Although business representatives bring the customer\'s vision, developers and testers are needed to define testable examples.","source":"User Provided Batch 8","id":"q_batch8_29"},{"chapter":5,"topic":"Planificaci\xf3n de Pruebas","difficulty":"medium","question":"How can testers contribute to better planning of the software release?","options":["Testers review the specifications and provide feedback on project feasibility.","Testers produce user documentation without being involved in product development.","Testers are responsible for establishing project delivery deadlines.","Testers focus on testing at the end of the development cycle to ensure quality."],"correctAnswer":0,"explanation":"A. Correct. Testers review the specifications and can identify feasibility issues, which aids in planning. B. Incorrect. Although testers may contribute to documentation, their main function is to assure quality during development. C. Incorrect. Establishing deadlines is generally the responsibility of the project manager or the management team. D. Incorrect. Waiting until the end to perform testing is not helpful and can compromise the quality of the product.","source":"User Provided Batch 8","id":"q_batch8_30"},{"chapter":5,"topic":"Estimaci\xf3n","difficulty":"medium","question":"Your team is in the third iteration of an agile project. The test efforts of the previous iterations were:\\n\\n- Iteration 1: 45 person-days\\n- Iteration 2: 52 person-days\\n\\nUsing extrapolation,\\n\\nwhat would be the most appropriate estimate for Iteration 3?","options":["45 person-days (the historical minimum)","48.5 person-days (average of the two iterations)","52 person-days (increasing trend)","59 person-days (extrapolation of the trend)"],"correctAnswer":1,"explanation":"A. Incorrect. Using only the minimum does not consider the trend or variability. B. Correct. According to the syllabus, in extrapolation \'the team can extrapolate the test effort for the next iteration as the averaged effort of the last three iterations.\' With only two iterations available, the average would be (45 + 52) \xf7 2 = 48.5 person-days. C. Incorrect. Using only the last value does not apply the concept of history-based extrapolation. D. Incorrect. Although it could be a trend extrapolation, the syllabus specifically mentions using the average.","source":"User Provided Batch 8","id":"q_batch8_32"},{"chapter":5,"topic":"Riesgos","difficulty":"hard","question":"You have the following test cases for an online banking system:\\n\\n| Case | Functionality Risk | Risk Likelihood | Risk Impact | Dependency |\\n|---|---|---|---|---|\\n| TC1 | Login | 2 | 2 | None |\\n| TC2 | Check balance | 3 | 3 | TC1 |\\n| TC3 | Transfer money | 2 | 2 | TC1, TC2 |\\n| TC4 | Change PIN | 4 | 4 | TC1 |\\n\\nApplying risk-based prioritization,\\n\\nwhere impact and likelihood are measured on a scale of 1 to 5 (1=Very High, 2=High, 3=Medium, 4=Low, 5=Very Low), what would be the MOST appropriate execution order?","options":["TC1, TC3, TC2, TC4","TC1, TC2, TC3, TC4","TC3, TC1, TC2, TC4","TC1, TC4, TC2, TC3"],"correctAnswer":1,"explanation":"A. Incorrect. Problem 1: TC3 depends on TC2 (needs checked balance), but TC3 runs before TC2. This breaks the dependency. Problem 2: TC2 has a higher risk rating (3x3=9) than TC4 (4x4=16) since lower number is higher risk. Oh wait! Scale: 1=Very High, 5=Very Low. So lower number means HIGHER risk. Risk level = Likelihood x Impact. TC1: 2x2=4. TC3: 2x2=4. TC2: 3x3=9. TC4: 4x4=16. Priority is TC1 and TC3 (highest risk), then TC2, then TC4. But TC3 depends on TC2, which depends on TC1. Thus, TC1 must go first, then TC2, then TC3, then TC4. Wait, B executes TC2 before TC3. This satisfies dependency, though delays higher risk TC3. B is the only logically viable sequence. B. Correct. TC1 first: Independent and baseline for all others. TC2 before TC3/TC4: Even though TC3 has higher risk, it strictly depends on TC2. C. Incorrect. Critical problem: TC3 depends on TC1 and TC2, but is executed first, before both. It will fail due to lack of dependencies. D. Incorrect. Problem 1: TC2 has higher risk (9) than TC4 (16), but TC4 is executed before TC2. Prioritizes risk incorrectly. Problem 2: TC3 depends on TC2, but TC2 is executed after TC3. Breaks dependency.","source":"User Provided Batch 8","id":"q_batch8_33"},{"chapter":2,"topic":"Cuadrantes \xc1giles","difficulty":"medium","question":"Identify the following test categories (1-4) and the agile testing quadrants (A-D):\\n\\n1. Usability testing\\n2. Component testing\\n3. Functional testing\\n4. Reliability testing\\n\\nA. Quadrant Q1: technology-facing, supports the development team\\nB. Quadrant Q2: business-facing, supports the development team\\nC. Quadrant Q3: business-facing, critiques the product\\nD. Quadrant Q4: technology-facing, critiques the product\\n\\nWhich combinations are correct for these test categories and quadrants?","options":["1C, 2A, 3B, 4D","1D, 2A, 3C, 4B","1C, 2B, 3D, 4A","1D, 2B, 3C, 4A"],"correctAnswer":0,"explanation":"A. Usability testing relates to Quadrant Q3 (1-C), component testing to Quadrant Q1 (2-A), functional testing to Quadrant Q2 (3-B), and reliability testing (as non-functional testing) to Quadrant Q4 (4-D). This aligns exactly with section 5.1.7 of the syllabus. Therefore, this option is correct. B. Functional tests would be assigned to Q3 (3-C), which is not correct according to the description of Q2. C. Reliability tests would be assigned to Q1 (4-A), which is not correct (they belong to Q4). D. Usability tests would be assigned to Q4 (1-D), which is not correct (they belong to Q3).","source":"User Provided Batch 8","id":"q_batch8_34"},{"chapter":5,"topic":"Gesti\xf3n de Riesgos","difficulty":"medium","question":"During a risk review, the following problem was identified:\\n\\nRisk: Incompatibility between software modules.\\nRisk Likelihood: high; Risk Impact: medium\\n\\nRisk response:\\n- perform early integration testing to identify incompatibilities\\n- document incompatibilities and communicate them to the development team\\n\\nWhat is the most appropriate action to take in response to this analyzed risk?","options":["Risk mitigation","Risk transfer","Risk acceptance","Contingency plan"],"correctAnswer":0,"explanation":"A. Correct. Early integration tests are a mitigation strategy that helps identify and resolve problems before they become bigger. B. Incorrect. Risk transfer involves passing the risk to another party, which is not mentioned here. C. Incorrect. Accepting the risk is not appropriate, as actions are being proposed to solve it. D. Incorrect. Although contingency plans can be developed, the main action here is mitigation through testing.","source":"User Provided Batch 8","id":"q_batch8_35"},{"chapter":5,"topic":"M\xe9tricas e Informes","difficulty":"medium","question":"Which of the following elements is most appropriate to provide an overview of testing progress to project stakeholders?","options":["Defect log","Monthly test report","Test status report","Test plan"],"correctAnswer":2,"explanation":"A. Incorrect. The defect log details the defects found but does not provide a summary of testing status. B. Incorrect. While a monthly test report can offer information on progress, it is not the most suitable for an immediate overview. C. Correct. A test status report summarizes progress, results, and relevant metrics regarding the testing status, being useful for stakeholders. D. Incorrect. The test plan establishes the strategy and approach, but does not communicate the current testing status.","source":"User Provided Batch 8","id":"q_batch8_36"},{"chapter":5,"topic":"Gesti\xf3n de Defectos","difficulty":"medium","question":"You have found a defect during testing of a billing module. The system calculates the tax incorrectly\\n\\nwhen a discount is applied. Which of the following defect reports is BEST structured?","options":["\\"The tax is calculated incorrectly with discounts\\"","\\"Error in tax calculation with discounts. Expected result: 21%, actual result: 18%. Steps: apply 10% discount to $100 invoice, calculate tax.\\"","\\"ID: DEF-2024-001, Title: Incorrect tax calculation with discounts, Environment: Test v2.1, Steps: 1)Create $100 invoice, 2)Apply 10% discount, 3)Calculate tax, Expected: $19.53, Actual: $16.20, Severity: High, Status: New\\"","\\"There is a problem with taxes when there are discounts applied in the system\\""],"correctAnswer":2,"explanation":"A. Incorrect. Too vague, lacks critical information to reproduce and resolve the defect. B. Incorrect. Although better than (A), it lacks important structural elements such as ID, environment, severity, status. C. Correct. This report includes all essential elements according to the syllabus: unique identifier, descriptive title, identification of the test environment, clear description for reproduction, expected vs actual results, severity, and status. It allows effective reproduction and resolution. D. Incorrect. Very general description without specific details to reproduce or understand the problem.","source":"User Provided Batch 8","id":"q_batch8_38"},{"chapter":3,"topic":"Retroalimentaci\xf3n","difficulty":"medium","question":"What is a benefit of early and frequent feedback from stakeholders in a project?","options":["Accelerates the implementation of new technological tools.","Facilitates the early identification of problems in development.","Reduces the need for training in the test team.","Increases the duration of the project lifecycle."],"correctAnswer":1,"explanation":"A. Incorrect. Feedback is not directly related to implementing technological tools.\\nB. Correct. Early and frequent feedback helps identify problems earlier in the development cycle.\\nC. Incorrect. Feedback does not eliminate the need for training.\\nD. Incorrect. Early and frequent feedback tends to optimize the project lifecycle, not increase it.","source":"User Provided Batch 9","id":"q_batch9_1"},{"chapter":3,"topic":"Retroalimentaci\xf3n","difficulty":"medium","question":"What advantage does frequent feedback from stakeholders provide in a project?","options":["Facilitates the identification of errors in early stages.","Minimizes communication between teams.","Reduces development time by avoiding reviews.","Increases the amount of documentation required."],"correctAnswer":0,"explanation":"A. Correct. Frequent feedback allows errors and misunderstandings to be detected in time, facilitating their correction before advancing.\\nB. Incorrect. Frequent feedback encourages communication between teams and stakeholders.\\nC. Incorrect. Although it may help avoid reviews, feedback does not necessarily reduce development time.\\nD. Incorrect. Early feedback tends to simplify documentation by clarifying requirements from the start.","source":"User Provided Batch 9","id":"q_batch9_2"},{"chapter":3,"topic":"Pruebas Est\xe1ticas","difficulty":"medium","question":"Which of the following statements best describes a benefit of static testing?","options":["Static testing allows defects to be found in early stages, reducing the cost of correcting them.","Static testing requires more time than dynamic testing to be carried out.","Static testing is useful mainly for validating software functionality.","Static testing cannot be automated."],"correctAnswer":0,"explanation":"A. Correct. This is a key benefit of static testing, as identifying defects early can be less costly than correcting them in later stages.\\nB. Incorrect. Generally, static testing requires less time than dynamic testing to detect defects.\\nC. Incorrect. Static testing does not validate functionality, but reviews code quality, documentation, etc.\\nD. Incorrect. Static testing can be automated using code analysis tools.","source":"User Provided Batch 9","id":"q_batch9_3"},{"chapter":3,"topic":"Revisiones","difficulty":"medium","question":"Which of the following elements is essential to ensure the effectiveness of a review?","options":["Active participation of all members in the review process.","Conducting the review without a structured approach to foster creativity.","Limiting the review time to less than 15 minutes to maintain participant energy.","Allowing only the team leader to share observations to avoid confusion."],"correctAnswer":0,"explanation":"A. Correct. Active participation of all members is crucial to identifying more defects and improving quality.\\nB. Incorrect. A structured approach is fundamental to guide the review and ensure all relevant aspects are covered.\\nC. Incorrect. Limiting review time can lead to overlooking important defects.\\nD. Incorrect. Allowing only the leader to share observations can restrict the diversity of opinions and findings.","source":"User Provided Batch 9","id":"q_batch9_5"},{"chapter":3,"topic":"Revisiones","difficulty":"medium","question":"Which of the following elements is essential to achieve an effective review?","options":["Having a moderator to control the discussion.","Allowing all participants to be reviewers without prior preparation.","It is not necessary to document the problems identified during the review.","Conducting the review informally and without structure."],"correctAnswer":0,"explanation":"A. Correct. A moderator helps maintain focus and productivity during the review.\\nB. Incorrect. Preparation by reviewers is crucial for a successful review.\\nC. Incorrect. Documenting problems is fundamental for tracking and improvement.\\nD. Incorrect. A lack of structure can lead to confusion and ineffective results.","source":"User Provided Batch 9","id":"q_batch9_6"},{"chapter":3,"topic":"Tipos de Revisi\xf3n","difficulty":"medium","question":"In your company, reviews are conducted with the following characteristics:\\n\\n- There is no defined role for a moderator.\\n- The main objective is to identify defects.\\n- An informal discussion is held among participants.\\n- No prior preparation of documents is required.\\n\\nWhat type of review is being described?","options":["Informal review","Walkthrough","Technical review","Inspection"],"correctAnswer":0,"explanation":"A. Correct. It is an informal review, as it requires no moderator and focuses on identifying defects through open discussion.\\nB. Incorrect. Walkthroughs require a author as a leader and a more structured approach, which is not mentioned here.\\nC. Incorrect. Technical reviews usually follow a more formal process, with defined roles and prior preparation.\\nD. Incorrect. Inspections are formal processes involving specific roles and a clear objective of finding defects, which does not apply here.","source":"User Provided Batch 9","id":"q_batch9_7"},{"chapter":3,"topic":"Tipos de Revisi\xf3n","difficulty":"medium","question":"In your organization, the following activities take place in a review:\\n\\n- No moderator is required.\\n- Participants review the work informally.\\n- No formal report is generated upon conclusion.\\n- Suggestions for improvement are discussed.\\n\\nWhich of the following types of review is MOST likely taking place?","options":["Informal review","Technical review","Inspection","Walkthrough"],"correctAnswer":0,"explanation":"A. Correct. Informal reviews do not require a moderator, do not produce formal reports, and allow open discussions, fitting the characteristics mentioned.\\nB. Incorrect. Technical reviews usually require a structured approach, which does not align with the given description.\\nC. Incorrect. Inspections are very formal and require specific documentation, contradicting the lack of a formal report in this case.\\nD. Incorrect. Walkthroughs are structured with the author leading, which is not present in the described situation.","source":"User Provided Batch 9","id":"q_batch9_8"}]')}}]);